INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C1','kor',5,2,'u2',1,'빠진 말이 뜻을 흐린다 — 문장에 꼭 있어야 할 말이 빠지면 누가 무엇을 어찌했는지 알 수 없어 읽는 사람이 짐작만 하게 된다',ARRAY['6국04-04 문법']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C2','kor',5,2,'u2',1,'매체의 뜻 — 휴대 전화 메시지 · 전자 우편 · 학급 누리집처럼 생각이나 정보를 전하는 도구를 매체라고 한다',ARRAY['6국03-04 쓰기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C3','kor',5,2,'u2',1,'단원의 흐름 — 문장을 이루는 말 → 말끼리 어울리게 쓰기(호응) → 경험을 글로 쓰기 → 매체의 특성 알기 → 매체에 알맞게 쓰기 → 칭찬 댓글로 의견 주고받기',ARRAY['6국04-04 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C4','kor',5,2,'u2',2,'주어 — 문장에서 움직이거나 어떠한 주인이 되는 말, 곧 「누가」나 「무엇이」에 해당하는 말이다',ARRAY['6국04-04 문법']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C5','kor',5,2,'u2',2,'서술어의 세 갈래 — 서술어는 어찌하는지(달린다) · 어떠한지(씩씩하다) · 무엇인지(5학년이다)를 알려 주는 말이다',ARRAY['6국04-04 문법']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C6','kor',5,2,'u2',2,'서술어는 문장의 중심 — 서술어가 없으면 뜻을 전할 수 없어서 서술어는 문장의 중심이며, 서술어를 먼저 보면 문장에 무엇이 필요한지 알 수 있다',ARRAY['6국04-04 문법']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C7','kor',5,2,'u2',2,'목적어 — 움직임의 대상이 되는 「무엇을」 · 「누구를」에 해당하는 말이다(내가 실내화를 잃어버렸어)',ARRAY['6국04-04 문법']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C8','kor',5,2,'u2',2,'서술어에 따라 꼭 있어야 하는 말 — 서술어를 보고 꼭 필요한 말을 판단한다 — 떠오르다(무엇이) · 마시다(누가 + 무엇을) · 넣다(+ 어디에) · 드리다(+ 누구에게)',ARRAY['6국04-04 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C9','kor',5,2,'u2',2,'목적어가 없어도 완전한 문장 — 「바람이 선선하다」 · 「해가 떠오른다」처럼 서술어에 따라 목적어 없이도 완전한 문장이 있다',ARRAY['6국04-04 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C10','kor',5,2,'u2',2,'주어의 여러 꼴 — 주어는 「이 · 가」뿐 아니라 「은 · 는」, 높일 때는 「께서」가 붙기도 하므로 붙은 말이 아니라 「누가 · 무엇이」를 물어 찾는다',ARRAY['6국04-04 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C11','kor',5,2,'u2',3,'호응의 뜻 — 앞에 오는 말에 어울리는 말이 뒤따르는 것을 호응이라 하고, 호응이 맞지 않으면 문장이 어색해진다',ARRAY['6국04-04 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C12','kor',5,2,'u2',3,'주어와 서술어의 호응 — 「새가 지저귄다」는 자연스럽지만 「강아지가 지저귄다」는 어색하듯 주어마다 어울리는 서술어가 있다',ARRAY['6국04-04 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C13','kor',5,2,'u2',3,'목적어와 서술어의 호응 — 모자는 쓰다, 양말은 신다, 장갑은 끼다, 목도리는 두르다, 김치는 담그다, 만두는 빚다처럼 목적어마다 어울리는 서술어가 있다',ARRAY['6국04-04 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C14','kor',5,2,'u2',3,'목적어가 둘일 때 — 두 목적어에 어울리는 서술어가 다르면 「장갑을 끼고 목도리를 두르고」처럼 각각 서술어를 쓴다',ARRAY['6국04-04 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C15','kor',5,2,'u2',3,'반드시 ~해야 한다 — 「반드시」 뒤에는 「~해야 한다」처럼 꼭 해야 함을 나타내는 말이 어울린다',ARRAY['6국04-04 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C16','kor',5,2,'u2',3,'전혀 · 별로 · 도저히 · 여간 + 부정 — 「전혀 · 별로 · 도저히 · 여간」 뒤에는 「~지 않다 · ~지 못하다 · ~이 아니다」처럼 부정하는 말이 와야 한다',ARRAY['6국04-04 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C17','kor',5,2,'u2',3,'왜냐하면 ~기 때문이다 — 「왜냐하면」으로 까닭을 말할 때에는 「~기 때문이다」로 맺는다',ARRAY['6국04-04 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C18','kor',5,2,'u2',3,'아마 ~ㄹ 것이다 — 「아마」는 짐작을 나타내므로 「~ㄹ 것이다」처럼 짐작하는 말과 어울린다',ARRAY['6국04-04 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C19','kor',5,2,'u2',3,'시간 표현의 호응 — 「어제」는 지난 일이라 「~했다」, 「내일」은 앞으로의 일이라 「~할 것이다」, 「지금」은 「~하고 있다」와 어울린다',ARRAY['6국04-04 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C20','kor',5,2,'u2',3,'높임 표현의 호응 — 높여야 할 분이 주어이면 「께서」와 함께 서술어에도 「-시-」를 넣어 「할머니께서 오셨다」처럼 쓴다',ARRAY['6국04-04 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C21','kor',5,2,'u2',3,'꿈은 ~는 것이다 — 「꿈은 · 소원은 · 목표는」으로 시작하면 「~는 것이다」로 맺어야 주어와 서술어가 어울린다',ARRAY['6국04-04 문법']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C22','kor',5,2,'u2',3,'어색한 까닭을 말하고 여러 가지로 고치기 — 어색한 문장은 틀렸다고 지적만 하지 않고 어색한 까닭을 말하며, 까닭이 맞으면 고친 문장은 여러 가지일 수 있다',ARRAY['6국04-04 문법']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C23','kor',5,2,'u2',5,'쓰기 전에 정할 것 — 어떤 글을 쓸지 · 누가 읽을지 · 무엇을 위해 쓸지를 먼저 정하고, 반 친구들이 읽는다면 공감할 수 있게 쉽고 생생하게 쓴다',ARRAY['6국03-04 쓰기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C24','kor',5,2,'u2',5,'글감 고르기 — 경험 글의 글감은 사건이 많은 일보다 그때의 느낌이 생생한 한 가지 일이 좋다',ARRAY['6국03-04 쓰기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C25','kor',5,2,'u2',5,'차례대로 정리하기 — 경험을 시간 차례나 장소가 바뀐 차례로 정리하고, 그때 한 말이나 든 느낌도 함께 메모한다',ARRAY['6국03-04 쓰기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C26','kor',5,2,'u2',5,'처음-가운데-끝 — 처음에는 언제 · 어디서 · 누구와, 가운데에는 일어난 일과 생각 · 느낌을 자세히, 끝에는 배우거나 느낀 점과 다짐을 쓴다',ARRAY['6국03-04 쓰기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C27','kor',5,2,'u2',5,'고쳐쓰기 — 빠진 말 · 겹친 말 · 어울리지 않는 말을 찾아 고치고, 제목 · 생생함 · 생각과 느낌이 잘 드러났는지도 확인한다',ARRAY['6국04-04 문법']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C28','kor',5,2,'u2',5,'친구 글 읽고 의견 나누기 — 모둠 친구의 글을 읽고 인상 깊은 장면 · 공감한 부분 · 궁금한 점을 이야기한다',ARRAY['6국03-04 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C29','kor',5,2,'u2',7,'상황에 알맞은 매체 — 매체는 읽을 사람과 상황에 따라 골라야 하며, 어느 한 매체가 언제나 가장 좋은 것은 아니다',ARRAY['6국03-04 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C30','kor',5,2,'u2',7,'휴대 전화 메시지의 특성 — 직접 만나지 않아도 빠르게 주고받고, 실제 대화처럼 짧고 친근한 말과 그림말로 기분을 나타낼 수 있다',ARRAY['6국03-04 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C31','kor',5,2,'u2',7,'전자 우편의 특성 — 받는 사람 주소를 정확히 쓰고, 제목만 보고 내용을 짐작하게 쓰며, 첫인사 · 끝인사를 갖추고 글 · 그림을 첨부해 공식적으로 보낼 수 있다',ARRAY['6국03-04 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C32','kor',5,2,'u2',7,'학급 누리집의 특성 — 같은 반 선생님 · 학생 · 학부모가 함께 보는 공간으로, 댓글로 의견을 주고받고 글이 오래 기록으로 남는다',ARRAY['6국03-04 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C33','kor',5,2,'u2',7,'학급 누리집에서 지킬 점 — 올바른 맞춤법과 문장으로 쓰고, 개인 정보를 올리지 않으며, 가져온 글 · 사진은 허락받고 출처를 밝히고, 누가 썼는지 알 수 있게 쓴다',ARRAY['6국03-04 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C34','kor',5,2,'u2',9,'매체에 따라 달라지는 글 — 반 친구들과 함께 정하자고 제안하는 글은 의견을 한곳에 모아 견줄 수 있는 학급 누리집이 알맞고, 매체가 바뀌면 글의 짜임과 표현도 달라진다',ARRAY['6국03-04 쓰기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C35','kor',5,2,'u2',9,'제목 붙이기 — 누리집에는 글이 많아 제목을 보고 읽을지 정하므로 흥미를 끌면서 핵심을 담아 쓰고, 내용과 어긋나거나 자극적이기만 한 제목은 피한다',ARRAY['6국03-04 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C36','kor',5,2,'u2',9,'자료와 출처 — 글에 쓸 자료는 믿을 만하고 새로운 것을 고르고, 가져온 자료는 출처를 밝힌다',ARRAY['6국03-04 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C37','kor',5,2,'u2',9,'매체 글의 짜임 — 처음에는 문제 상황과 쓴 까닭, 가운데에는 사진 · 그림을 곁들인 제안, 끝에는 정리와 댓글 참여 안내를 쓴다',ARRAY['6국03-04 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C38','kor',5,2,'u2',9,'고쳐쓰기 기준 만들기 — 매체의 특성 · 목적과 읽을 사람 · 제목 · 문장 성분의 호응처럼 내가 만든 기준으로 확인하고, 글자 크기 · 줄 간격도 살핀다',ARRAY['6국03-04 쓰기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C39','kor',5,2,'u2',12,'댓글 기능과 올리기 전 확인 — 댓글을 쓰고 · 고치고 · 지우는 방법을 익히고, 여러 사람이 보는 글이므로 올리기 전에 한 번 더 읽고 예절을 확인한다',ARRAY['6국03-04 쓰기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C40','kor',5,2,'u2',12,'칭찬할 곳 찾기 — 글 전체(주제 · 제목) · 문단(차례 · 자료) · 문장과 낱말(호응 · 표현)에서 어디가 왜 좋은지 찾아 메모한다',ARRAY['6국03-04 쓰기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C41','kor',5,2,'u2',12,'구체적인 칭찬 댓글 — 막연한 「좋아요」보다 글의 내용이나 표현을 근거로 들어 어떤 점이 왜 좋은지 쓰며, 틀 문장은 내 말로 채워 쓴다',ARRAY['6국03-04 쓰기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C42','kor',5,2,'u2',12,'장점을 중심으로 — 칭찬 댓글 활동에서는 틀린 곳을 지적하지 않고 장점을 중심으로 쓴다',ARRAY['6국03-04 쓰기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C43','kor',5,2,'u2',12,'디지털 안내문 만들기 — 알리고 싶은 내용과 읽을 사람을 먼저 정하고 글 · 그림 · 사진 · 기호를 넣어 만든 뒤 잘 전달되었는지 살핀다',ARRAY['6국03-04 쓰기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u2-C44','kor',5,2,'u2',14,'온라인 대화 예절 — 모르는 사람이 사진 · 전화번호 · 주소를 달라고 하면 정중하지만 분명하게 거절하고, 이상한 메시지는 어른께 알린다 (기초 다지기)',ARRAY['기초 다지기(온라인 대화 예절)']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X01','kor',5,'u2',ARRAY['K5-2-u2-C1']::text[],'꼭 있어야 할 말이 빠져도 읽는 사람이 알아서 짐작하니 뜻이 다 통한다고 여긴다','누가? 무엇을? 어찌했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X02','kor',5,'u2',ARRAY['K5-2-u2-C2']::text[],'매체를 생각이나 정보를 전하는 도구로 보지 않고 글쓰기와 관계없는 것으로 여긴다','전하는 도구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X03','kor',5,'u2',ARRAY['K5-2-u2-C3']::text[],'단원에서 배우는 차례를 거꾸로 알거나 문장 공부와 매체 공부가 서로 관계없다고 여긴다','문장 → 글 → 매체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X04','kor',5,'u2',ARRAY['K5-2-u2-C4','K5-2-u2-C10']::text[],'「이 · 가」가 붙은 말만 주어라 여겨 「은 · 는 · 께서」가 붙은 주어를 놓친다','누가 · 무엇이를 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X05','kor',5,'u2',ARRAY['K5-2-u2-C5']::text[],'움직임을 나타내는 말만 서술어라 여겨 「어떠하다 · 무엇이다」를 서술어로 보지 않는다','세 갈래 서술어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X06','kor',5,'u2',ARRAY['K5-2-u2-C6','K5-2-u2-C4']::text[],'서술어가 없어도 뜻이 전해진다고 여기거나 주어와 서술어를 헷갈린다','서술어는 중심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X07','kor',5,'u2',ARRAY['K5-2-u2-C7']::text[],'「무엇을 · 누구를」에 해당하는 목적어를 주어와 헷갈린다','무엇을?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X08','kor',5,'u2',ARRAY['K5-2-u2-C9']::text[],'모든 문장에는 반드시 목적어가 있어야 한다고 여긴다','서술어마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X09','kor',5,'u2',ARRAY['K5-2-u2-C8']::text[],'서술어와 관계없이 주어와 서술어만 있으면 완전하다고 여겨 「어디에 · 누구에게」 말을 빠뜨린다','서술어를 보고 판단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X10','kor',5,'u2',ARRAY['K5-2-u2-C11']::text[],'호응을 맞춤법이나 띄어쓰기 문제로 여긴다','말끼리 어울림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X11','kor',5,'u2',ARRAY['K5-2-u2-C12']::text[],'문장에 말만 다 있으면 주어와 서술어가 어울리지 않아도 괜찮다고 여긴다','주어에 맞는 서술어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X12','kor',5,'u2',ARRAY['K5-2-u2-C13']::text[],'목적어마다 어울리는 서술어를 가리지 않는다(모자를 신다)','쓰다 · 신다 · 끼다 · 두르다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X13','kor',5,'u2',ARRAY['K5-2-u2-C14']::text[],'서술어가 다른 두 목적어를 서술어 하나로 묶어 쓴다(장갑과 목도리를 끼다)','각각 어울리는 서술어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X14','kor',5,'u2',ARRAY['K5-2-u2-C15']::text[],'「반드시」 뒤에 「~해도 된다 · ~하지 않아도 된다」를 쓴다','반드시 ~해야 한다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X15','kor',5,'u2',ARRAY['K5-2-u2-C16']::text[],'「전혀 · 별로 · 도저히 · 여간」 뒤에 부정하는 말 없이 쓴다','뒤에 부정하는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X16','kor',5,'u2',ARRAY['K5-2-u2-C17']::text[],'「왜냐하면」으로 시작하고 「~이다 · ~했다」로 맺는다','~기 때문이다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X17','kor',5,'u2',ARRAY['K5-2-u2-C18']::text[],'「아마」 뒤에 이미 일어난 일이나 확실한 일을 나타내는 말을 쓴다','짐작하는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X18','kor',5,'u2',ARRAY['K5-2-u2-C19']::text[],'때를 나타내는 말과 서술어의 시간이 어긋나게 쓴다(어제 갈 것이다)','어제는 ~했다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X19','kor',5,'u2',ARRAY['K5-2-u2-C20']::text[],'「께서」만 넣고 서술어는 높이지 않거나, 높일 분을 「이 · 가」로 쓴다','께서 + -시-') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X20','kor',5,'u2',ARRAY['K5-2-u2-C21']::text[],'「꿈은 · 소원은」으로 시작하고 「~하고 싶다」로 맺는다','~는 것이다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X21','kor',5,'u2',ARRAY['K5-2-u2-C22']::text[],'어색한 문장을 고친 답은 하나뿐이라 여기거나, 어색한 까닭은 말하지 않고 틀렸다고만 한다','까닭 · 여러 표현') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X22','kor',5,'u2',ARRAY['K5-2-u2-C23']::text[],'누가 읽을지 · 무엇을 위해 쓸지 정하지 않고 바로 쓴다','목적 · 읽을 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X23','kor',5,'u2',ARRAY['K5-2-u2-C24']::text[],'경험 글의 글감은 사건이 많을수록 좋다고 여긴다','느낌이 생생한 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X24','kor',5,'u2',ARRAY['K5-2-u2-C25']::text[],'차례를 섞어 정리하거나 일어난 사실만 적고 그때의 말 · 느낌을 빠뜨린다','차례 + 느낌 한 줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X25','kor',5,'u2',ARRAY['K5-2-u2-C26']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 헷갈리거나, 가장 인상 깊은 장면을 처음에 길게 쓴다','가운데를 자세히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X26','kor',5,'u2',ARRAY['K5-2-u2-C27']::text[],'고쳐쓰기는 맞춤법만 고치는 일이라 여기거나 고칠 곳이 없다고 여긴다','빠진 · 겹친 · 어울리지 않는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X27','kor',5,'u2',ARRAY['K5-2-u2-C28']::text[],'친구 글을 읽고 공감이나 궁금한 점 없이 글씨 · 틀린 곳만 말한다','인상 · 공감 · 궁금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X28','kor',5,'u2',ARRAY['K5-2-u2-C29']::text[],'어느 한 매체가 언제나 가장 좋다고 여겨 상황을 살피지 않는다','읽을 사람과 상황') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X29','kor',5,'u2',ARRAY['K5-2-u2-C30','K5-2-u2-C31']::text[],'메시지와 전자 우편의 특성을 바꾸어 알거나, 메시지에 그림말 · 줄임말만 가득 쓴다','빠르게 · 공식적으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X30','kor',5,'u2',ARRAY['K5-2-u2-C31']::text[],'전자 우편에 제목 · 인사 없이 쓰거나 받는 사람 주소를 대충 써도 된다고 여긴다','주소 · 제목 · 인사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X31','kor',5,'u2',ARRAY['K5-2-u2-C32','K5-2-u2-C33']::text[],'학급 누리집은 아무렇게나 써도 된다고 여겨 개인 정보를 올리거나 이름 없이 남을 깎아내린다','함께 보는 공간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X32','kor',5,'u2',ARRAY['K5-2-u2-C35']::text[],'제목은 내용과 달라도 자극적으로 눈길만 끌면 된다고 여긴다','흥미 + 핵심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X33','kor',5,'u2',ARRAY['K5-2-u2-C36']::text[],'인터넷에서 찾은 글 · 그림을 출처 없이 내 것처럼 쓴다','출처를 밝혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X34','kor',5,'u2',ARRAY['K5-2-u2-C37','K5-2-u2-C34']::text[],'매체가 바뀌어도 글의 짜임이 같다고 여기거나, 누리집 글을 「끝.」으로 맺고 참여 안내를 빠뜨린다','끝에 댓글 안내') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X35','kor',5,'u2',ARRAY['K5-2-u2-C41','K5-2-u2-C40']::text[],'칭찬 댓글을 「좋아요」처럼 근거 없이 쓰거나 틀 문장의 빈칸을 채우지 않는다','어디가 왜 좋은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X36','kor',5,'u2',ARRAY['K5-2-u2-C42']::text[],'칭찬 댓글 활동에서 틀린 곳을 찾아 지적한다','오늘은 장점만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X37','kor',5,'u2',ARRAY['K5-2-u2-C39']::text[],'올린 뒤 고치면 된다고 여겨 댓글을 다시 읽지 않고 바로 올린다','올리기 전에 한 번 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X38','kor',5,'u2',ARRAY['K5-2-u2-C43']::text[],'안내문을 만들 때 읽을 사람과 내용보다 꾸미기를 먼저 한다','내용 · 읽을 사람 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X39','kor',5,'u2',ARRAY['K5-2-u2-C44']::text[],'모르는 사람에게 개인 정보나 사진을 보내거나, 온라인은 무조건 쓰면 안 된다고만 여긴다','정중히 거절 · 어른께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u2-X40','kor',5,'u2',ARRAY['K5-2-u2-C38']::text[],'고쳐쓰기 기준 없이 고치거나 글 길이 같은 엉뚱한 기준을 세운다','매체 · 목적 · 제목 · 호응') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#1','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C1',1,'mc','auto','「대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.」처럼 빈칸이 있으면 무엇을 알 수 없나요?',ARRAY['K5-2-u2-X01']::text[],false,'{"seq":1,"concept":"K5-2-u2-C1","difficulty":1,"kind":"mc","stem":"「대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.」처럼 빈칸이 있으면 무엇을 알 수 없나요?","options":[{"t":"누가 우리를 맞아 주었는지","correct":true},{"t":"언제 이모 댁에 갔는지","mis":"K5-2-u2-X01"},{"t":"무엇을 타고 갔는지","mis":"K5-2-u2-X01"},{"t":"누구와 함께 갔는지","mis":"K5-2-u2-X01"}],"explanation":["「지난 토요일」에 나와요.","「버스」에 나와요.","빈칸이 바로 맞아 준 사람 자리예요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 동생과 함께 이모 댁에 다녀왔다.","오랜만에 뵙는 이모 생각에 버스 안에서 내내 가슴이 콩닥거렸다.","대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.","나는 반가운 마음에 이모를 ( ? )."],"title":"경험을 쓴 글 「이모 댁에 다녀온 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#2','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C1',1,'ox','auto','문장에 꼭 있어야 할 말이 빠져도 읽는 사람은 뜻을 다 알 수 있어요.',ARRAY['K5-2-u2-X01']::text[],false,'{"seq":2,"concept":"K5-2-u2-C1","difficulty":1,"kind":"ox","stem":"문장에 꼭 있어야 할 말이 빠져도 읽는 사람은 뜻을 다 알 수 있어요.","answer":"X","reason_options":[{"t":"누가 무엇을 어찌했는지 알 수 없어 뜻이 흐려지기 때문에","correct":true},{"t":"읽는 사람이 알아서 짐작하면 되기 때문에","mis":"K5-2-u2-X01"}],"mis":"K5-2-u2-X01","explanation":["짐작은 틀릴 수 있어요.","빠진 말이 뜻을 흐려요.","꼭 필요한 말은 써야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#3','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C1',1,'blank','auto','「나는 반가운 마음에 이모를 ( ? ).」의 빈칸에 들어갈 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X01']::text[],false,'{"seq":3,"concept":"K5-2-u2-C1","difficulty":1,"kind":"blank","stem":"「나는 반가운 마음에 이모를 ( ? ).」의 빈칸에 들어갈 말로 알맞은 것은 어느 것인가요?","options":[{"t":"와락 껴안았다","correct":true},{"t":"이모께서","mis":"K5-2-u2-X07"},{"t":"버스 안에서","mis":"K5-2-u2-X01"},{"t":"지난 토요일","mis":"K5-2-u2-X01"}],"explanation":["이모는 이미 앞에 있어요.","어디서인지는 알아요.","무엇을 어찌했는지가 빠졌어요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 동생과 함께 이모 댁에 다녀왔다.","오랜만에 뵙는 이모 생각에 버스 안에서 내내 가슴이 콩닥거렸다.","대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.","나는 반가운 마음에 이모를 ( ? )."],"title":"경험을 쓴 글 「이모 댁에 다녀온 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#4','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C2',1,'mc','auto','휴대 전화 메시지 · 전자 우편 · 학급 누리집처럼 생각이나 정보를 전하는 도구를 무엇이라고 하나요?',ARRAY['K5-2-u2-X03','K5-2-u2-X10']::text[],false,'{"seq":4,"concept":"K5-2-u2-C2","difficulty":1,"kind":"mc","stem":"휴대 전화 메시지 · 전자 우편 · 학급 누리집처럼 생각이나 정보를 전하는 도구를 무엇이라고 하나요?","options":[{"t":"매체","correct":true},{"t":"문장 성분","mis":"K5-2-u2-X03"},{"t":"호응","mis":"K5-2-u2-X10"},{"t":"개요","mis":"K5-2-u2-X03"}],"explanation":["문장을 이루는 말이에요.","말끼리 어울리는 것이에요.","전하는 도구를 매체라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#5','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C1',2,'mc','auto','「이모 댁에 다녀온 날」의 두 빈칸을 채우면 무엇이 분명해지나요?',ARRAY['K5-2-u2-X01','K5-2-u2-X03']::text[],false,'{"seq":5,"concept":"K5-2-u2-C1","difficulty":2,"kind":"mc","stem":"「이모 댁에 다녀온 날」의 두 빈칸을 채우면 무엇이 분명해지나요?","options":[{"t":"누가 맞아 주었고, 내가 이모를 어찌했는지","correct":true},{"t":"글쓴이가 몇 학년인지","mis":"K5-2-u2-X01"},{"t":"이모 댁이 어느 동네인지","mis":"K5-2-u2-X01"},{"t":"글의 제목이 무엇인지","mis":"K5-2-u2-X03"}],"explanation":["빈칸과 관계없어요.","빈칸과 관계없어요.","누가 · 어찌했는지가 채워져요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 동생과 함께 이모 댁에 다녀왔다.","오랜만에 뵙는 이모 생각에 버스 안에서 내내 가슴이 콩닥거렸다.","대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.","나는 반가운 마음에 이모를 ( ? )."],"title":"경험을 쓴 글 「이모 댁에 다녀온 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#6','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C2',2,'mc','auto','하윤이가 매체로 의견을 나누며 어려웠던 점은 무엇인가요?',ARRAY['K5-2-u2-X02']::text[],false,'{"seq":6,"concept":"K5-2-u2-C2","difficulty":2,"kind":"mc","stem":"하윤이가 매체로 의견을 나누며 어려웠던 점은 무엇인가요?","options":[{"t":"댓글에 줄임말이 많아 뜻이 헷갈렸다","correct":true},{"t":"친구들이 댓글을 달아 주었다","mis":"K5-2-u2-X02"},{"t":"전학 간 친구가 안부를 보냈다","mis":"K5-2-u2-X02"},{"t":"독서 감상문을 쓰지 못했다","mis":"K5-2-u2-X02"}],"explanation":["그건 좋았던 점이에요.","그건 준서의 경험이에요.","줄임말 때문에 헷갈렸어요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"학급 누리집에 독서 감상문을 올렸더니 친구들이 댓글을 달아 줘서 좋았어."},{"who":"준서","text":"나는 전학 간 친구가 휴대 전화 메시지로 안부를 보내 줘서 반가웠어."},{"who":"하윤","text":"그런데 댓글에 줄임말이 너무 많아서 무슨 뜻인지 헷갈린 적도 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#7','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C3',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u2-C3","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"문장 성분","r":"문장을 이루는 말 알기"},{"l":"호응","r":"말끼리 어울리게 쓰기"},{"l":"매체에 알맞게 쓰기","r":"읽을 사람과 매체를 생각하며 쓰기"}],"mis":"K5-2-u2-X03","explanation":["문장의 뼈대를 알아요.","어울리는 말을 골라요.","매체에 맞춰 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#8','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C1',2,'error','auto','이모 댁 이야기를 친구에게 전한 말이에요. 뜻이 가장 흐린 것은 어느 것인가요?',ARRAY['K5-2-u2-X01','K5-2-u2-X04','K5-2-u2-X09']::text[],false,'{"seq":8,"concept":"K5-2-u2-C1","difficulty":2,"kind":"error","stem":"이모 댁 이야기를 친구에게 전한 말이에요. 뜻이 가장 흐린 것은 어느 것인가요?","options":[{"t":"「대문을 열자 우리를 반갑게 맞아 주셨어.」","correct":true,"mis_target":"K5-2-u2-X01"},{"t":"「이모께서 대문 앞에서 우리를 맞아 주셨어.」","mis":"K5-2-u2-X04"},{"t":"「나는 반가워서 이모를 와락 껴안았어.」","mis":"K5-2-u2-X09"}],"explanation":["누가 맞아 주었는지 있어요.","어찌했는지 있어요.","누가 맞아 주었는지 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#9','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C3',2,'mc','auto','이 단원에서 경험을 글로 쓴 다음에 배우는 내용은 어느 것인가요?',ARRAY['K5-2-u2-X03']::text[],false,'{"seq":9,"concept":"K5-2-u2-C3","difficulty":2,"kind":"mc","stem":"이 단원에서 경험을 글로 쓴 다음에 배우는 내용은 어느 것인가요?","options":[{"t":"매체의 특성을 알고 매체에 알맞게 글 쓰기","correct":true},{"t":"문장을 이루는 말 처음 알아보기","mis":"K5-2-u2-X03"},{"t":"시를 읽고 인상적인 부분 말하기","mis":"K5-2-u2-X03"},{"t":"토론 절차 익히기","mis":"K5-2-u2-X03"}],"explanation":["그건 맨 처음에 배워요.","그건 지난 단원이에요.","경험 글 다음은 매체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_basic#10','kor',5,2,'u2','L01','g5_2_kor_u2_L01_basic','lesson_basic','K5-2-u2-C1',3,'mc','auto','경험을 쓴 글에서 꼭 있어야 할 말을 빠뜨리지 않으려면 어떻게 하는 것이 가장 좋을까요?',ARRAY['K5-2-u2-X26','K5-2-u2-X01']::text[],false,'{"seq":10,"concept":"K5-2-u2-C1","difficulty":3,"kind":"mc","stem":"경험을 쓴 글에서 꼭 있어야 할 말을 빠뜨리지 않으려면 어떻게 하는 것이 가장 좋을까요?","options":[{"t":"다 쓴 뒤 「누가? 무엇을? 어찌했나?」를 물으며 다시 읽는다","correct":true},{"t":"다 쓰면 다시 읽지 않고 바로 낸다","mis":"K5-2-u2-X26"},{"t":"문장을 될 수 있는 대로 짧게 줄인다","mis":"K5-2-u2-X01"},{"t":"어려운 낱말을 많이 넣는다","mis":"K5-2-u2-X01"}],"explanation":["다시 읽어야 찾아요.","짧게 줄이면 더 빠져요.","물음으로 빠진 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#1','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C2',2,'mc','auto','다음 가운데 매체를 활용한 경험이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u2-X02']::text[],false,'{"seq":1,"concept":"K5-2-u2-C2","difficulty":2,"kind":"mc","stem":"다음 가운데 매체를 활용한 경험이 아닌 것은 어느 것인가요?","options":[{"t":"쉬는 시간에 짝과 마주 보고 이야기했다","correct":true},{"t":"전자 우편으로 대회에 그림을 보냈다","mis":"K5-2-u2-X02"},{"t":"학급 누리집에 사진을 올렸다","mis":"K5-2-u2-X02"},{"t":"휴대 전화 메시지로 약속을 바꿨다","mis":"K5-2-u2-X02"}],"explanation":["전자 우편도 매체예요.","학급 누리집도 매체예요.","마주 보고 말한 것은 도구를 거치지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#2','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C3',2,'ox','auto','이 단원에서는 문장을 바르게 쓰는 법과 매체에 알맞게 글 쓰는 법을 함께 배워요.',ARRAY['K5-2-u2-X03']::text[],false,'{"seq":2,"concept":"K5-2-u2-C3","difficulty":2,"kind":"ox","stem":"이 단원에서는 문장을 바르게 쓰는 법과 매체에 알맞게 글 쓰는 법을 함께 배워요.","answer":"O","reason_options":[{"t":"올바른 문장으로 경험을 쓴 뒤 매체에 알맞게 쓰는 데까지 넓혀 가기 때문에","correct":true},{"t":"문장 공부와 매체 공부는 서로 관계없기 때문에","mis":"K5-2-u2-X03"}],"mis":"K5-2-u2-X03","explanation":["둘은 이어져요.","바른 문장이 매체 글의 바탕이에요.","함께 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#3','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C1',3,'mc','auto','「나는 반가운 마음에 이모를.」처럼 끝말이 빠진 문장의 가장 큰 문제는 무엇인가요?',ARRAY['K5-2-u2-X01','K5-2-u2-X26']::text[],false,'{"seq":3,"concept":"K5-2-u2-C1","difficulty":3,"kind":"mc","stem":"「나는 반가운 마음에 이모를.」처럼 끝말이 빠진 문장의 가장 큰 문제는 무엇인가요?","options":[{"t":"내가 이모에게 무엇을 했는지 알 수 없다","correct":true},{"t":"글자 수가 너무 적다","mis":"K5-2-u2-X01"},{"t":"이모가 누구인지 알 수 없다","mis":"K5-2-u2-X01"},{"t":"쉼표가 없다","mis":"K5-2-u2-X26"}],"explanation":["길이가 문제가 아니에요.","이모는 알 수 있어요.","어찌했는지가 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#4','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C30',3,'mc','auto','준서가 휴대 전화 메시지에서 좋았던 점과 가장 관계있는 매체의 특성은 무엇인가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X29']::text[],false,'{"seq":4,"concept":"K5-2-u2-C30","difficulty":3,"kind":"mc","stem":"준서가 휴대 전화 메시지에서 좋았던 점과 가장 관계있는 매체의 특성은 무엇인가요?","options":[{"t":"직접 만나지 않아도 빠르게 마음을 전할 수 있다","correct":true},{"t":"반 친구들 모두가 오래 기록으로 본다","mis":"K5-2-u2-X28"},{"t":"제목과 첨부 자료를 갖춘다","mis":"K5-2-u2-X29"},{"t":"여러 사람의 의견을 한곳에 모은다","mis":"K5-2-u2-X28"}],"explanation":["그건 학급 누리집이에요.","그건 전자 우편이에요.","메시지는 빠르게 전해요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"학급 누리집에 독서 감상문을 올렸더니 친구들이 댓글을 달아 줘서 좋았어."},{"who":"준서","text":"나는 전학 간 친구가 휴대 전화 메시지로 안부를 보내 줘서 반가웠어."},{"who":"하윤","text":"그런데 댓글에 줄임말이 너무 많아서 무슨 뜻인지 헷갈린 적도 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#5','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C3',3,'error','auto','단원 공부 계획을 세운 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u2-X03','K5-2-u2-X10','K5-2-u2-X28']::text[],false,'{"seq":5,"concept":"K5-2-u2-C3","difficulty":3,"kind":"error","stem":"단원 공부 계획을 세운 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「매체 공부를 먼저 하고 문장 성분은 맨 끝에 배울 거야.」","correct":true,"mis_target":"K5-2-u2-X03"},{"t":"「문장을 이루는 말부터 알아보고 말끼리 어울리게 쓰는 법을 익힐래.」","mis":"K5-2-u2-X10"},{"t":"「경험을 쓴 글을 매체에 알맞게 바꿔 올려 볼래.」","mis":"K5-2-u2-X28"}],"explanation":["차례에 맞아요.","단원의 끝에서 하는 일이에요.","문장 성분이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#6','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C1',3,'mc','auto','빈칸이 있는 「이모 댁에 다녀온 날」을 읽은 친구의 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X01','K5-2-u2-X11']::text[],false,'{"seq":6,"concept":"K5-2-u2-C1","difficulty":3,"kind":"mc","stem":"빈칸이 있는 「이모 댁에 다녀온 날」을 읽은 친구의 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「빈칸이 있으니 누가 무엇을 했는지 짐작만 하게 돼.」","correct":true},{"t":"「빈칸이 있어도 글의 뜻은 똑같아.」","mis":"K5-2-u2-X01"},{"t":"「빈칸에는 아무 말이나 넣으면 돼.」","mis":"K5-2-u2-X11"},{"t":"「빈칸은 글을 짧게 하려고 일부러 뺀 거야.」","mis":"K5-2-u2-X01"}],"explanation":["뜻이 흐려져요.","어울리는 말을 넣어야 해요.","빈칸이 뜻을 흐려요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 동생과 함께 이모 댁에 다녀왔다.","오랜만에 뵙는 이모 생각에 버스 안에서 내내 가슴이 콩닥거렸다.","대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.","나는 반가운 마음에 이모를 ( ? )."],"title":"경험을 쓴 글 「이모 댁에 다녀온 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#7','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C23',3,'mc','auto','매체로 글을 쓸 때 가장 먼저 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X29','K5-2-u2-X22']::text[],false,'{"seq":7,"concept":"K5-2-u2-C23","difficulty":3,"kind":"mc","stem":"매체로 글을 쓸 때 가장 먼저 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 읽을지와 무엇을 위해 쓰는지","correct":true},{"t":"가장 새로 나온 매체가 무엇인지","mis":"K5-2-u2-X28"},{"t":"그림말을 몇 개 넣을지","mis":"K5-2-u2-X29"},{"t":"글자를 얼마나 크게 쓸지","mis":"K5-2-u2-X22"}],"explanation":["새것이 늘 알맞지는 않아요.","그림말은 나중 일이에요.","읽을 사람과 목적이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#8','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C1',4,'essay','teacher','「이모 댁에 다녀온 날」의 두 빈칸을 채워 문장을 완성하고, 빈칸을 채우니 무엇이 분명해졌는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C1","difficulty":4,"kind":"essay","stem":"「이모 댁에 다녀온 날」의 두 빈칸을 채워 문장을 완성하고, 빈칸을 채우니 무엇이 분명해졌는지 쓰세요.","answer_guide":{"answer":"예: 대문을 열자 이모께서 우리를 반갑게 맞아 주셨다. 나는 반가운 마음에 이모를 와락 껴안았다. 빈칸을 채우니 누가 우리를 맞아 주었는지와 내가 이모를 어떻게 했는지가 분명해져 장면이 눈앞에 그려진다.","scoring_points":["두 빈칸을 알맞게 채웠는가","누가 맞아 주었는지가 분명해졌다고 썼는가","무엇을 어찌했는지가 분명해졌다고 썼는가"]},"explanation":["빈칸에 알맞은 말을 넣어요.","누가가 채워져요.","어찌했는지가 채워져요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 동생과 함께 이모 댁에 다녀왔다.","오랜만에 뵙는 이모 생각에 버스 안에서 내내 가슴이 콩닥거렸다.","대문을 열자 ( ? ) 우리를 반갑게 맞아 주셨다.","나는 반가운 마음에 이모를 ( ? )."],"title":"경험을 쓴 글 「이모 댁에 다녀온 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#9','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C2',4,'essay','teacher','매체로 글을 쓰거나 의견을 나누었던 경험을 하나 떠올려, 어떤 매체였는지와 좋았던 점 · 어려웠던 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C2","difficulty":4,"kind":"essay","stem":"매체로 글을 쓰거나 의견을 나누었던 경험을 하나 떠올려, 어떤 매체였는지와 좋았던 점 · 어려웠던 점을 쓰세요.","answer_guide":{"answer":"예: 학급 누리집에 모둠 발표 자료를 올린 적이 있다. 친구들이 댓글로 궁금한 점을 물어 와서 발표 전에 내용을 보탤 수 있어 좋았다. 하지만 짧은 댓글은 무슨 뜻인지 헷갈려 다시 물어봐야 했던 점이 어려웠다.","scoring_points":["매체를 밝혔는가","좋았던 점을 썼는가","어려웠던 점을 썼는가"]},"explanation":["매체 이름을 써요.","좋았던 점을 떠올려요.","어려웠던 점도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L01_challenge#10','kor',5,2,'u2','L01','g5_2_kor_u2_L01_challenge','lesson_challenge','K5-2-u2-C3',4,'essay','teacher','이 단원에서 배울 「문장 성분 · 호응」과 「매체에 알맞게 쓰기」가 서로 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C3","difficulty":4,"kind":"essay","stem":"이 단원에서 배울 「문장 성분 · 호응」과 「매체에 알맞게 쓰기」가 서로 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 매체에 올린 글도 모두 문장으로 이루어지므로 문장에 꼭 필요한 말이 빠지거나 말끼리 어울리지 않으면 읽는 사람이 뜻을 오해한다. 그래서 먼저 올바른 문장을 쓰는 법을 익히고, 그 문장으로 읽을 사람과 매체에 알맞은 글을 써야 생각이 제대로 전해진다.","scoring_points":["올바른 문장이 매체 글의 바탕임을 썼는가","문장이 어색하면 생기는 문제를 썼는가","둘을 이어 정리했는가"]},"explanation":["문장이 바탕이에요.","어색하면 오해가 생겨요.","둘을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#1','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C4',1,'mc','auto','「기차가 달린다.」에서 주어는 어느 것인가요?',ARRAY['K5-2-u2-X06','K5-2-u2-X04']::text[],false,'{"seq":1,"concept":"K5-2-u2-C4","difficulty":1,"kind":"mc","stem":"「기차가 달린다.」에서 주어는 어느 것인가요?","options":[{"t":"기차가","correct":true},{"t":"달린다","mis":"K5-2-u2-X06"},{"t":"기차가 달린다","mis":"K5-2-u2-X04"},{"t":"주어가 없다","mis":"K5-2-u2-X04"}],"explanation":["그건 서술어예요.","문장 전체예요.","누가 · 무엇이에 해당하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#2','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C5',1,'mc','auto','「귤이 새콤하다.」에서 「새콤하다」는 무엇을 알려 주나요?',ARRAY['K5-2-u2-X05','K5-2-u2-X06']::text[],false,'{"seq":2,"concept":"K5-2-u2-C5","difficulty":1,"kind":"mc","stem":"「귤이 새콤하다.」에서 「새콤하다」는 무엇을 알려 주나요?","options":[{"t":"귤이 어떠한지","correct":true},{"t":"귤이 어찌하는지","mis":"K5-2-u2-X05"},{"t":"귤이 무엇인지","mis":"K5-2-u2-X05"},{"t":"누가 귤을 먹는지","mis":"K5-2-u2-X06"}],"explanation":["움직임이 아니에요.","무엇이다가 아니에요.","맛이 어떠한지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#3','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C7',1,'blank','auto','「내가 (     ) 잃어버렸어.」의 빈칸에는 「무엇을」에 해당하는 말이 들어가요. 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X09','K5-2-u2-X06']::text[],false,'{"seq":3,"concept":"K5-2-u2-C7","difficulty":1,"kind":"blank","stem":"「내가 (     ) 잃어버렸어.」의 빈칸에는 「무엇을」에 해당하는 말이 들어가요. 알맞은 말은 어느 것인가요?","options":[{"t":"실내화를","correct":true},{"t":"실내화가","mis":"K5-2-u2-X07"},{"t":"어제","mis":"K5-2-u2-X09"},{"t":"잃어버렸다","mis":"K5-2-u2-X06"}],"explanation":["「무엇이」 꼴이에요.","언제인지 알려 주는 말이에요.","무엇을 잃어버렸는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#4','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C6',1,'ox','auto','서술어는 문장의 중심이라서 서술어가 빠지면 뜻을 전하기 어려워요.',ARRAY['K5-2-u2-X06']::text[],false,'{"seq":4,"concept":"K5-2-u2-C6","difficulty":1,"kind":"ox","stem":"서술어는 문장의 중심이라서 서술어가 빠지면 뜻을 전하기 어려워요.","answer":"O","reason_options":[{"t":"서술어가 어찌하는지 · 어떠한지 · 무엇인지를 알려 주기 때문에","correct":true},{"t":"서술어는 언제나 문장 맨 앞에 오기 때문에","mis":"K5-2-u2-X06"}],"mis":"K5-2-u2-X06","explanation":["서술어가 뜻을 맺어요.","빠지면 뜻이 끊겨요.","서술어는 대개 끝에 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#5','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C8',2,'mc','auto','「윤아가 마신다.」에서 뜻이 온전하려면 더 있어야 할 말은 무엇인가요?',ARRAY['K5-2-u2-X09','K5-2-u2-X04']::text[],false,'{"seq":5,"concept":"K5-2-u2-C8","difficulty":2,"kind":"mc","stem":"「윤아가 마신다.」에서 뜻이 온전하려면 더 있어야 할 말은 무엇인가요?","options":[{"t":"무엇을 마시는지 (예: 우유를)","correct":true},{"t":"언제 마시는지 (예: 아침에)","mis":"K5-2-u2-X09"},{"t":"어떻게 마시는지 (예: 천천히)","mis":"K5-2-u2-X09"},{"t":"누가 마시는지 (예: 윤아가)","mis":"K5-2-u2-X04"}],"explanation":["없어도 뜻은 통해요.","없어도 뜻은 통해요.","「마시다」는 무엇을이 꼭 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#6','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C10',2,'mc','auto','「할머니께서 웃으신다.」에서 주어는 어느 것인가요?',ARRAY['K5-2-u2-X06','K5-2-u2-X04']::text[],false,'{"seq":6,"concept":"K5-2-u2-C10","difficulty":2,"kind":"mc","stem":"「할머니께서 웃으신다.」에서 주어는 어느 것인가요?","options":[{"t":"할머니께서","correct":true},{"t":"웃으신다","mis":"K5-2-u2-X06"},{"t":"주어가 없다 — 「이 · 가」가 붙은 말이 없어서","mis":"K5-2-u2-X04"},{"t":"께서","mis":"K5-2-u2-X04"}],"explanation":["그건 서술어예요.","「께서」가 붙어도 주어예요.","누가 웃는지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#7','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C5',2,'mc','auto','다음 가운데 서술어가 「무엇이다」에 해당하는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X05']::text[],false,'{"seq":7,"concept":"K5-2-u2-C5","difficulty":2,"kind":"mc","stem":"다음 가운데 서술어가 「무엇이다」에 해당하는 문장은 어느 것인가요?","options":[{"t":"서진이는 5학년이다.","correct":true},{"t":"서진이는 달린다.","mis":"K5-2-u2-X05"},{"t":"서진이는 씩씩하다.","mis":"K5-2-u2-X05"},{"t":"서진이는 공을 찼다.","mis":"K5-2-u2-X05"}],"explanation":["어찌하다예요.","어떠하다예요.","서진이가 무엇인지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#8','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C8',2,'match','auto','서술어와 그 서술어에 꼭 있어야 하는 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C8","difficulty":2,"kind":"match","stem":"서술어와 그 서술어에 꼭 있어야 하는 말을 알맞게 이으세요.","pairs":[{"l":"떠오르다","r":"무엇이 (해가)"},{"l":"넣다","r":"누가 + 무엇을 + 어디에"},{"l":"드리다","r":"누가 + 무엇을 + 누구에게"}],"mis":"K5-2-u2-X09","explanation":["주어만 있어도 돼요.","어디에 넣는지 있어야 해요.","누구에게 드리는지 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#9','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C7',2,'error','auto','목적어를 찾은 것이에요. 잘못 찾은 것은 어느 것인가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X08']::text[],false,'{"seq":9,"concept":"K5-2-u2-C7","difficulty":2,"kind":"error","stem":"목적어를 찾은 것이에요. 잘못 찾은 것은 어느 것인가요?","options":[{"t":"「동생이 책을 읽는다.」의 목적어 — 동생이","correct":true,"mis_target":"K5-2-u2-X07"},{"t":"「나는 꽃을 샀다.」의 목적어 — 꽃을","mis":"K5-2-u2-X08"},{"t":"「언니가 편지를 쓴다.」의 목적어 — 편지를","mis":"K5-2-u2-X08"}],"explanation":["무엇을 샀는지예요.","무엇을 쓰는지예요.","「동생이」는 주어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_basic#10','kor',5,2,'u2','L02','g5_2_kor_u2_L02_basic','lesson_basic','K5-2-u2-C9',3,'mc','auto','다음 가운데 목적어가 없어도 완전한 문장은 어느 것인가요?',ARRAY['K5-2-u2-X08']::text[],false,'{"seq":10,"concept":"K5-2-u2-C9","difficulty":3,"kind":"mc","stem":"다음 가운데 목적어가 없어도 완전한 문장은 어느 것인가요?","options":[{"t":"바람이 선선하다.","correct":true},{"t":"민호가 던졌다.","mis":"K5-2-u2-X08"},{"t":"누나가 샀다.","mis":"K5-2-u2-X08"},{"t":"아빠가 고치셨다.","mis":"K5-2-u2-X08"}],"explanation":["무엇을 던졌는지 궁금해요.","무엇을 샀는지 궁금해요.","「선선하다」는 목적어가 필요 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#1','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C4',2,'mc','auto','「강아지는 꼬리를 흔든다.」에서 주어를 찾는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X04','K5-2-u2-X06']::text[],false,'{"seq":1,"concept":"K5-2-u2-C4","difficulty":2,"kind":"mc","stem":"「강아지는 꼬리를 흔든다.」에서 주어를 찾는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「누가 꼬리를 흔드나?」를 물어 「강아지는」을 찾는다","correct":true},{"t":"「이 · 가」가 붙은 말만 찾는다","mis":"K5-2-u2-X04"},{"t":"문장 맨 끝 말을 찾는다","mis":"K5-2-u2-X06"},{"t":"가장 긴 낱말을 찾는다","mis":"K5-2-u2-X04"}],"explanation":["「는」이 붙어도 주어예요.","끝 말은 서술어예요.","물음으로 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#2','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C9',2,'ox','auto','모든 문장에는 반드시 목적어가 있어야 해요.',ARRAY['K5-2-u2-X08']::text[],false,'{"seq":2,"concept":"K5-2-u2-C9","difficulty":2,"kind":"ox","stem":"모든 문장에는 반드시 목적어가 있어야 해요.","answer":"X","reason_options":[{"t":"「해가 떠오른다.」처럼 서술어에 따라 목적어 없이도 완전한 문장이 있기 때문에","correct":true},{"t":"목적어가 없으면 누가 했는지 알 수 없기 때문에","mis":"K5-2-u2-X08"}],"mis":"K5-2-u2-X08","explanation":["서술어가 정해요.","누가는 주어가 알려 줘요.","목적어 없는 문장도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#3','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C8',3,'mc','auto','「하율이가 편지를 넣는다.」를 읽고 가장 궁금해지는 것과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X04','K5-2-u2-X07','K5-2-u2-X06']::text[],false,'{"seq":3,"concept":"K5-2-u2-C8","difficulty":3,"kind":"mc","stem":"「하율이가 편지를 넣는다.」를 읽고 가장 궁금해지는 것과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"어디에 넣는지 — 「넣다」는 어디에 해당하는 말이 있어야 뜻이 분명해서","correct":true},{"t":"누가 넣는지 — 주어가 없어서","mis":"K5-2-u2-X04"},{"t":"무엇을 넣는지 — 목적어가 없어서","mis":"K5-2-u2-X07"},{"t":"넣는지 안 넣는지 — 서술어가 없어서","mis":"K5-2-u2-X06"}],"explanation":["하율이가 주어예요.","편지를이 목적어예요.","「넣다」는 어디에가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#4','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C5',3,'mc','auto','「나는 ○○.」에 서술어를 넣어 세 갈래를 모두 보인 것은 어느 것인가요?',ARRAY['K5-2-u2-X05','K5-2-u2-X06']::text[],false,'{"seq":4,"concept":"K5-2-u2-C5","difficulty":3,"kind":"mc","stem":"「나는 ○○.」에 서술어를 넣어 세 갈래를 모두 보인 것은 어느 것인가요?","options":[{"t":"나는 뛴다. / 나는 즐겁다. / 나는 반장이다.","correct":true},{"t":"나는 뛴다. / 나는 걷는다. / 나는 웃는다.","mis":"K5-2-u2-X05"},{"t":"나는 즐겁다. / 나는 기쁘다. / 나는 슬프다.","mis":"K5-2-u2-X05"},{"t":"나는 공을 / 나는 빨리 / 나는 오늘","mis":"K5-2-u2-X06"}],"explanation":["모두 어찌하다예요.","모두 어떠하다예요.","어찌 · 어떠 · 무엇이 다 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#5','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C8',3,'mc','auto','「선생님께서 상장을 주셨다.」에 한 말을 더해 뜻을 더 분명히 하려면 어떤 말이 알맞은가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X04','K5-2-u2-X06']::text[],false,'{"seq":5,"concept":"K5-2-u2-C8","difficulty":3,"kind":"mc","stem":"「선생님께서 상장을 주셨다.」에 한 말을 더해 뜻을 더 분명히 하려면 어떤 말이 알맞은가요?","options":[{"t":"누구에게 주셨는지 (예: 지호에게)","correct":true},{"t":"무엇을 주셨는지 (예: 상장을)","mis":"K5-2-u2-X07"},{"t":"누가 주셨는지 (예: 선생님께서)","mis":"K5-2-u2-X04"},{"t":"주셨는지 안 주셨는지 (예: 주셨다)","mis":"K5-2-u2-X06"}],"explanation":["이미 있어요.","이미 있어요.","「주다」는 누구에게가 있어야 분명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#6','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C10',3,'error','auto','주어를 찾은 말이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X04','K5-2-u2-X06']::text[],false,'{"seq":6,"concept":"K5-2-u2-C10","difficulty":3,"kind":"error","stem":"주어를 찾은 말이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「언니는 노래한다.」에는 주어가 없다 — 「이 · 가」가 붙은 말이 없으니까","correct":true,"mis_target":"K5-2-u2-X04"},{"t":"「언니는 노래한다.」의 주어는 「언니는」이다 — 누가 노래하는지 알려 주니까","mis":"K5-2-u2-X06"},{"t":"「아버지께서 요리하신다.」의 주어는 「아버지께서」다 — 누가 요리하는지 알려 주니까","mis":"K5-2-u2-X06"}],"explanation":["누가를 물어 찾았어요.","「께서」도 주어예요.","「는」이 붙어도 주어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#7','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C7',3,'mc','auto','「동생이 ( ? ) 껴안았다.」에서 빈칸에 목적어를 넣어야 하는 까닭은 무엇인가요?',ARRAY['K5-2-u2-X04','K5-2-u2-X08','K5-2-u2-X06']::text[],false,'{"seq":7,"concept":"K5-2-u2-C7","difficulty":3,"kind":"mc","stem":"「동생이 ( ? ) 껴안았다.」에서 빈칸에 목적어를 넣어야 하는 까닭은 무엇인가요?","options":[{"t":"「껴안다」는 누구를 · 무엇을 껴안는지가 있어야 뜻이 온전해서","correct":true},{"t":"주어가 빠져 있어서","mis":"K5-2-u2-X04"},{"t":"모든 문장에는 목적어가 꼭 있어야 해서","mis":"K5-2-u2-X08"},{"t":"서술어가 문장 앞에 와야 해서","mis":"K5-2-u2-X06"}],"explanation":["동생이가 주어예요.","모든 문장이 그렇지는 않아요.","서술어가 대상을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#8','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C8',4,'essay','teacher','서술어 「보내다」를 넣어 문장을 하나 만들고, 그 문장에 꼭 있어야 하는 말이 무엇인지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C8","difficulty":4,"kind":"essay","stem":"서술어 「보내다」를 넣어 문장을 하나 만들고, 그 문장에 꼭 있어야 하는 말이 무엇인지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 민준이가 할머니께 생일 카드를 보냈다. 「보내다」에는 누가(민준이가) · 무엇을(생일 카드를) · 누구에게(할머니께)가 꼭 있어야 한다. 하나라도 빠지면 누가 무엇을 누구에게 보냈는지 알 수 없어 뜻이 분명하지 않기 때문이다.","scoring_points":["「보내다」로 문장을 만들었는가","누가 · 무엇을 · 누구에게를 갖추었는가","빠지면 뜻이 흐려진다는 까닭을 썼는가"]},"explanation":["문장을 만들어요.","필요한 말을 갖춰요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#9','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C4',4,'essay','teacher','「바람개비가 돈다.」와 「나는 바람개비를 돌린다.」를 견주어 두 문장의 주어 · 목적어 · 서술어를 찾아 쓰고, 무엇이 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C4","difficulty":4,"kind":"essay","stem":"「바람개비가 돈다.」와 「나는 바람개비를 돌린다.」를 견주어 두 문장의 주어 · 목적어 · 서술어를 찾아 쓰고, 무엇이 다른지 쓰세요.","answer_guide":{"answer":"예: 첫째 문장의 주어는 「바람개비가」, 서술어는 「돈다」이고 목적어는 없다. 둘째 문장의 주어는 「나는」, 목적어는 「바람개비를」, 서술어는 「돌린다」이다. 첫째 문장에서는 바람개비가 스스로 움직이는 주인이지만, 둘째 문장에서는 내가 움직이게 하는 대상이 되어 목적어가 되었다.","scoring_points":["두 문장의 성분을 바르게 찾았는가","목적어가 있고 없음을 견주었는가","바람개비가 주어에서 목적어로 바뀐 점을 썼는가"]},"explanation":["각 문장을 나눠요.","목적어를 견줘요.","바람개비의 자리를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L02_challenge#10','kor',5,2,'u2','L02','g5_2_kor_u2_L02_challenge','lesson_challenge','K5-2-u2-C6',4,'essay','teacher','「서술어는 문장의 중심이다.」라는 말의 뜻을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C6","difficulty":4,"kind":"essay","stem":"「서술어는 문장의 중심이다.」라는 말의 뜻을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「동생이 우유를」처럼 서술어가 빠지면 동생이 우유를 마셨는지 쏟았는지 알 수 없다. 「마셨다」를 넣어야 뜻이 전해진다. 또 서술어가 「마시다」인지 「드리다」인지에 따라 꼭 있어야 할 말도 달라지므로 서술어가 문장 전체를 이끄는 중심이다.","scoring_points":["서술어가 빠진 예를 들었는가","서술어가 있어야 뜻이 전해짐을 썼는가","서술어가 필요한 말을 정함을 썼는가"]},"explanation":["빠진 예를 들어요.","서술어의 일을 써요.","중심인 까닭을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#1','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C11',1,'mc','auto','앞에 오는 말에 어울리는 말이 뒤따르는 것을 무엇이라고 하나요?',ARRAY['K5-2-u2-X02','K5-2-u2-X10']::text[],false,'{"seq":1,"concept":"K5-2-u2-C11","difficulty":1,"kind":"mc","stem":"앞에 오는 말에 어울리는 말이 뒤따르는 것을 무엇이라고 하나요?","options":[{"t":"호응","correct":true},{"t":"매체","mis":"K5-2-u2-X02"},{"t":"개요","mis":"K5-2-u2-X10"},{"t":"첨부","mis":"K5-2-u2-X10"}],"explanation":["전하는 도구예요.","글의 뼈대예요.","말끼리 어울리는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#2','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C13',1,'blank','auto','「모자를 (     ).」에 어울리는 서술어는 어느 것인가요?',ARRAY['K5-2-u2-X12']::text[],false,'{"seq":2,"concept":"K5-2-u2-C13","difficulty":1,"kind":"blank","stem":"「모자를 (     ).」에 어울리는 서술어는 어느 것인가요?","options":[{"t":"쓴다","correct":true},{"t":"신는다","mis":"K5-2-u2-X12"},{"t":"낀다","mis":"K5-2-u2-X12"},{"t":"두른다","mis":"K5-2-u2-X12"}],"explanation":["양말에 어울려요.","장갑에 어울려요.","모자는 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#3','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C16',1,'ox','auto','「전혀」 뒤에는 「~지 않다」처럼 부정하는 말이 와야 자연스러워요.',ARRAY['K5-2-u2-X15']::text[],false,'{"seq":3,"concept":"K5-2-u2-C16","difficulty":1,"kind":"ox","stem":"「전혀」 뒤에는 「~지 않다」처럼 부정하는 말이 와야 자연스러워요.","answer":"O","reason_options":[{"t":"「전혀」는 부정하는 말과 어울리기 때문에","correct":true},{"t":"「전혀」는 어떤 말과 써도 똑같이 자연스럽기 때문에","mis":"K5-2-u2-X15"}],"mis":"K5-2-u2-X15","explanation":["「전혀 쉽지 않았다」처럼 써요.","부정하는 말과 짝이에요.","아무 말과 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#4','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C19',1,'mc','auto','「어제」와 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X18']::text[],false,'{"seq":4,"concept":"K5-2-u2-C19","difficulty":1,"kind":"mc","stem":"「어제」와 어울리는 문장은 어느 것인가요?","options":[{"t":"어제 공원에 갔다.","correct":true},{"t":"어제 공원에 갈 것이다.","mis":"K5-2-u2-X18"},{"t":"어제 공원에 가자.","mis":"K5-2-u2-X18"},{"t":"어제 공원에 가야겠다.","mis":"K5-2-u2-X18"}],"explanation":["앞으로의 일이에요.","함께 하자는 말이에요.","지난 일은 「~했다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#5','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C20',2,'mc','auto','「선생님이 책을 줬다.」를 높임 표현에 맞게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X19']::text[],false,'{"seq":5,"concept":"K5-2-u2-C20","difficulty":2,"kind":"mc","stem":"「선생님이 책을 줬다.」를 높임 표현에 맞게 고친 것은 어느 것인가요?","options":[{"t":"선생님께서 책을 주셨다.","correct":true},{"t":"선생님께서 책을 줬다.","mis":"K5-2-u2-X19"},{"t":"선생님은 책을 줬다.","mis":"K5-2-u2-X19"},{"t":"선생님께 책을 줬다.","mis":"K5-2-u2-X19"}],"explanation":["서술어도 높여요.","높임이 없어요.","뜻이 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#6','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C15',2,'blank','auto','「나는 봉사 활동에 반드시 (     ).」에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X14','K5-2-u2-X17']::text[],false,'{"seq":6,"concept":"K5-2-u2-C15","difficulty":2,"kind":"blank","stem":"「나는 봉사 활동에 반드시 (     ).」에 알맞은 말은 어느 것인가요?","options":[{"t":"참석해야 한다","correct":true},{"t":"참석해도 된다","mis":"K5-2-u2-X14"},{"t":"참석하지 않아도 된다","mis":"K5-2-u2-X14"},{"t":"참석했을지도 모른다","mis":"K5-2-u2-X17"}],"explanation":["반드시와 어울리지 않아요.","반드시와 어울리지 않아요.","반드시는 ~해야 한다와 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#7','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C17',2,'mc','auto','「이 책이 좋다. 왜냐하면 대화 장면이 감동적이다.」의 둘째 문장을 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X16']::text[],false,'{"seq":7,"concept":"K5-2-u2-C17","difficulty":2,"kind":"mc","stem":"「이 책이 좋다. 왜냐하면 대화 장면이 감동적이다.」의 둘째 문장을 바르게 고친 것은 어느 것인가요?","options":[{"t":"왜냐하면 대화 장면이 감동적이기 때문이다.","correct":true},{"t":"왜냐하면 대화 장면이 감동적이었다.","mis":"K5-2-u2-X16"},{"t":"왜냐하면 대화 장면이 감동적일 것이다.","mis":"K5-2-u2-X16"},{"t":"그래서 대화 장면이 감동적이다.","mis":"K5-2-u2-X16"}],"explanation":["끝맺음이 안 맞아요.","짐작이 아니에요.","왜냐하면은 ~기 때문이다와 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#8','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C16',2,'error','auto','일기 「수수깡 집 짓기」를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u2-X15','K5-2-u2-X21']::text[],false,'{"seq":8,"concept":"K5-2-u2-C16","difficulty":2,"kind":"error","stem":"일기 「수수깡 집 짓기」를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「여간 어려운 일이었다」는 고칠 곳이 없는 문장이다","correct":true,"mis_target":"K5-2-u2-X15"},{"t":"「도저히 이해되었다」는 「도저히 이해되지 않았다」로 고쳐야 한다","mis":"K5-2-u2-X21"},{"t":"「별로 어려웠다」는 「별로 어렵지 않았다」로 고쳐야 한다","mis":"K5-2-u2-X21"}],"explanation":["부정하는 말을 넣었어요.","부정하는 말을 넣었어요.","여간 뒤에도 부정하는 말이 와요."],"asset":{"type":"passage","lines":["오늘 미술 시간에 수수깡으로 집을 지었다.","지붕을 붙이는 일은 여간 어려운 일이었다.","선생님께서 방법을 알려 주셨는데도 도저히 이해되었다.","짝과 함께 다시 해 보니 이번에는 별로 어려웠다.","내일은 친구들에게 우리 집을 소개할 것이다."],"title":"일기 「수수깡 집 짓기」","hi":["여간","도저히","별로"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#9','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C15',2,'match','auto','앞에 오는 말과 어울리는 끝말을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C15","difficulty":2,"kind":"match","stem":"앞에 오는 말과 어울리는 끝말을 알맞게 이으세요.","pairs":[{"l":"반드시","r":"~해야 한다"},{"l":"왜냐하면","r":"~기 때문이다"},{"l":"도저히","r":"~할 수 없다"}],"mis":"K5-2-u2-X14","explanation":["꼭 해야 함이에요.","까닭을 맺어요.","부정하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_basic#10','kor',5,2,'u2','L03','g5_2_kor_u2_L03_basic','lesson_basic','K5-2-u2-C14',3,'mc','auto','「서윤이는 장갑과 목도리를 끼고 나섰다.」가 어색한 까닭은 무엇인가요?',ARRAY['K5-2-u2-X06','K5-2-u2-X13','K5-2-u2-X18']::text[],false,'{"seq":10,"concept":"K5-2-u2-C14","difficulty":3,"kind":"mc","stem":"「서윤이는 장갑과 목도리를 끼고 나섰다.」가 어색한 까닭은 무엇인가요?","options":[{"t":"목도리는 「끼다」가 아니라 「두르다」와 어울리는데 한 서술어로 묶어서","correct":true},{"t":"주어가 빠져서","mis":"K5-2-u2-X06"},{"t":"장갑은 낄 수 없어서","mis":"K5-2-u2-X13"},{"t":"「나섰다」가 지난 일이라서","mis":"K5-2-u2-X18"}],"explanation":["서윤이는이 주어예요.","장갑은 끼어요.","목적어마다 서술어가 달라요."],"asset":{"type":"passage","lines":["서윤이는 장갑과 목도리를 끼고 나섰다.","우리 고양이는 목욕을 별로 좋아한다.","내 꿈은 커서 수의사가 되고 싶다."],"title":"「서윤이의 아침」 속 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#1','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C12',2,'mc','auto','주어와 서술어가 어울리지 않는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X11']::text[],false,'{"seq":1,"concept":"K5-2-u2-C12","difficulty":2,"kind":"mc","stem":"주어와 서술어가 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"강아지가 지저귄다.","correct":true},{"t":"새가 지저귄다.","mis":"K5-2-u2-X11"},{"t":"강아지가 짖는다.","mis":"K5-2-u2-X11"},{"t":"시냇물이 졸졸 흐른다.","mis":"K5-2-u2-X11"}],"explanation":["자연스러워요.","자연스러워요.","강아지는 짖어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#2','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C21',2,'ox','auto','「내 꿈은 커서 수의사가 되고 싶다.」는 호응이 자연스러운 문장이에요.',ARRAY['K5-2-u2-X20']::text[],false,'{"seq":2,"concept":"K5-2-u2-C21","difficulty":2,"kind":"ox","stem":"「내 꿈은 커서 수의사가 되고 싶다.」는 호응이 자연스러운 문장이에요.","answer":"X","reason_options":[{"t":"「꿈은」으로 시작하면 「~는 것이다」로 맺어야 어울리기 때문에","correct":true},{"t":"꿈을 말하는 문장은 「~하고 싶다」로 끝내면 되기 때문에","mis":"K5-2-u2-X20"}],"mis":"K5-2-u2-X20","explanation":["주어가 「꿈은」이에요.","꿈은 ~되는 것이다로 맺어요.","되고 싶다는 「나는」과 어울려요."],"asset":{"type":"passage","lines":["서윤이는 장갑과 목도리를 끼고 나섰다.","우리 고양이는 목욕을 별로 좋아한다.","내 꿈은 커서 수의사가 되고 싶다."],"title":"「서윤이의 아침」 속 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#3','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C13',3,'mc','auto','목적어와 서술어가 모두 어울리게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u2-X12']::text[],false,'{"seq":3,"concept":"K5-2-u2-C13","difficulty":3,"kind":"mc","stem":"목적어와 서술어가 모두 어울리게 짝지은 것은 어느 것인가요?","options":[{"t":"김치를 담그다 · 만두를 빚다 · 양말을 신다","correct":true},{"t":"김치를 빚다 · 만두를 담그다 · 양말을 신다","mis":"K5-2-u2-X12"},{"t":"김치를 담그다 · 만두를 빚다 · 양말을 쓰다","mis":"K5-2-u2-X12"},{"t":"김치를 신다 · 만두를 쓰다 · 양말을 빚다","mis":"K5-2-u2-X12"}],"explanation":["김치와 만두가 바뀌었어요.","양말은 신어요.","셋 다 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#4','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C22',3,'mc','auto','「별로 좋아한다」를 고친 두 친구의 문장을 보고 알맞게 판단한 것은 어느 것인가요?',ARRAY['K5-2-u2-X21','K5-2-u2-X15']::text[],false,'{"seq":4,"concept":"K5-2-u2-C22","difficulty":3,"kind":"mc","stem":"「별로 좋아한다」를 고친 두 친구의 문장을 보고 알맞게 판단한 것은 어느 것인가요?","options":[{"t":"둘 다 알맞다 — 「별로」와 부정하는 말이 어울리기 때문에","correct":true},{"t":"도윤이만 알맞다 — 고친 답은 하나뿐이라서","mis":"K5-2-u2-X21"},{"t":"하람이만 알맞다 — 낱말을 꼭 바꾸어야 해서","mis":"K5-2-u2-X21"},{"t":"둘 다 틀렸다 — 「별로」를 지워야만 해서","mis":"K5-2-u2-X15"}],"explanation":["여러 표현이 될 수 있어요.","꼭 바꿀 필요는 없어요.","까닭이 맞으면 둘 다 돼요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"우리 고양이는 목욕을 별로 좋아하지 않는다."},{"who":"하람","text":"우리 고양이는 목욕을 별로 즐기지 않는다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#5','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C20',3,'mc','auto','할머니가 주어인 문장을 높임 표현에 맞게 쓴 것은 어느 것인가요?',ARRAY['K5-2-u2-X19']::text[],false,'{"seq":5,"concept":"K5-2-u2-C20","difficulty":3,"kind":"mc","stem":"할머니가 주어인 문장을 높임 표현에 맞게 쓴 것은 어느 것인가요?","options":[{"t":"할머니께서 시장에 가셨다.","correct":true},{"t":"할머니께서 시장에 갔다.","mis":"K5-2-u2-X19"},{"t":"할머니가 시장에 갔다.","mis":"K5-2-u2-X19"},{"t":"할머니께 시장에 가셨다.","mis":"K5-2-u2-X19"}],"explanation":["서술어를 높이지 않았어요.","높임이 하나도 없어요.","「께서」와 「-시-」가 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#6','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C19',3,'error','auto','일기 「비 오는 날의 체육 시간」을 고치려는 말 가운데 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X18','K5-2-u2-X19','K5-2-u2-X15']::text[],false,'{"seq":6,"concept":"K5-2-u2-C19","difficulty":3,"kind":"error","stem":"일기 「비 오는 날의 체육 시간」을 고치려는 말 가운데 알맞지 않은 것은 어느 것인가요?","options":[{"t":"첫째 문장은 고칠 필요가 없다 — 「할 것이다」는 앞으로의 계획이라서","correct":true,"mis_target":"K5-2-u2-X18"},{"t":"둘째 문장은 「선생님께서 공을 주셨다」로 고친다","mis":"K5-2-u2-X19"},{"t":"셋째 문장은 「전혀 쉽지 않았다」로 고친다","mis":"K5-2-u2-X15"}],"explanation":["높임을 맞췄어요.","부정하는 말을 넣었어요.","「어제」는 지난 일이라 「했다」예요."],"asset":{"type":"passage","lines":["어제 체육 시간에 피구를 할 것이다.","비가 와서 강당에서 했는데 선생님이 공을 줬다.","나는 공을 받는 일이 전혀 쉬웠다.","왜냐하면 지난번에 공에 맞은 적이 있다.","그래도 반드시 다음에는 공을 잡아도 된다."],"title":"일기 「비 오는 날의 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#7','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C17',3,'mc','auto','일기의 넷째 문장을 호응에 맞게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X16','K5-2-u2-X18']::text[],false,'{"seq":7,"concept":"K5-2-u2-C17","difficulty":3,"kind":"mc","stem":"일기의 넷째 문장을 호응에 맞게 고친 것은 어느 것인가요?","options":[{"t":"왜냐하면 지난번에 공에 맞은 적이 있기 때문이다.","correct":true},{"t":"왜냐하면 지난번에 공에 맞은 적이 있었다.","mis":"K5-2-u2-X16"},{"t":"그래서 지난번에 공에 맞은 적이 있다.","mis":"K5-2-u2-X16"},{"t":"왜냐하면 지난번에 공에 맞을 것이다.","mis":"K5-2-u2-X18"}],"explanation":["끝맺음이 그대로예요.","까닭이 아니게 돼요.","때도 맞고 끝맺음도 맞아요."],"asset":{"type":"passage","lines":["어제 체육 시간에 피구를 할 것이다.","비가 와서 강당에서 했는데 선생님이 공을 줬다.","나는 공을 받는 일이 전혀 쉬웠다.","왜냐하면 지난번에 공에 맞은 적이 있다.","그래도 반드시 다음에는 공을 잡아도 된다."],"title":"일기 「비 오는 날의 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#8','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C16',4,'essay','teacher','「수수깡 집 짓기」에서 호응이 어색한 문장 세 개를 찾아 고쳐 쓰고, 어색한 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C16","difficulty":4,"kind":"essay","stem":"「수수깡 집 짓기」에서 호응이 어색한 문장 세 개를 찾아 고쳐 쓰고, 어색한 까닭을 쓰세요.","answer_guide":{"answer":"예: 「지붕을 붙이는 일은 여간 어려운 일이 아니었다.」 「선생님께서 방법을 알려 주셨는데도 도저히 이해되지 않았다.」 「짝과 함께 다시 해 보니 이번에는 별로 어렵지 않았다.」 여간 · 도저히 · 별로는 뒤에 부정하는 말이 와야 어울리는데, 처음 글에서는 부정하는 말 없이 써서 어색했다.","scoring_points":["어색한 문장 세 개를 찾았는가","부정하는 말을 넣어 고쳤는가","어색한 까닭을 썼는가"]},"explanation":["굵게 볼 말을 찾아요.","부정하는 말을 넣어요.","까닭을 써요."],"asset":{"type":"passage","lines":["오늘 미술 시간에 수수깡으로 집을 지었다.","지붕을 붙이는 일은 여간 어려운 일이었다.","선생님께서 방법을 알려 주셨는데도 도저히 이해되었다.","짝과 함께 다시 해 보니 이번에는 별로 어려웠다.","내일은 친구들에게 우리 집을 소개할 것이다."],"title":"일기 「수수깡 집 짓기」","hi":["여간","도저히","별로"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#9','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C22',4,'essay','teacher','일기의 다섯째 문장 「그래도 반드시 다음에는 공을 잡아도 된다.」를 서로 다른 두 가지로 고쳐 쓰고, 두 문장이 모두 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C22","difficulty":4,"kind":"essay","stem":"일기의 다섯째 문장 「그래도 반드시 다음에는 공을 잡아도 된다.」를 서로 다른 두 가지로 고쳐 쓰고, 두 문장이 모두 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「그래도 다음에는 반드시 공을 잡아야겠다.」 「그래도 다음에는 반드시 공을 잡을 것이다.」 「반드시」는 꼭 그렇게 하겠다는 뜻이라 「~해도 된다」와는 어울리지 않는다. 두 문장 모두 꼭 하겠다는 말로 맺어 「반드시」와 어울리므로 표현이 달라도 둘 다 알맞다.","scoring_points":["두 가지로 고쳐 썼는가","두 문장 모두 「반드시」와 어울리는가","여러 표현이 될 수 있는 까닭을 썼는가"]},"explanation":["두 가지로 써 봐요.","반드시의 짝을 맞춰요.","까닭이 맞으면 여러 가지예요."],"asset":{"type":"passage","lines":["어제 체육 시간에 피구를 할 것이다.","비가 와서 강당에서 했는데 선생님이 공을 줬다.","나는 공을 받는 일이 전혀 쉬웠다.","왜냐하면 지난번에 공에 맞은 적이 있다.","그래도 반드시 다음에는 공을 잡아도 된다."],"title":"일기 「비 오는 날의 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L03_challenge#10','kor',5,2,'u2','L03','g5_2_kor_u2_L03_challenge','lesson_challenge','K5-2-u2-C11',4,'essay','teacher','호응이 어색한 문장을 그대로 두면 읽는 사람에게 어떤 일이 생기는지 예를 들어 쓰고, 문장을 쓴 뒤 호응을 확인하는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C11","difficulty":4,"kind":"essay","stem":"호응이 어색한 문장을 그대로 두면 읽는 사람에게 어떤 일이 생기는지 예를 들어 쓰고, 문장을 쓴 뒤 호응을 확인하는 방법을 쓰세요.","answer_guide":{"answer":"예: 「어제 친구와 축구를 할 것이다.」라고 쓰면 읽는 사람은 축구를 이미 했는지 앞으로 할지 헷갈린다. 문장을 쓴 뒤에는 소리 내어 읽으며 때를 나타내는 말과 서술어, 「께서」와 높인 서술어, 「별로 · 전혀」와 부정하는 말이 서로 어울리는지 짝을 지어 확인한다.","scoring_points":["어색한 문장의 예를 들었는가","읽는 사람이 겪는 혼란을 썼는가","호응을 확인하는 방법을 썼는가"]},"explanation":["예를 들어요.","헷갈리는 점을 써요.","확인 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#1','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C23',1,'mc','auto','경험을 글로 쓰기 전에 먼저 정할 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X22']::text[],false,'{"seq":1,"concept":"K5-2-u2-C23","difficulty":1,"kind":"mc","stem":"경험을 글로 쓰기 전에 먼저 정할 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글씨를 어떤 색 펜으로 쓸지","correct":true},{"t":"누가 내 글을 읽을지","mis":"K5-2-u2-X22"},{"t":"무엇을 위해 쓰는지","mis":"K5-2-u2-X22"},{"t":"어떤 경험을 쓸지","mis":"K5-2-u2-X22"}],"explanation":["먼저 정해요.","먼저 정해요.","펜 색은 글의 내용과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#2','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C24',1,'ox','auto','경험을 쓴 글의 글감은 사건이 많을수록 좋아요.',ARRAY['K5-2-u2-X23']::text[],false,'{"seq":2,"concept":"K5-2-u2-C24","difficulty":1,"kind":"ox","stem":"경험을 쓴 글의 글감은 사건이 많을수록 좋아요.","answer":"X","reason_options":[{"t":"사건이 많으면 느낌이 흐려져, 그때의 느낌이 생생한 한 가지 일이 좋기 때문에","correct":true},{"t":"여러 일을 넣어야 읽는 사람이 지루하지 않기 때문에","mis":"K5-2-u2-X23"}],"mis":"K5-2-u2-X23","explanation":["많으면 흐려져요.","한 가지를 깊게 써요.","생생한 느낌이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#3','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C26',1,'mc','auto','처음-가운데-끝 가운데 「언제 · 어디서 · 누구와 어떤 경험을 했는지」를 소개하는 부분은 어디인가요?',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":3,"concept":"K5-2-u2-C26","difficulty":1,"kind":"mc","stem":"처음-가운데-끝 가운데 「언제 · 어디서 · 누구와 어떤 경험을 했는지」를 소개하는 부분은 어디인가요?","options":[{"t":"처음","correct":true},{"t":"가운데","mis":"K5-2-u2-X25"},{"t":"끝","mis":"K5-2-u2-X25"},{"t":"제목","mis":"K5-2-u2-X25"}],"explanation":["일과 느낌을 자세히 써요.","배운 점과 다짐을 써요.","처음에 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#4','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C25',1,'blank','auto','경험을 정리할 때에는 「처음에 → 그다음에 → 마지막에」처럼 (     ) 차례로 정리하면 좋아요.',ARRAY['K5-2-u2-X24']::text[],false,'{"seq":4,"concept":"K5-2-u2-C25","difficulty":1,"kind":"blank","stem":"경험을 정리할 때에는 「처음에 → 그다음에 → 마지막에」처럼 (     ) 차례로 정리하면 좋아요.","options":[{"t":"시간","correct":true},{"t":"글자 수","mis":"K5-2-u2-X24"},{"t":"좋아하는","mis":"K5-2-u2-X24"},{"t":"가나다","mis":"K5-2-u2-X24"}],"explanation":["길이 차례가 아니에요.","마음대로가 아니에요.","일이 일어난 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#5','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C26',2,'mc','auto','「강변에서 다시 띄운 연」 개요에서 가장 인상 깊은 장면을 크게 담은 부분은 어디인가요?',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":5,"concept":"K5-2-u2-C26","difficulty":2,"kind":"mc","stem":"「강변에서 다시 띄운 연」 개요에서 가장 인상 깊은 장면을 크게 담은 부분은 어디인가요?","options":[{"t":"가운데","correct":true},{"t":"처음","mis":"K5-2-u2-X25"},{"t":"끝","mis":"K5-2-u2-X25"},{"t":"제목","mis":"K5-2-u2-X25"}],"explanation":["소개만 해요.","배운 점이에요.","줄이 끊어진 장면이 가운데에 있어요."],"asset":{"type":"passage","lines":["처음 — 지난 방학, 강변 공원에서 아빠와 만든 연을 날리기로 했다.","가운데 — 연이 높이 오르는 순간 줄이 툭 끊어졌다. 눈물이 핑 돌았다.","가운데 — 남은 실을 두 겹으로 꼬아 새 연을 만들어 다시 띄웠다.","끝 — 실패해도 까닭을 찾아 다시 하면 된다는 것을 알았다."],"title":"개요 「강변에서 다시 띄운 연」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#6','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C27',2,'mc','auto','고쳐쓰기에서 찾아 고칠 것으로 알맞게 묶은 것은 어느 것인가요?',ARRAY['K5-2-u2-X26']::text[],false,'{"seq":6,"concept":"K5-2-u2-C27","difficulty":2,"kind":"mc","stem":"고쳐쓰기에서 찾아 고칠 것으로 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"빠진 말 · 겹친 말 · 어울리지 않는 말","correct":true},{"t":"맞춤법만","mis":"K5-2-u2-X26"},{"t":"글씨 크기 · 종이 색","mis":"K5-2-u2-X26"},{"t":"제목의 글자 수","mis":"K5-2-u2-X26"}],"explanation":["맞춤법만이 아니에요.","내용과 관계없어요.","문장의 말을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#7','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C28',2,'mc','auto','모둠 친구의 경험 글을 읽고 나눌 이야기로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X27']::text[],false,'{"seq":7,"concept":"K5-2-u2-C28","difficulty":2,"kind":"mc","stem":"모둠 친구의 경험 글을 읽고 나눌 이야기로 알맞은 것은 어느 것인가요?","options":[{"t":"인상 깊은 장면, 공감한 부분, 궁금한 점","correct":true},{"t":"틀린 글자가 모두 몇 개인지","mis":"K5-2-u2-X27"},{"t":"누가 글씨를 더 잘 썼는지","mis":"K5-2-u2-X27"},{"t":"글이 모두 몇 줄인지","mis":"K5-2-u2-X27"}],"explanation":["오늘은 공감이 먼저예요.","글씨 겨루기가 아니에요.","내용을 두고 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#8','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C27',2,'error','auto','「처음 타 본 자전거」의 둘째 문장을 두고 한 말이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X19','K5-2-u2-X21']::text[],false,'{"seq":8,"concept":"K5-2-u2-C27","difficulty":2,"kind":"error","stem":"「처음 타 본 자전거」의 둘째 문장을 두고 한 말이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「아빠께서 뒤에서 잡아 주었다.」는 고칠 곳이 없다","correct":true,"mis_target":"K5-2-u2-X19"},{"t":"「아빠께서 뒤에서 잡아 주셨다.」로 고친다","mis":"K5-2-u2-X21"},{"t":"「아빠께서 뒤에서 자전거를 잡아 주셨다.」로 고친다","mis":"K5-2-u2-X21"}],"explanation":["높임을 맞췄어요.","높임도 맞추고 말도 보탰어요.","「께서」에 맞게 서술어도 높여요."],"asset":{"type":"passage","lines":["지난 주말에 나는 공원에서 자전거를 처음 탔다.","아빠께서 뒤에서 잡아 주었다.","나는 페달을 힘껏 세게 힘차게 밟았다.","아빠가 손을 놓으신 줄도 모르고 혼자 달렸다.","넘어졌지만 별로 아팠다.","그날 나는 무엇이든 해 보면 된다."],"title":"초안 「처음 타 본 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#9','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C23',2,'mc','auto','반 친구들이 읽을 경험 글을 쓸 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u2-X22','K5-2-u2-X23']::text[],false,'{"seq":9,"concept":"K5-2-u2-C23","difficulty":2,"kind":"mc","stem":"반 친구들이 읽을 경험 글을 쓸 때 알맞은 태도는 어느 것인가요?","options":[{"t":"친구들이 공감할 수 있게 쉽고 생생하게 쓴다","correct":true},{"t":"어려운 낱말을 골라 멋있게 쓴다","mis":"K5-2-u2-X22"},{"t":"나만 아는 줄임말로 짧게 쓴다","mis":"K5-2-u2-X22"},{"t":"있었던 일을 빠짐없이 모두 쓴다","mis":"K5-2-u2-X23"}],"explanation":["읽기 어려워요.","친구들이 몰라요.","공감이 목적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_basic#10','kor',5,2,'u2','L05','g5_2_kor_u2_L05_basic','lesson_basic','K5-2-u2-C27',3,'mc','auto','「넘어졌지만 별로 아팠다.」를 고친 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X15','K5-2-u2-X17','K5-2-u2-X14']::text[],false,'{"seq":10,"concept":"K5-2-u2-C27","difficulty":3,"kind":"mc","stem":"「넘어졌지만 별로 아팠다.」를 고친 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"넘어졌지만 별로 아프지 않았다.","correct":true},{"t":"넘어졌지만 별로 아팠었다.","mis":"K5-2-u2-X15"},{"t":"넘어졌지만 아마 아팠다.","mis":"K5-2-u2-X17"},{"t":"넘어졌지만 반드시 아팠다.","mis":"K5-2-u2-X14"}],"explanation":["부정하는 말이 없어요.","아마와도 어울리지 않아요.","별로 + 부정하는 말이에요."],"asset":{"type":"passage","lines":["지난 주말에 나는 공원에서 자전거를 처음 탔다.","아빠께서 뒤에서 잡아 주었다.","나는 페달을 힘껏 세게 힘차게 밟았다.","아빠가 손을 놓으신 줄도 모르고 혼자 달렸다.","넘어졌지만 별로 아팠다.","그날 나는 무엇이든 해 보면 된다."],"title":"초안 「처음 타 본 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#1','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C24',2,'mc','auto','다음 가운데 경험 글의 글감으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X23','K5-2-u2-X22']::text[],false,'{"seq":1,"concept":"K5-2-u2-C24","difficulty":2,"kind":"mc","stem":"다음 가운데 경험 글의 글감으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음 혼자 자전거를 타던 순간의 떨림과 기쁨","correct":true},{"t":"지난 한 해 동안 있었던 모든 일","mis":"K5-2-u2-X23"},{"t":"어제 먹은 음식 이름 모두","mis":"K5-2-u2-X23"},{"t":"친구가 들려준 다른 사람 이야기","mis":"K5-2-u2-X22"}],"explanation":["너무 많아요.","느낌이 없어요.","느낌이 생생한 한 가지 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#2','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C26',2,'ox','auto','경험 글의 끝에는 배우거나 느낀 점, 다짐을 쓸 수 있어요.',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":2,"concept":"K5-2-u2-C26","difficulty":2,"kind":"ox","stem":"경험 글의 끝에는 배우거나 느낀 점, 다짐을 쓸 수 있어요.","answer":"O","reason_options":[{"t":"끝에서 경험을 돌아보며 생각을 정리하기 때문에","correct":true},{"t":"끝에는 일어난 일만 다시 줄줄이 적어야 하기 때문에","mis":"K5-2-u2-X25"}],"mis":"K5-2-u2-X25","explanation":["끝은 돌아보기예요.","다짐을 써도 좋아요.","일은 가운데에 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#3','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C25',3,'mc','auto','차례대로 정리한 메모를 더 좋게 만드는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X24']::text[],false,'{"seq":3,"concept":"K5-2-u2-C25","difficulty":3,"kind":"mc","stem":"차례대로 정리한 메모를 더 좋게 만드는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"일마다 그때 한 말이나 든 느낌을 한 줄씩 더한다","correct":true},{"t":"일어난 사실만 더 많이 적는다","mis":"K5-2-u2-X24"},{"t":"차례를 섞어 재미있게 바꾼다","mis":"K5-2-u2-X24"},{"t":"느낌은 맨 끝에 한꺼번에만 쓴다","mis":"K5-2-u2-X24"}],"explanation":["느낌이 빠져요.","차례가 흐트러져요.","말과 느낌을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#4','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C27',3,'mc','auto','「처음 타 본 자전거」 마지막 문장 「그날 나는 무엇이든 해 보면 된다.」가 어색한 까닭은 무엇인가요?',ARRAY['K5-2-u2-X26','K5-2-u2-X18']::text[],false,'{"seq":4,"concept":"K5-2-u2-C27","difficulty":3,"kind":"mc","stem":"「처음 타 본 자전거」 마지막 문장 「그날 나는 무엇이든 해 보면 된다.」가 어색한 까닭은 무엇인가요?","options":[{"t":"「나는」과 어울리는 서술어가 없어 내가 무엇을 했는지 알 수 없어서","correct":true},{"t":"문장이 너무 길어서","mis":"K5-2-u2-X26"},{"t":"「그날」이 지난 일이라서","mis":"K5-2-u2-X18"},{"t":"「무엇이든」이 어려운 말이라서","mis":"K5-2-u2-X26"}],"explanation":["길이가 문제가 아니에요.","때 표현은 맞아요.","「~는 것을 배웠다」가 빠졌어요."],"asset":{"type":"passage","lines":["지난 주말에 나는 공원에서 자전거를 처음 탔다.","아빠께서 뒤에서 잡아 주었다.","나는 페달을 힘껏 세게 힘차게 밟았다.","아빠가 손을 놓으신 줄도 모르고 혼자 달렸다.","넘어졌지만 별로 아팠다.","그날 나는 무엇이든 해 보면 된다."],"title":"초안 「처음 타 본 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#5','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C26',3,'mc','auto','처음-가운데-끝으로 쓴 경험 글에서 「가운데」를 가장 잘 쓴 것은 어느 것인가요?',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":5,"concept":"K5-2-u2-C26","difficulty":3,"kind":"mc","stem":"처음-가운데-끝으로 쓴 경험 글에서 「가운데」를 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"줄이 끊어진 순간의 모습과 「눈물이 핑 돌았다」는 느낌까지 자세히 썼다","correct":true},{"t":"언제 어디서 누구와 갔는지만 길게 썼다","mis":"K5-2-u2-X25"},{"t":"「참 재미있었다. 끝.」으로만 썼다","mis":"K5-2-u2-X25"},{"t":"다음 방학 계획을 자세히 썼다","mis":"K5-2-u2-X25"}],"explanation":["그건 처음이에요.","너무 짧아요.","일과 느낌을 자세히 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#6','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C28',3,'error','auto','친구 글을 읽고 나눈 말이에요. 오늘 활동에 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u2-X27','K5-2-u2-X23']::text[],false,'{"seq":6,"concept":"K5-2-u2-C28","difficulty":3,"kind":"error","stem":"친구 글을 읽고 나눈 말이에요. 오늘 활동에 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「글씨가 삐뚤어서 별로야.」","correct":true,"mis_target":"K5-2-u2-X27"},{"t":"「줄이 끊어진 장면에서 나도 마음이 철렁했어.」","mis":"K5-2-u2-X23"},{"t":"「새 연을 만들 때 아빠가 뭐라고 하셨는지 궁금해.」","mis":"K5-2-u2-X23"}],"explanation":["공감한 부분이에요.","궁금한 점이에요.","글의 내용을 두고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#7','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C23',3,'mc','auto','같은 「연 날리기」 경험이라도 할머니께 보내는 글과 반 친구들에게 읽힐 글이 달라지는 까닭은 무엇인가요?',ARRAY['K5-2-u2-X22']::text[],false,'{"seq":7,"concept":"K5-2-u2-C23","difficulty":3,"kind":"mc","stem":"같은 「연 날리기」 경험이라도 할머니께 보내는 글과 반 친구들에게 읽힐 글이 달라지는 까닭은 무엇인가요?","options":[{"t":"읽을 사람이 다르면 알맞은 말투와 내용이 달라지기 때문에","correct":true},{"t":"경험 자체가 달라지기 때문에","mis":"K5-2-u2-X22"},{"t":"글감은 읽을 사람과 관계없기 때문에","mis":"K5-2-u2-X22"},{"t":"할머니께는 글을 쓰면 안 되기 때문에","mis":"K5-2-u2-X22"}],"explanation":["경험은 같아요.","읽을 사람이 중요해요.","읽을 사람에 맞춰 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#8','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C26',4,'essay','teacher','내가 겪은 일 하나를 골라 처음-가운데-끝 개요를 짜고, 가운데에 가장 크게 담을 장면을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C26","difficulty":4,"kind":"essay","stem":"내가 겪은 일 하나를 골라 처음-가운데-끝 개요를 짜고, 가운데에 가장 크게 담을 장면을 쓰세요.","answer_guide":{"answer":"예: 처음 — 지난 가을, 가족과 함께 시골 할머니 댁에서 밤을 주웠다. 가운데 — 밤송이를 발로 벌리다 가시에 찔려 깜짝 놀랐지만, 할머니께서 집게로 까는 법을 알려 주셔서 바구니를 가득 채웠다. 끝 — 서두르지 않고 방법을 배우면 어려운 일도 해낼 수 있다는 것을 알았다. 가운데에는 가시에 찔린 순간의 놀람과 바구니가 차오를 때의 뿌듯함을 가장 크게 담겠다.","scoring_points":["처음 · 가운데 · 끝을 갖추었는가","가운데에 일과 느낌을 넣었는가","가장 크게 담을 장면을 밝혔는가"]},"explanation":["세 부분을 나눠요.","가운데를 자세히요.","인상 깊은 장면을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#9','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C27',4,'essay','teacher','「처음 타 본 자전거」에서 고쳐야 할 문장 세 개를 찾아 고쳐 쓰고, 각각 무엇이 문제였는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C27","difficulty":4,"kind":"essay","stem":"「처음 타 본 자전거」에서 고쳐야 할 문장 세 개를 찾아 고쳐 쓰고, 각각 무엇이 문제였는지 쓰세요.","answer_guide":{"answer":"예: 「아빠께서 뒤에서 잡아 주셨다.」 — 「께서」에 맞게 서술어도 높여야 한다. 「나는 페달을 힘차게 밟았다.」 — 같은 뜻의 말이 겹쳤다. 「넘어졌지만 별로 아프지 않았다.」 — 「별로」 뒤에는 부정하는 말이 와야 한다. (이 밖에 「아빠께서 손을 놓으신」, 「무엇이든 해 보면 된다는 것을 배웠다」도 알맞다.)","scoring_points":["고칠 문장 세 개를 찾았는가","알맞게 고쳤는가","높임 · 겹친 말 · 호응 등 문제를 밝혔는가"]},"explanation":["어색한 문장을 찾아요.","고쳐 써요.","무엇이 문제였는지 밝혀요."],"asset":{"type":"passage","lines":["지난 주말에 나는 공원에서 자전거를 처음 탔다.","아빠께서 뒤에서 잡아 주었다.","나는 페달을 힘껏 세게 힘차게 밟았다.","아빠가 손을 놓으신 줄도 모르고 혼자 달렸다.","넘어졌지만 별로 아팠다.","그날 나는 무엇이든 해 보면 된다."],"title":"초안 「처음 타 본 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L05_challenge#10','kor',5,2,'u2','L05','g5_2_kor_u2_L05_challenge','lesson_challenge','K5-2-u2-C28',4,'essay','teacher','「강변에서 다시 띄운 연」을 읽고 친구에게 인상 깊은 장면 · 공감한 부분 · 궁금한 점을 한 가지씩 말해 주는 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C28","difficulty":4,"kind":"essay","stem":"「강변에서 다시 띄운 연」을 읽고 친구에게 인상 깊은 장면 · 공감한 부분 · 궁금한 점을 한 가지씩 말해 주는 글을 쓰세요.","answer_guide":{"answer":"예: 줄이 툭 끊어져 연이 강 건너로 날아가는 장면이 가장 인상 깊었어. 눈물이 핑 돌았다는 말에 나도 아끼던 풍선을 놓쳤던 날이 떠올라 공감했어. 실을 두 겹으로 꼬자고 처음 생각한 사람이 너였는지 아빠였는지 궁금해.","scoring_points":["인상 깊은 장면을 썼는가","공감한 부분을 경험과 함께 썼는가","궁금한 점을 썼는가"]},"explanation":["장면을 골라요.","내 경험과 이어요.","물어볼 것을 써요."],"asset":{"type":"passage","lines":["처음 — 지난 방학, 강변 공원에서 아빠와 만든 연을 날리기로 했다.","가운데 — 연이 높이 오르는 순간 줄이 툭 끊어졌다. 눈물이 핑 돌았다.","가운데 — 남은 실을 두 겹으로 꼬아 새 연을 만들어 다시 띄웠다.","끝 — 실패해도 까닭을 찾아 다시 하면 된다는 것을 알았다."],"title":"개요 「강변에서 다시 띄운 연」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#1','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C30',1,'mc','auto','직접 만나지 않아도 짧은 말을 빠르게 주고받고, 그림말로 기분을 나타낼 수 있는 매체는 어느 것인가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X28']::text[],false,'{"seq":1,"concept":"K5-2-u2-C30","difficulty":1,"kind":"mc","stem":"직접 만나지 않아도 짧은 말을 빠르게 주고받고, 그림말로 기분을 나타낼 수 있는 매체는 어느 것인가요?","options":[{"t":"휴대 전화 메시지","correct":true},{"t":"전자 우편","mis":"K5-2-u2-X29"},{"t":"학급 누리집","mis":"K5-2-u2-X28"},{"t":"종이 신문","mis":"K5-2-u2-X28"}],"explanation":["제목 · 인사를 갖춰요.","반 모두가 함께 봐요.","짧고 빠르게 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#2','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C31',1,'mc','auto','받는 사람 주소를 정확히 써야 보내지고, 제목 · 첫인사 · 끝인사를 갖추는 매체는 어느 것인가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X28']::text[],false,'{"seq":2,"concept":"K5-2-u2-C31","difficulty":1,"kind":"mc","stem":"받는 사람 주소를 정확히 써야 보내지고, 제목 · 첫인사 · 끝인사를 갖추는 매체는 어느 것인가요?","options":[{"t":"전자 우편","correct":true},{"t":"휴대 전화 메시지","mis":"K5-2-u2-X29"},{"t":"학급 누리집 댓글","mis":"K5-2-u2-X28"},{"t":"교실 게시판 쪽지","mis":"K5-2-u2-X28"}],"explanation":["짧고 친근하게 써요.","댓글은 짧은 의견이에요.","편지글처럼 갖춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#3','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C32',1,'ox','auto','학급 누리집은 같은 반 선생님 · 학생 · 학부모가 함께 보는 공간이에요.',ARRAY['K5-2-u2-X31']::text[],false,'{"seq":3,"concept":"K5-2-u2-C32","difficulty":1,"kind":"ox","stem":"학급 누리집은 같은 반 선생님 · 학생 · 학부모가 함께 보는 공간이에요.","answer":"O","reason_options":[{"t":"같은 반 사람들이 함께 쓰고 보는 곳이기 때문에","correct":true},{"t":"학급 누리집은 나만 보는 일기장이기 때문에","mis":"K5-2-u2-X31"}],"mis":"K5-2-u2-X31","explanation":["함께 봐요.","그래서 지킬 점이 있어요.","나만 보는 곳이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#4','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C29',1,'mc','auto','전학 간 친구에게 생일 축하를 빠르게 전하려면 어떤 매체가 알맞을까요?',ARRAY['K5-2-u2-X28']::text[],false,'{"seq":4,"concept":"K5-2-u2-C29","difficulty":1,"kind":"mc","stem":"전학 간 친구에게 생일 축하를 빠르게 전하려면 어떤 매체가 알맞을까요?","options":[{"t":"휴대 전화 메시지","correct":true},{"t":"어린이 잡지 독자 마당","mis":"K5-2-u2-X28"},{"t":"학급 누리집 공지","mis":"K5-2-u2-X28"},{"t":"대회 응모 전자 우편","mis":"K5-2-u2-X28"}],"explanation":["친구 한 명에게 전하기엔 멀어요.","우리 반 공간이에요.","한 사람에게 빠르게 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#5','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C30',2,'mc','auto','하람이의 메시지에서 하람이의 마음을 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u2-X29']::text[],false,'{"seq":5,"concept":"K5-2-u2-C30","difficulty":2,"kind":"mc","stem":"하람이의 메시지에서 하람이의 마음을 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"「다행이다!」라는 말과 손 모은 그림말","correct":true},{"t":"「집에 와 보니」라는 말","mis":"K5-2-u2-X29"},{"t":"실내화 주머니의 색","mis":"K5-2-u2-X29"},{"t":"메시지를 보낸 사람의 이름","mis":"K5-2-u2-X29"}],"explanation":["지유의 말이에요.","마음과 관계없어요.","말과 그림말로 마음을 드러내요."],"asset":{"type":"speech","turns":[{"who":"지유","text":"집에 와 보니 내 가방에 네 실내화 주머니가 있어! 색이 똑같아서 바뀌었나 봐 😅"},{"who":"하람","text":"찾고 있었는데 다행이다! 알려 줘서 고마워 🙏 내일 아침에 바꾸자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#6','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C31',2,'mc','auto','이 전자 우편의 제목을 이렇게 쓴 까닭은 무엇인가요?',ARRAY['K5-2-u2-X30']::text[],false,'{"seq":6,"concept":"K5-2-u2-C31","difficulty":2,"kind":"mc","stem":"이 전자 우편의 제목을 이렇게 쓴 까닭은 무엇인가요?","options":[{"t":"제목만 보고도 무슨 내용인지 짐작할 수 있게 하려고","correct":true},{"t":"제목은 길수록 좋아서","mis":"K5-2-u2-X30"},{"t":"받는 사람 주소를 대신하려고","mis":"K5-2-u2-X30"},{"t":"끝인사를 빼려고","mis":"K5-2-u2-X30"}],"explanation":["길이가 기준이 아니에요.","주소는 따로 써요.","제목으로 내용을 알려요."],"asset":{"type":"passage","lines":["받는 사람 — 어린이 과학 잡지 편집부 (전자 우편 주소)","제목 — 「독자 마당」에 싣고 싶은 글과 그림을 보냅니다","첫인사 — 안녕하세요? 잡지를 즐겨 읽는 5학년 학생입니다.","내용 — 교실 텃밭을 가꾸며 겪은 일을 글과 그림으로 담았습니다.","첨부 자료 — 텃밭 글 한 개 · 텃밭 그림 한 개","끝인사 — 읽어 주셔서 감사합니다. ○○○ 드림"],"title":"전자 우편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#7','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C29',2,'match','auto','상황과 알맞은 매체를 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u2-C29","difficulty":2,"kind":"match","stem":"상황과 알맞은 매체를 이으세요.","pairs":[{"l":"약속 시간을 급하게 바꾸기","r":"휴대 전화 메시지"},{"l":"반 친구들 의견 모으기","r":"학급 누리집"},{"l":"글쓰기 대회에 작품 내기","r":"전자 우편"}],"mis":"K5-2-u2-X28","explanation":["빠르게 전해요.","함께 보고 댓글을 달아요.","공식적으로 첨부해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#8','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C33',2,'error','auto','학급 누리집에 올라온 글과 댓글이에요. 지킬 점을 어긴 것은 어느 것인가요?',ARRAY['K5-2-u2-X31','K5-2-u2-X33']::text[],false,'{"seq":8,"concept":"K5-2-u2-C33","difficulty":2,"kind":"error","stem":"학급 누리집에 올라온 글과 댓글이에요. 지킬 점을 어긴 것은 어느 것인가요?","options":[{"t":"「ㅋㅋㅋ 표정 완전 이상함」 — 익명","correct":true,"mis_target":"K5-2-u2-X31"},{"t":"「발표하는 모습이 잘 나왔어요! 고마워요.」 — 이○○","mis":"K5-2-u2-X33"},{"t":"「학급 발표회 사진을 올려요. 다들 멋졌어요!」 — 사진 담당 모둠","mis":"K5-2-u2-X33"}],"explanation":["고마움을 바르게 전했어요.","알리는 글이에요.","이름 없이 남을 깎아내렸어요."],"asset":{"type":"speech","turns":[{"who":"사진 담당 모둠","text":"〔학급 누리집〕 학급 발표회 사진을 올려요. 다들 멋졌어요!"},{"who":"이○○","text":"발표하는 모습이 잘 나왔어요! 고마워요."},{"who":"익명","text":"ㅋㅋㅋ 표정 완전 이상함"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#9','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C33',2,'mc','auto','학급 누리집에 친구 사진을 올리기 전에 꼭 해야 할 일은 어느 것인가요?',ARRAY['K5-2-u2-X31']::text[],false,'{"seq":9,"concept":"K5-2-u2-C33","difficulty":2,"kind":"mc","stem":"학급 누리집에 친구 사진을 올리기 전에 꼭 해야 할 일은 어느 것인가요?","options":[{"t":"사진 속 친구에게 올려도 되는지 허락받는다","correct":true},{"t":"사진을 가장 크게 키운다","mis":"K5-2-u2-X31"},{"t":"이름을 숨기고 익명으로 올린다","mis":"K5-2-u2-X31"},{"t":"친구의 전화번호를 함께 적는다","mis":"K5-2-u2-X31"}],"explanation":["크기는 중요하지 않아요.","누가 올렸는지 밝혀요.","개인 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_basic#10','kor',5,2,'u2','L07','g5_2_kor_u2_L07_basic','lesson_basic','K5-2-u2-C29',3,'mc','auto','「반 친구들 모두에게 도서관 새 책 소식을 알리고 의견도 듣고 싶다.」 이 상황에 가장 알맞은 매체와 까닭은 어느 것인가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X02']::text[],false,'{"seq":10,"concept":"K5-2-u2-C29","difficulty":3,"kind":"mc","stem":"「반 친구들 모두에게 도서관 새 책 소식을 알리고 의견도 듣고 싶다.」 이 상황에 가장 알맞은 매체와 까닭은 어느 것인가요?","options":[{"t":"학급 누리집 — 반 모두가 보고 댓글로 의견을 남길 수 있어서","correct":true},{"t":"휴대 전화 메시지 — 늘 가장 빠르니까","mis":"K5-2-u2-X28"},{"t":"전자 우편 — 언제나 가장 예의 바른 매체니까","mis":"K5-2-u2-X28"},{"t":"아무 매체나 — 매체는 글과 관계없으니까","mis":"K5-2-u2-X02"}],"explanation":["빠른 것만이 기준이 아니에요.","늘 그런 매체는 없어요.","상황에 맞는 매체를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#1','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C31',2,'mc','auto','전자 우편의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X30']::text[],false,'{"seq":1,"concept":"K5-2-u2-C31","difficulty":2,"kind":"mc","stem":"전자 우편의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"글 · 그림 · 동영상을 첨부하고 주고받은 편지를 보관하기 쉽다","correct":true},{"t":"그림말로만 대화한다","mis":"K5-2-u2-X29"},{"t":"반 친구 모두가 저절로 본다","mis":"K5-2-u2-X29"},{"t":"주소가 틀려도 잘 간다","mis":"K5-2-u2-X30"}],"explanation":["그건 메시지에 가까워요.","그건 누리집이에요.","주소는 정확해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#2','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C29',2,'ox','auto','학급 누리집은 언제나 휴대 전화 메시지보다 좋은 매체예요.',ARRAY['K5-2-u2-X28']::text[],false,'{"seq":2,"concept":"K5-2-u2-C29","difficulty":2,"kind":"ox","stem":"학급 누리집은 언제나 휴대 전화 메시지보다 좋은 매체예요.","answer":"X","reason_options":[{"t":"매체는 읽을 사람과 상황에 따라 알맞은 것을 골라야 하기 때문에","correct":true},{"t":"여러 사람이 볼 수 있는 매체가 늘 더 좋기 때문에","mis":"K5-2-u2-X28"}],"mis":"K5-2-u2-X28","explanation":["상황이 정해요.","한 사람에게 급히 알릴 땐 메시지가 나아요.","늘 좋은 매체는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#3','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C32',3,'mc','auto','학급 누리집이 반 친구들과 의견을 나누기에 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X28']::text[],false,'{"seq":3,"concept":"K5-2-u2-C32","difficulty":3,"kind":"mc","stem":"학급 누리집이 반 친구들과 의견을 나누기에 좋은 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"한 사람에게만 몰래 빠르게 전할 수 있다","correct":true},{"t":"댓글로 의견을 주고받을 수 있다","mis":"K5-2-u2-X28"},{"t":"글이 오래 기록으로 남는다","mis":"K5-2-u2-X28"},{"t":"반 모두가 같은 글을 볼 수 있다","mis":"K5-2-u2-X28"}],"explanation":["누리집의 특성이에요.","누리집의 특성이에요.","그건 메시지에 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#4','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C30',3,'mc','auto','휴대 전화 메시지를 쓸 때 주의할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X29']::text[],false,'{"seq":4,"concept":"K5-2-u2-C30","difficulty":3,"kind":"mc","stem":"휴대 전화 메시지를 쓸 때 주의할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"짧고 친근하게 쓰되 뜻이 헷갈리지 않게 쓰고, 그림말에만 기대지 않는다","correct":true},{"t":"그림말만 가득 보내 마음을 전한다","mis":"K5-2-u2-X29"},{"t":"공식적인 글도 메시지로만 보낸다","mis":"K5-2-u2-X29"},{"t":"줄임말을 많이 쓸수록 좋다","mis":"K5-2-u2-X29"}],"explanation":["뜻이 헷갈려요.","공식적인 글은 전자 우편이에요.","줄임말은 헷갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#5','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C31',3,'error','auto','어린이 잡지에 글을 보내려는 전자 우편 계획이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X30','K5-2-u2-X29']::text[],false,'{"seq":5,"concept":"K5-2-u2-C31","difficulty":3,"kind":"error","stem":"어린이 잡지에 글을 보내려는 전자 우편 계획이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「제목은 비워 두고 첫인사도 빼서 짧게 보내자.」","correct":true,"mis_target":"K5-2-u2-X30"},{"t":"「받는 사람 주소를 한 글자씩 확인하자.」","mis":"K5-2-u2-X29"},{"t":"「텃밭 글과 그림을 첨부 자료로 붙이자.」","mis":"K5-2-u2-X29"}],"explanation":["주소가 정확해야 해요.","첨부할 수 있어요.","제목과 인사를 갖춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#6','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C33',3,'mc','auto','학급 누리집에 인터넷에서 찾은 그림을 넣고 싶어요. 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u2-X33']::text[],false,'{"seq":6,"concept":"K5-2-u2-C33","difficulty":3,"kind":"mc","stem":"학급 누리집에 인터넷에서 찾은 그림을 넣고 싶어요. 알맞은 방법은 어느 것인가요?","options":[{"t":"써도 되는 그림인지 확인하고 출처를 밝힌다","correct":true},{"t":"내가 그린 것처럼 그냥 붙인다","mis":"K5-2-u2-X33"},{"t":"그림 위에 내 이름을 쓴다","mis":"K5-2-u2-X33"},{"t":"출처는 길어서 빼도 된다","mis":"K5-2-u2-X33"}],"explanation":["남의 것이에요.","내 것이 아니에요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#7','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C29',3,'mc','auto','같은 「텃밭 사진」이라도 상황에 따라 매체를 알맞게 고른 것은 어느 것인가요?',ARRAY['K5-2-u2-X28']::text[],false,'{"seq":7,"concept":"K5-2-u2-C29","difficulty":3,"kind":"mc","stem":"같은 「텃밭 사진」이라도 상황에 따라 매체를 알맞게 고른 것은 어느 것인가요?","options":[{"t":"할머니께 바로 보여 드리기 — 메시지 / 반 친구들과 함께 보기 — 누리집 / 잡지에 응모하기 — 전자 우편","correct":true},{"t":"셋 다 휴대 전화 메시지","mis":"K5-2-u2-X28"},{"t":"셋 다 학급 누리집","mis":"K5-2-u2-X28"},{"t":"셋 다 전자 우편","mis":"K5-2-u2-X28"}],"explanation":["응모엔 맞지 않아요.","할머니께 바로 보여 드리기엔 맞지 않아요.","상황마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#8','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C29',4,'essay','teacher','휴대 전화 메시지 · 전자 우편 · 학급 누리집의 특성을 하나씩 쓰고, 각 매체가 알맞은 상황을 예로 드세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C29","difficulty":4,"kind":"essay","stem":"휴대 전화 메시지 · 전자 우편 · 학급 누리집의 특성을 하나씩 쓰고, 각 매체가 알맞은 상황을 예로 드세요.","answer_guide":{"answer":"예: 휴대 전화 메시지는 짧은 말을 빠르게 주고받을 수 있어 친구와 약속 시간을 급히 바꿀 때 알맞다. 전자 우편은 제목 · 인사를 갖추고 파일을 첨부할 수 있어 대회에 작품을 낼 때 알맞다. 학급 누리집은 반 모두가 보고 댓글을 달 수 있어 체험 학습 장소에 대한 의견을 모을 때 알맞다.","scoring_points":["세 매체의 특성을 썼는가","각 매체에 알맞은 상황을 들었는가","특성과 상황이 이어지는가"]},"explanation":["특성을 써요.","상황을 들어요.","둘을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#9','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C33',4,'essay','teacher','학급 누리집 댓글 「ㅋㅋㅋ 표정 완전 이상함」(익명)이 무엇이 문제인지 두 가지 쓰고, 지킬 점에 맞게 바꿔 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C33","difficulty":4,"kind":"essay","stem":"학급 누리집 댓글 「ㅋㅋㅋ 표정 완전 이상함」(익명)이 무엇이 문제인지 두 가지 쓰고, 지킬 점에 맞게 바꿔 쓰세요.","answer_guide":{"answer":"예: 첫째, 이름을 밝히지 않고 남의 모습을 깎아내렸다. 둘째, 여러 사람이 보는 곳에 줄임말과 놀리는 말을 썼다. 바꿔 쓴 댓글 — 「발표할 때 모두 웃는 얼굴이라 보는 저도 즐거웠어요. 사진 올려 줘서 고마워요. — 김○○」","scoring_points":["문제 두 가지를 썼는가","이름 · 존중 · 바른 말 가운데 지킬 점을 짚었는가","지킬 점에 맞게 바꿔 썼는가"]},"explanation":["무엇이 문제인지 찾아요.","지킬 점을 떠올려요.","바꿔 써요."],"asset":{"type":"speech","turns":[{"who":"사진 담당 모둠","text":"〔학급 누리집〕 학급 발표회 사진을 올려요. 다들 멋졌어요!"},{"who":"이○○","text":"발표하는 모습이 잘 나왔어요! 고마워요."},{"who":"익명","text":"ㅋㅋㅋ 표정 완전 이상함"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L07_challenge#10','kor',5,2,'u2','L07','g5_2_kor_u2_L07_challenge','lesson_challenge','K5-2-u2-C31',4,'essay','teacher','어린이 과학 잡지에 내 그림을 보내는 전자 우편을 제목 · 첫인사 · 내용 · 첨부 자료 · 끝인사를 갖추어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C31","difficulty":4,"kind":"essay","stem":"어린이 과학 잡지에 내 그림을 보내는 전자 우편을 제목 · 첫인사 · 내용 · 첨부 자료 · 끝인사를 갖추어 쓰세요.","answer_guide":{"answer":"예: 제목 — 「독자 그림 마당」에 보내는 우리 동네 새 그림입니다. 첫인사 — 안녕하세요? 과학 잡지를 즐겨 읽는 5학년 학생입니다. 내용 — 학교 앞 공원에서 관찰한 새를 그림으로 그렸습니다. 독자 그림 마당에 실어 주시면 기쁘겠습니다. 첨부 자료 — 새 관찰 그림 한 개. 끝인사 — 읽어 주셔서 감사합니다. 김○○ 드림.","scoring_points":["제목이 내용을 알려 주는가","첫인사 · 끝인사를 갖추었는가","내용과 첨부 자료를 밝혔는가"]},"explanation":["제목을 정해요.","인사를 갖춰요.","내용과 첨부 자료를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#1','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C34',1,'mc','auto','도윤이가 학급 누리집에 글을 쓴 목적은 무엇인가요?',ARRAY['K5-2-u2-X34','K5-2-u2-X28']::text[],false,'{"seq":1,"concept":"K5-2-u2-C34","difficulty":1,"kind":"mc","stem":"도윤이가 학급 누리집에 글을 쓴 목적은 무엇인가요?","options":[{"t":"우산꽂이 정리 방법을 반 친구들과 함께 정하자고 제안하려고","correct":true},{"t":"친구에게 우산을 빌려 달라고 하려고","mis":"K5-2-u2-X34"},{"t":"잡지에 응모하려고","mis":"K5-2-u2-X28"},{"t":"혼자만 기억해 두려고","mis":"K5-2-u2-X34"}],"explanation":["한 사람에게 하는 부탁이 아니에요.","잡지 응모는 전자 우편이에요.","함께 정하자고 제안했어요."],"asset":{"type":"passage","lines":["〔제목〕 복도 우산꽂이, 이렇게 정리하면 어떨까요?","비 오는 날마다 우산이 뒤섞여 내 우산을 찾느라 늦은 적이 있나요?","우산꽂이 옆에 모둠별 고리를 달고 우산에 이름표를 붙이면 좋겠습니다.","사진처럼 고리를 달면 우산이 바닥에 떨어지지 않습니다. 〔사진〕","어떻게 생각하는지 댓글로 의견을 남겨 주세요. — 최도윤"],"title":"학급 누리집에 올린 제안하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#2','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C35',1,'mc','auto','학급 누리집에 올릴 글의 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X32']::text[],false,'{"seq":2,"concept":"K5-2-u2-C35","difficulty":1,"kind":"mc","stem":"학급 누리집에 올릴 글의 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"복도 우산꽂이, 이렇게 정리하면 어떨까요?","correct":true},{"t":"충격!!! 우리 반 큰일 났다","mis":"K5-2-u2-X32"},{"t":"글","mis":"K5-2-u2-X32"},{"t":"ㅇㅇ","mis":"K5-2-u2-X32"}],"explanation":["자극적이기만 해요.","내용을 알 수 없어요.","흥미와 핵심이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#3','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C36',1,'ox','auto','글에 쓸 자료를 가져올 때에는 출처를 밝혀야 해요.',ARRAY['K5-2-u2-X33']::text[],false,'{"seq":3,"concept":"K5-2-u2-C36","difficulty":1,"kind":"ox","stem":"글에 쓸 자료를 가져올 때에는 출처를 밝혀야 해요.","answer":"O","reason_options":[{"t":"남이 만든 자료이고, 읽는 사람이 믿을 수 있는지 확인할 수 있기 때문에","correct":true},{"t":"인터넷 자료는 누구 것도 아니기 때문에","mis":"K5-2-u2-X33"}],"mis":"K5-2-u2-X33","explanation":["남이 만든 자료예요.","믿을 수 있는지 알려 줘요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#4','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C37',1,'mc','auto','학급 누리집 제안하는 글의 「끝」에 들어갈 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X34','K5-2-u2-X32','K5-2-u2-X33']::text[],false,'{"seq":4,"concept":"K5-2-u2-C37","difficulty":1,"kind":"mc","stem":"학급 누리집 제안하는 글의 「끝」에 들어갈 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「어떻게 생각하는지 댓글로 의견을 남겨 주세요.」","correct":true},{"t":"「끝.」","mis":"K5-2-u2-X34"},{"t":"「충격적인 사실을 알려 드립니다!」","mis":"K5-2-u2-X32"},{"t":"「출처는 생략합니다.」","mis":"K5-2-u2-X33"}],"explanation":["참여 안내가 없어요.","처음에도 맞지 않아요.","정리하며 댓글 참여를 안내해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#5','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C35',2,'mc','auto','학급 누리집에서 제목이 특히 중요한 까닭은 무엇인가요?',ARRAY['K5-2-u2-X32']::text[],false,'{"seq":5,"concept":"K5-2-u2-C35","difficulty":2,"kind":"mc","stem":"학급 누리집에서 제목이 특히 중요한 까닭은 무엇인가요?","options":[{"t":"글이 많아 사람들이 제목을 보고 읽을지 정하기 때문에","correct":true},{"t":"제목만 있으면 내용은 없어도 되기 때문에","mis":"K5-2-u2-X32"},{"t":"제목이 길수록 칭찬받기 때문에","mis":"K5-2-u2-X32"},{"t":"제목은 아무도 보지 않기 때문에","mis":"K5-2-u2-X32"}],"explanation":["내용도 있어야 해요.","길이가 기준이 아니에요.","제목을 보고 골라 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#6','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C37',2,'mc','auto','제안하는 글의 「가운데」에 사진이나 그림을 넣으면 좋은 점은 무엇인가요?',ARRAY['K5-2-u2-X34','K5-2-u2-X33']::text[],false,'{"seq":6,"concept":"K5-2-u2-C37","difficulty":2,"kind":"mc","stem":"제안하는 글의 「가운데」에 사진이나 그림을 넣으면 좋은 점은 무엇인가요?","options":[{"t":"제안 내용을 한눈에 보여 주어 이해를 돕는다","correct":true},{"t":"글을 쓰지 않아도 된다","mis":"K5-2-u2-X34"},{"t":"출처를 밝히지 않아도 된다","mis":"K5-2-u2-X33"},{"t":"글이 길어 보인다","mis":"K5-2-u2-X34"}],"explanation":["글과 함께 써요.","출처는 밝혀요.","이해를 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#7','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C35',2,'error','auto','「책 바꿔 읽기 상자」 초안을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u2-X32','K5-2-u2-X15','K5-2-u2-X33']::text[],false,'{"seq":7,"concept":"K5-2-u2-C35","difficulty":2,"kind":"error","stem":"「책 바꿔 읽기 상자」 초안을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「제목은 눈길을 끄니 고치지 말고 그대로 두자.」","correct":true,"mis_target":"K5-2-u2-X32"},{"t":"「‘별로 재미있다’는 ‘별로 재미없다’로 고쳐야 해.」","mis":"K5-2-u2-X15"},{"t":"「가져온 그림의 출처를 밝혀야 해.」","mis":"K5-2-u2-X33"}],"explanation":["호응을 바로잡았어요.","출처를 밝혀요.","자극적이기만 한 제목은 고쳐요."],"asset":{"type":"passage","lines":["〔제목〕 충격!!! 우리 반 큰일 났다","요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미있다.","그래서 집에 있는 책을 바꿔 읽는 상자를 만들면 좋겠다.","인터넷에서 본 그림을 그대로 붙였다. 〔그림〕","끝."],"title":"학급 누리집에 올릴 글 초안 「책 바꿔 읽기 상자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#8','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C37',2,'match','auto','제안하는 글의 짜임과 들어갈 내용을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C37","difficulty":2,"kind":"match","stem":"제안하는 글의 짜임과 들어갈 내용을 이으세요.","pairs":[{"l":"처음","r":"교실 속 문제와 글을 쓴 까닭"},{"l":"가운데","r":"사진 · 그림으로 제안 내용 자세히"},{"l":"끝","r":"내용 정리와 댓글 참여 안내"}],"mis":"K5-2-u2-X34","explanation":["문제부터 꺼내요.","자세히 제안해요.","참여를 안내해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#9','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C38',2,'mc','auto','내가 만든 고쳐쓰기 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X40']::text[],false,'{"seq":9,"concept":"K5-2-u2-C38","difficulty":2,"kind":"mc","stem":"내가 만든 고쳐쓰기 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"다른 친구보다 글을 더 길게 썼나요?","correct":true},{"t":"매체의 특성에 알맞게 썼나요?","mis":"K5-2-u2-X40"},{"t":"제목이 흥미롭고 핵심을 담았나요?","mis":"K5-2-u2-X40"},{"t":"문장 성분의 호응이 어울리나요?","mis":"K5-2-u2-X40"}],"explanation":["좋은 기준이에요.","좋은 기준이에요.","길이 겨루기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_basic#10','kor',5,2,'u2','L09','g5_2_kor_u2_L09_basic','lesson_basic','K5-2-u2-C34',3,'mc','auto','학급 회의 시간에 말로 하는 것과 견주어, 학급 누리집에 제안하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X34','K5-2-u2-X32']::text[],false,'{"seq":10,"concept":"K5-2-u2-C34","difficulty":3,"kind":"mc","stem":"학급 회의 시간에 말로 하는 것과 견주어, 학급 누리집에 제안하는 글을 쓰면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구들이 시간을 두고 읽고 댓글로 의견을 남겨 한곳에 모아 견줄 수 있다","correct":true},{"t":"학급 회의는 이제 하지 않아도 된다","mis":"K5-2-u2-X28"},{"t":"반대 의견은 아무도 쓸 수 없다","mis":"K5-2-u2-X34"},{"t":"제목만 읽어도 모든 뜻이 전해진다","mis":"K5-2-u2-X32"}],"explanation":["회의가 필요 없어지지는 않아요.","다른 의견도 남길 수 있어요.","내용을 읽어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#1','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C36',2,'mc','auto','글에 쓸 자료로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X33']::text[],false,'{"seq":1,"concept":"K5-2-u2-C36","difficulty":2,"kind":"mc","stem":"글에 쓸 자료로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"믿을 만한 곳에서 낸 새로운 자료","correct":true},{"t":"누가 썼는지 모르는 오래된 글","mis":"K5-2-u2-X33"},{"t":"출처를 지운 그림","mis":"K5-2-u2-X33"},{"t":"친구가 지어낸 소문","mis":"K5-2-u2-X33"}],"explanation":["믿기 어려워요.","출처가 없어요.","믿을 만하고 새로운 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#2','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C34',2,'ox','auto','매체가 바뀌어도 글의 짜임과 표현은 늘 똑같아요.',ARRAY['K5-2-u2-X34']::text[],false,'{"seq":2,"concept":"K5-2-u2-C34","difficulty":2,"kind":"ox","stem":"매체가 바뀌어도 글의 짜임과 표현은 늘 똑같아요.","answer":"X","reason_options":[{"t":"읽을 사람과 매체의 특성에 따라 짜임과 표현이 달라지기 때문에","correct":true},{"t":"같은 내용이면 어디에 쓰든 똑같이 써야 하기 때문에","mis":"K5-2-u2-X34"}],"mis":"K5-2-u2-X34","explanation":["매체마다 달라요.","누리집 글은 댓글 안내로 맺어요.","읽을 사람에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#3','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C35',3,'mc','auto','초안의 제목을 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X32']::text[],false,'{"seq":3,"concept":"K5-2-u2-C35","difficulty":3,"kind":"mc","stem":"초안의 제목을 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반 책 바꿔 읽기 상자, 함께 만들어 볼까요?","correct":true},{"t":"충격!!! 읽으면 깜짝 놀랄 이야기","mis":"K5-2-u2-X32"},{"t":"책","mis":"K5-2-u2-X32"},{"t":"바꿔 읽기 상자 만들기 계획서 첫째 판 고친 판의 고친 판","mis":"K5-2-u2-X32"}],"explanation":["자극적이기만 해요.","핵심이 없어요.","흥미와 핵심을 담았어요."],"asset":{"type":"passage","lines":["〔제목〕 충격!!! 우리 반 큰일 났다","요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미있다.","그래서 집에 있는 책을 바꿔 읽는 상자를 만들면 좋겠다.","인터넷에서 본 그림을 그대로 붙였다. 〔그림〕","끝."],"title":"학급 누리집에 올릴 글 초안 「책 바꿔 읽기 상자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#4','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C37',3,'mc','auto','초안의 마지막 줄 「끝.」을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X34']::text[],false,'{"seq":4,"concept":"K5-2-u2-C37","difficulty":3,"kind":"mc","stem":"초안의 마지막 줄 「끝.」을 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"제안을 정리하고 「어떻게 생각하는지 댓글로 알려 주세요.」처럼 참여를 안내한다","correct":true},{"t":"「끝.」을 세 번 쓴다","mis":"K5-2-u2-X34"},{"t":"마지막 줄을 지운다","mis":"K5-2-u2-X34"},{"t":"「반대하면 안 됩니다.」로 맺는다","mis":"K5-2-u2-X34"}],"explanation":["달라진 게 없어요.","마무리가 없어요.","의견을 나누자고 안내해요."],"asset":{"type":"passage","lines":["〔제목〕 충격!!! 우리 반 큰일 났다","요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미있다.","그래서 집에 있는 책을 바꿔 읽는 상자를 만들면 좋겠다.","인터넷에서 본 그림을 그대로 붙였다. 〔그림〕","끝."],"title":"학급 누리집에 올릴 글 초안 「책 바꿔 읽기 상자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#5','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C36',3,'error','auto','학급 누리집에 글을 올리기 전에 한 생각이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X33','K5-2-u2-X40','K5-2-u2-X31']::text[],false,'{"seq":5,"concept":"K5-2-u2-C36","difficulty":3,"kind":"error","stem":"학급 누리집에 글을 올리기 전에 한 생각이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「인터넷 그림은 누구나 써도 되니 출처는 안 적을래.」","correct":true,"mis_target":"K5-2-u2-X33"},{"t":"「그림을 써도 되는지 확인하고 출처를 적을래.」","mis":"K5-2-u2-X40"},{"t":"「친구 얼굴이 나온 사진은 허락을 받을래.」","mis":"K5-2-u2-X31"}],"explanation":["바른 생각이에요.","바른 생각이에요.","출처를 밝혀야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#6','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C38',3,'mc','auto','고쳐쓰기에서 글의 내용 말고도 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X40','K5-2-u2-X29','K5-2-u2-X32']::text[],false,'{"seq":6,"concept":"K5-2-u2-C38","difficulty":3,"kind":"mc","stem":"고쳐쓰기에서 글의 내용 말고도 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"글자 크기 · 줄 간격처럼 화면에서 읽기 편한지","correct":true},{"t":"다른 친구보다 글이 긴지","mis":"K5-2-u2-X40"},{"t":"그림말을 가장 많이 넣었는지","mis":"K5-2-u2-X29"},{"t":"제목에 느낌표를 많이 달았는지","mis":"K5-2-u2-X32"}],"explanation":["길이 겨루기가 아니에요.","그림말이 많다고 좋지 않아요.","읽기 편한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#7','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C34',3,'mc','auto','「모둠 청소 당번표를 바꾸자」는 제안을 반 친구들과 함께 정하려고 해요. 매체와 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X02']::text[],false,'{"seq":7,"concept":"K5-2-u2-C34","difficulty":3,"kind":"mc","stem":"「모둠 청소 당번표를 바꾸자」는 제안을 반 친구들과 함께 정하려고 해요. 매체와 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학급 누리집 — 모두가 읽고 댓글로 서로 다른 의견을 남길 수 있어서","correct":true},{"t":"휴대 전화 메시지 — 한 친구에게만 빨리 보내면 되니까","mis":"K5-2-u2-X28"},{"t":"전자 우편 — 반 친구 모두에게 공식 문서로 보내야 하니까","mis":"K5-2-u2-X28"},{"t":"어느 매체든 상관없다 — 매체는 글과 관계없으니까","mis":"K5-2-u2-X02"}],"explanation":["모두의 의견이 필요해요.","반 안의 일이에요.","상황에 맞는 매체를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#8','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C37',4,'essay','teacher','우리 반에 제안하고 싶은 일을 하나 정해, 학급 누리집에 올릴 글의 제목과 처음-가운데-끝 개요를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C37","difficulty":4,"kind":"essay","stem":"우리 반에 제안하고 싶은 일을 하나 정해, 학급 누리집에 올릴 글의 제목과 처음-가운데-끝 개요를 쓰세요.","answer_guide":{"answer":"예: 제목 — 쉬는 시간 보드게임, 순서표로 함께 즐겨요! 처음 — 보드게임을 서로 먼저 하려다 다툰 일과 글을 쓴 까닭. 가운데 — 모둠별 순서표를 만들어 쓰는 방법을 표 그림과 함께 설명한다. 끝 — 제안을 정리하고 「순서표에 넣을 규칙을 댓글로 알려 주세요.」라고 참여를 안내한다.","scoring_points":["제목이 흥미와 핵심을 담았는가","처음 · 가운데 · 끝을 갖추었는가","끝에 댓글 참여 안내가 있는가"]},"explanation":["제목을 정해요.","짜임을 갖춰요.","참여를 안내해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#9','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C35',4,'essay','teacher','「충격!!! 우리 반 큰일 났다」 같은 제목이 알맞지 않은 까닭을 쓰고, 좋은 제목의 조건 두 가지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C35","difficulty":4,"kind":"essay","stem":"「충격!!! 우리 반 큰일 났다」 같은 제목이 알맞지 않은 까닭을 쓰고, 좋은 제목의 조건 두 가지를 쓰세요.","answer_guide":{"answer":"예: 이 제목은 눈길만 끌 뿐 무슨 내용인지 알 수 없고, 실제 내용과 달리 겁을 주어 읽는 사람을 속이는 느낌을 준다. 좋은 제목은 첫째, 읽고 싶어지도록 흥미를 끌어야 하고, 둘째, 글의 핵심 내용을 담아 내용과 어긋나지 않아야 한다.","scoring_points":["알맞지 않은 까닭을 썼는가","흥미를 끄는 조건을 썼는가","핵심 · 내용과 맞음을 썼는가"]},"explanation":["문제를 짚어요.","첫째 조건이에요.","둘째 조건이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L09_challenge#10','kor',5,2,'u2','L09','g5_2_kor_u2_L09_challenge','lesson_challenge','K5-2-u2-C38',4,'essay','teacher','학급 누리집 글을 고쳐 쓸 때 쓸 나만의 고쳐쓰기 기준 세 가지를 만들고, 그 기준을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C38","difficulty":4,"kind":"essay","stem":"학급 누리집 글을 고쳐 쓸 때 쓸 나만의 고쳐쓰기 기준 세 가지를 만들고, 그 기준을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 「처음에 문제 상황이 잘 드러났나?」 — 친구들이 왜 이 글을 읽어야 하는지 알게 하려고. 둘째, 「가져온 사진의 출처를 밝혔나?」 — 남의 자료를 바르게 쓰려고. 셋째, 「높임 표현과 ‘별로 · 전혀’의 호응이 맞나?」 — 내가 자주 틀리는 부분이라서.","scoring_points":["기준 세 가지를 만들었는가","기준이 매체 · 목적 · 제목 · 호응 등과 이어지는가","고른 까닭을 썼는가"]},"explanation":["기준을 만들어요.","배운 것과 이어요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#1','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C41',1,'mc','auto','칭찬 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":1,"concept":"K5-2-u2-C41","difficulty":1,"kind":"mc","stem":"칭찬 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「싹이 난 날을 사진과 날짜로 남겨서 자라는 모습이 한눈에 보여요!」","correct":true},{"t":"「좋아요」","mis":"K5-2-u2-X35"},{"t":"「맞춤법 두 개 틀렸어요.」","mis":"K5-2-u2-X36"},{"t":"「ㅋㅋ」","mis":"K5-2-u2-X35"}],"explanation":["근거가 없어요.","오늘은 지적하지 않아요.","어디가 왜 좋은지 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#2','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C42',1,'ox','auto','오늘 칭찬 댓글 쓰기에서는 틀린 곳을 찾아 알려 주는 것이 가장 중요해요.',ARRAY['K5-2-u2-X36']::text[],false,'{"seq":2,"concept":"K5-2-u2-C42","difficulty":1,"kind":"ox","stem":"오늘 칭찬 댓글 쓰기에서는 틀린 곳을 찾아 알려 주는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"오늘은 장점을 중심으로 쓰는 활동이기 때문에","correct":true},{"t":"틀린 곳을 알려 줘야 글이 좋아지기 때문에","mis":"K5-2-u2-X36"}],"mis":"K5-2-u2-X36","explanation":["오늘은 장점만요.","고쳐쓰기는 다른 시간에 해요.","칭찬으로 힘을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#3','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C39',1,'mc','auto','댓글을 올리기 전에 한 번 더 읽어 보아야 하는 까닭은 무엇인가요?',ARRAY['K5-2-u2-X37','K5-2-u2-X35']::text[],false,'{"seq":3,"concept":"K5-2-u2-C39","difficulty":1,"kind":"mc","stem":"댓글을 올리기 전에 한 번 더 읽어 보아야 하는 까닭은 무엇인가요?","options":[{"t":"여러 사람이 함께 보는 글이기 때문에","correct":true},{"t":"올린 뒤에는 아무도 안 보기 때문에","mis":"K5-2-u2-X37"},{"t":"댓글은 길수록 좋기 때문에","mis":"K5-2-u2-X35"},{"t":"고치기 기능이 없기 때문에","mis":"K5-2-u2-X37"}],"explanation":["여럿이 봐요.","길이가 기준이 아니에요.","여러 사람이 보니 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#4','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C40',1,'mc','auto','친구 글에서 칭찬할 곳을 찾을 때 살피는 곳이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u2-X35']::text[],false,'{"seq":4,"concept":"K5-2-u2-C40","difficulty":1,"kind":"mc","stem":"친구 글에서 칭찬할 곳을 찾을 때 살피는 곳이 아닌 것은 어느 것인가요?","options":[{"t":"글쓴이의 키와 생김새","correct":true},{"t":"글 전체 — 주제와 제목","mis":"K5-2-u2-X35"},{"t":"문단 — 차례와 자료","mis":"K5-2-u2-X35"},{"t":"문장과 낱말 — 호응과 표현","mis":"K5-2-u2-X35"}],"explanation":["살피는 곳이에요.","살피는 곳이에요.","글이 아니라 사람을 보는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#5','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C41',2,'mc','auto','오○○의 댓글은 글의 어느 부분을 칭찬한 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":5,"concept":"K5-2-u2-C41","difficulty":2,"kind":"mc","stem":"오○○의 댓글은 글의 어느 부분을 칭찬한 것인가요?","options":[{"t":"문장과 낱말의 표현","correct":true},{"t":"글 전체의 주제","mis":"K5-2-u2-X35"},{"t":"문단의 차례","mis":"K5-2-u2-X35"},{"t":"맞춤법","mis":"K5-2-u2-X36"}],"explanation":["한 문장을 칭찬했어요.","차례가 아니에요.","「기지개를 켰다」는 표현을 칭찬했어요."],"asset":{"type":"speech","turns":[{"who":"김○○","text":"싹이 난 날을 사진과 날짜로 남겨서 자라는 모습이 한눈에 보여요!"},{"who":"오○○","text":"「잎이 기지개를 켰다」는 문장 덕분에 싹이 눈앞에 그려졌어요."},{"who":"이○○","text":"좋아요"},{"who":"박○○","text":"맞춤법 두 개 틀렸어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#6','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C41',2,'mc','auto','「좋아요」를 구체적인 칭찬 댓글로 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":6,"concept":"K5-2-u2-C41","difficulty":2,"kind":"mc","stem":"「좋아요」를 구체적인 칭찬 댓글로 바꾼 것은 어느 것인가요?","options":[{"t":"「물 준 날을 표로 정리해서 언제 싹이 났는지 바로 알 수 있었어요.」","correct":true},{"t":"「좋아요 좋아요 좋아요」","mis":"K5-2-u2-X35"},{"t":"「최고!」","mis":"K5-2-u2-X35"},{"t":"「다음엔 글씨를 크게 써요.」","mis":"K5-2-u2-X36"}],"explanation":["되풀이일 뿐이에요.","근거가 없어요.","어디가 왜 좋은지 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#7','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C42',2,'error','auto','「모둠 화분 일지」에 달린 댓글 가운데 오늘 활동과 맞지 않는 것은 어느 것인가요?',ARRAY['K5-2-u2-X36','K5-2-u2-X35']::text[],false,'{"seq":7,"concept":"K5-2-u2-C42","difficulty":2,"kind":"error","stem":"「모둠 화분 일지」에 달린 댓글 가운데 오늘 활동과 맞지 않는 것은 어느 것인가요?","options":[{"t":"「맞춤법 두 개 틀렸어요.」 — 박○○","correct":true,"mis_target":"K5-2-u2-X36"},{"t":"「싹이 난 날을 사진과 날짜로 남겨서 자라는 모습이 한눈에 보여요!」 — 김○○","mis":"K5-2-u2-X35"},{"t":"「‘잎이 기지개를 켰다’는 문장 덕분에 싹이 눈앞에 그려졌어요.」 — 오○○","mis":"K5-2-u2-X35"}],"explanation":["자료를 칭찬했어요.","표현을 칭찬했어요.","오늘은 지적하지 않아요."],"asset":{"type":"speech","turns":[{"who":"김○○","text":"싹이 난 날을 사진과 날짜로 남겨서 자라는 모습이 한눈에 보여요!"},{"who":"오○○","text":"「잎이 기지개를 켰다」는 문장 덕분에 싹이 눈앞에 그려졌어요."},{"who":"이○○","text":"좋아요"},{"who":"박○○","text":"맞춤법 두 개 틀렸어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#8','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C39',2,'match','auto','댓글 기능과 하는 일을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C39","difficulty":2,"kind":"match","stem":"댓글 기능과 하는 일을 이으세요.","pairs":[{"l":"쓰기","r":"댓글 칸에 입력해 올리기"},{"l":"고치기","r":"올린 댓글 다듬기"},{"l":"지우기","r":"잘못 쓴 댓글 없애기"}],"mis":"K5-2-u2-X37","explanation":["올려요.","다듬어요.","없애요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#9','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C43',2,'mc','auto','디지털 안내문을 만들 때 가장 먼저 정할 것은 무엇인가요?',ARRAY['K5-2-u2-X38']::text[],false,'{"seq":9,"concept":"K5-2-u2-C43","difficulty":2,"kind":"mc","stem":"디지털 안내문을 만들 때 가장 먼저 정할 것은 무엇인가요?","options":[{"t":"알리고 싶은 내용과 읽을 사람","correct":true},{"t":"배경 색과 글꼴","mis":"K5-2-u2-X38"},{"t":"붙일 스티커 수","mis":"K5-2-u2-X38"},{"t":"안내문 크기","mis":"K5-2-u2-X38"}],"explanation":["꾸미기는 나중이에요.","꾸미기는 나중이에요.","무엇을 누구에게 알릴지가 먼저예요."],"asset":{"type":"passage","lines":["〔우리 반 안내문〕 잃어버린 물건, 이렇게 찾아요","분실물은 교실 뒤 「찾아가요 상자」에 모아 두어요.","금요일까지 주인이 없으면 학급 누리집에 사진을 올려요.","☑ 물건에 이름표 붙이기  ☑ 찾은 물건은 상자에 넣기"],"title":"디지털 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_basic#10','kor',5,2,'u2','L12','g5_2_kor_u2_L12_basic','lesson_basic','K5-2-u2-C40',3,'mc','auto','칭찬할 부분을 찾을 때 「어디가 왜 좋은지」를 메모해 두면 좋은 까닭은 무엇인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":10,"concept":"K5-2-u2-C40","difficulty":3,"kind":"mc","stem":"칭찬할 부분을 찾을 때 「어디가 왜 좋은지」를 메모해 두면 좋은 까닭은 무엇인가요?","options":[{"t":"근거가 분명한 구체적인 칭찬 댓글을 쓸 수 있어서","correct":true},{"t":"댓글을 짧게 끝낼 수 있어서","mis":"K5-2-u2-X35"},{"t":"틀린 곳을 찾기 쉬워서","mis":"K5-2-u2-X36"},{"t":"메모를 그대로 복사해 올리면 돼서","mis":"K5-2-u2-X35"}],"explanation":["짧게가 목적이 아니에요.","오늘은 장점이에요.","근거가 칭찬을 구체적으로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#1','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C43',2,'mc','auto','디지털 안내문에 글과 그림을 함께 쓰면 좋은 점은 무엇인가요?',ARRAY['K5-2-u2-X38']::text[],false,'{"seq":1,"concept":"K5-2-u2-C43","difficulty":2,"kind":"mc","stem":"디지털 안내문에 글과 그림을 함께 쓰면 좋은 점은 무엇인가요?","options":[{"t":"내용을 한눈에 알아보기 쉽다","correct":true},{"t":"글을 쓰지 않아도 된다","mis":"K5-2-u2-X38"},{"t":"꾸밀수록 내용은 덜 중요해진다","mis":"K5-2-u2-X38"},{"t":"읽을 사람이 누구든 상관없다","mis":"K5-2-u2-X38"}],"explanation":["글도 필요해요.","내용이 먼저예요.","읽을 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#2','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C41',2,'ox','auto','틀 문장 「특히 ○○ 부분이 인상 깊었습니다.」를 쓸 때 ○○을 그대로 두고 올려도 돼요.',ARRAY['K5-2-u2-X35']::text[],false,'{"seq":2,"concept":"K5-2-u2-C41","difficulty":2,"kind":"ox","stem":"틀 문장 「특히 ○○ 부분이 인상 깊었습니다.」를 쓸 때 ○○을 그대로 두고 올려도 돼요.","answer":"X","reason_options":[{"t":"○○에 친구 글의 내용을 넣어 내 말로 채워야 구체적인 칭찬이 되기 때문에","correct":true},{"t":"틀 문장을 그대로 쓰는 것이 가장 예의 바르기 때문에","mis":"K5-2-u2-X35"}],"mis":"K5-2-u2-X35","explanation":["빈칸을 채워요.","내 말로 채워요.","그래야 구체적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#3','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C42',3,'mc','auto','친구 글에서 고칠 점이 눈에 띄었어요. 오늘 칭찬 댓글 활동에서 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u2-X36','K5-2-u2-X31','K5-2-u2-X35']::text[],false,'{"seq":3,"concept":"K5-2-u2-C42","difficulty":3,"kind":"mc","stem":"친구 글에서 고칠 점이 눈에 띄었어요. 오늘 칭찬 댓글 활동에서 알맞은 태도는 어느 것인가요?","options":[{"t":"오늘은 장점을 근거와 함께 쓰고, 고칠 점은 고쳐쓰기 시간에 나눈다","correct":true},{"t":"칭찬보다 고칠 점을 먼저 길게 쓴다","mis":"K5-2-u2-X36"},{"t":"고칠 점을 익명으로 남긴다","mis":"K5-2-u2-X31"},{"t":"칭찬할 게 없으면 「좋아요」만 쓴다","mis":"K5-2-u2-X35"}],"explanation":["오늘 활동과 달라요.","이름 없이 쓰면 안 돼요.","장점을 찾아 근거를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#4','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C40',3,'mc','auto','「모둠 화분 일지」의 「물 준 날 · 싹 난 날」 표를 칭찬한다면 어디를 보고 칭찬한 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":4,"concept":"K5-2-u2-C40","difficulty":3,"kind":"mc","stem":"「모둠 화분 일지」의 「물 준 날 · 싹 난 날」 표를 칭찬한다면 어디를 보고 칭찬한 것인가요?","options":[{"t":"문단 — 자료가 잘 어울려요","correct":true},{"t":"글 전체 — 제목이 끌려요","mis":"K5-2-u2-X35"},{"t":"문장과 낱말 — 호응이 자연스러워요","mis":"K5-2-u2-X35"},{"t":"맞춤법 — 틀린 곳이 없어요","mis":"K5-2-u2-X36"}],"explanation":["제목이 아니에요.","문장이 아니에요.","표는 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#5','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C39',3,'error','auto','댓글을 올리려는 친구들의 생각이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X37','K5-2-u2-X35']::text[],false,'{"seq":5,"concept":"K5-2-u2-C39","difficulty":3,"kind":"error","stem":"댓글을 올리려는 친구들의 생각이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「올린 다음에 고치면 되니까 한 번도 안 읽고 바로 올리자.」","correct":true,"mis_target":"K5-2-u2-X37"},{"t":"「올리기 전에 한 번 더 읽고 예절에 맞는지 확인하자.」","mis":"K5-2-u2-X35"},{"t":"「잘못 쓴 댓글은 고치기나 지우기로 바로잡자.」","mis":"K5-2-u2-X35"}],"explanation":["바른 생각이에요.","바른 생각이에요.","올리기 전에 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#6','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C41',3,'mc','auto','구체적인 칭찬 댓글이 글쓴이에게 주는 도움으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X36','K5-2-u2-X35','K5-2-u2-X40']::text[],false,'{"seq":6,"concept":"K5-2-u2-C41","difficulty":3,"kind":"mc","stem":"구체적인 칭찬 댓글이 글쓴이에게 주는 도움으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 점이 잘되었는지 알게 되어 다음 글에서도 살릴 수 있다","correct":true},{"t":"글쓴이가 틀린 곳을 모두 알게 된다","mis":"K5-2-u2-X36"},{"t":"댓글 수가 많아진다","mis":"K5-2-u2-X35"},{"t":"글쓴이가 다시는 고쳐 쓰지 않아도 된다","mis":"K5-2-u2-X40"}],"explanation":["오늘은 장점이에요.","수가 목적이 아니에요.","잘된 점을 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#7','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C43',3,'mc','auto','「잃어버린 물건, 이렇게 찾아요」 안내문이 내용을 잘 전했는지 살펴볼 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X38']::text[],false,'{"seq":7,"concept":"K5-2-u2-C43","difficulty":3,"kind":"mc","stem":"「잃어버린 물건, 이렇게 찾아요」 안내문이 내용을 잘 전했는지 살펴볼 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「읽은 사람이 물건을 어디서 찾아야 하는지 바로 알 수 있나?」","correct":true},{"t":"「색을 몇 가지 썼나?」","mis":"K5-2-u2-X38"},{"t":"「글꼴이 가장 화려한가?」","mis":"K5-2-u2-X38"},{"t":"「스티커를 많이 붙였나?」","mis":"K5-2-u2-X38"}],"explanation":["꾸미기 물음이에요.","꾸미기 물음이에요.","전달이 잘되었는지 물어요."],"asset":{"type":"passage","lines":["〔우리 반 안내문〕 잃어버린 물건, 이렇게 찾아요","분실물은 교실 뒤 「찾아가요 상자」에 모아 두어요.","금요일까지 주인이 없으면 학급 누리집에 사진을 올려요.","☑ 물건에 이름표 붙이기  ☑ 찾은 물건은 상자에 넣기"],"title":"디지털 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#8','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C41',4,'essay','teacher','친구가 학급 누리집에 올린 글이 있다고 생각하고, 칭찬할 곳 두 군데를 정해 구체적인 칭찬 댓글 두 개를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u2-C41","difficulty":4,"kind":"essay","stem":"친구가 학급 누리집에 올린 글이 있다고 생각하고, 칭찬할 곳 두 군데를 정해 구체적인 칭찬 댓글 두 개를 쓰세요.","answer_guide":{"answer":"예: 「‘우산 이름표’ 제안 덕분에 내 우산을 쉽게 찾을 방법을 생각해 보았습니다.」(글 전체 — 주제) 「고리를 단 사진을 넣어서 제안이 한눈에 그려졌어요.」(문단 — 자료)","scoring_points":["칭찬할 곳 두 군데를 정했는가","댓글마다 근거가 있는가","어디가 왜 좋은지 구체적으로 썼는가"]},"explanation":["칭찬할 곳을 정해요.","근거를 들어요.","구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#9','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C42',4,'essay','teacher','칭찬 댓글 「맞춤법 두 개 틀렸어요.」가 오늘 활동에 맞지 않는 까닭을 쓰고, 같은 글에 달 칭찬 댓글로 바꿔 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u2-C42","difficulty":4,"kind":"essay","stem":"칭찬 댓글 「맞춤법 두 개 틀렸어요.」가 오늘 활동에 맞지 않는 까닭을 쓰고, 같은 글에 달 칭찬 댓글로 바꿔 쓰세요.","answer_guide":{"answer":"예: 오늘은 친구 글의 장점을 찾아 근거를 들어 칭찬하는 활동인데, 이 댓글은 틀린 곳만 지적해 글쓴이의 힘을 빼고 무엇이 좋았는지 알려 주지 않는다. 바꿔 쓴 댓글 — 「싹이 난 날짜를 꼬박꼬박 적어서 화분이 자란 과정을 따라가며 읽는 재미가 있었어요.」","scoring_points":["맞지 않는 까닭을 썼는가","바꾼 댓글에 근거가 있는가","장점을 중심으로 썼는가"]},"explanation":["활동 목적을 떠올려요.","근거를 넣어요.","장점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_L12_challenge#10','kor',5,2,'u2','L12','g5_2_kor_u2_L12_challenge','lesson_challenge','K5-2-u2-C43',4,'essay','teacher','우리 반에 알리고 싶은 내용을 하나 정해, 디지털 안내문의 제목 · 읽을 사람 · 넣을 글과 그림을 계획해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u2-C43","difficulty":4,"kind":"essay","stem":"우리 반에 알리고 싶은 내용을 하나 정해, 디지털 안내문의 제목 · 읽을 사람 · 넣을 글과 그림을 계획해 쓰세요.","answer_guide":{"answer":"예: 제목 — 우리 반 화분 물 주기, 이렇게 해요! 읽을 사람 — 반 친구들. 넣을 글 — 요일별 물 주기 당번과 물의 양. 넣을 그림 — 물뿌리개 그림과 당번표. 글과 그림을 함께 넣어 한눈에 알아보게 하고, 다 만든 뒤 친구에게 읽혀 잘 전달되는지 확인하겠다.","scoring_points":["제목과 읽을 사람을 정했는가","넣을 글과 그림을 계획했는가","전달이 잘되는지 살필 방법이 있는가"]},"explanation":["제목과 읽을 사람이에요.","글과 그림을 정해요.","전달을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#1','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C4',1,'mc','auto','「고양이가 생선을 먹는다.」에서 주어는 어느 것인가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X06','K5-2-u2-X04']::text[],false,'{"seq":1,"concept":"K5-2-u2-C4","difficulty":1,"kind":"mc","stem":"「고양이가 생선을 먹는다.」에서 주어는 어느 것인가요?","options":[{"t":"고양이가","correct":true},{"t":"생선을","mis":"K5-2-u2-X07"},{"t":"먹는다","mis":"K5-2-u2-X06"},{"t":"주어가 없다","mis":"K5-2-u2-X04"}],"explanation":["목적어예요.","서술어예요.","누가 먹는지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#2','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C5',1,'mc','auto','「동생은 귀엽다.」의 서술어는 무엇을 알려 주나요?',ARRAY['K5-2-u2-X05','K5-2-u2-X06']::text[],false,'{"seq":2,"concept":"K5-2-u2-C5","difficulty":1,"kind":"mc","stem":"「동생은 귀엽다.」의 서술어는 무엇을 알려 주나요?","options":[{"t":"동생이 어떠한지","correct":true},{"t":"동생이 어찌하는지","mis":"K5-2-u2-X05"},{"t":"동생이 무엇인지","mis":"K5-2-u2-X05"},{"t":"누가 귀여운지","mis":"K5-2-u2-X06"}],"explanation":["움직임이 아니에요.","무엇이다가 아니에요.","어떠한지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
