INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#4','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C16',1,'blank','auto','「나는 매운 음식을 전혀 (     ).」에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X15','K5-2-u2-X14']::text[],false,'{"seq":4,"concept":"K5-2-u2-C16","difficulty":1,"kind":"blank","stem":"「나는 매운 음식을 전혀 (     ).」에 알맞은 말은 어느 것인가요?","options":[{"t":"먹지 못한다","correct":true},{"t":"먹는다","mis":"K5-2-u2-X15"},{"t":"잘 먹는다","mis":"K5-2-u2-X15"},{"t":"먹어야 한다","mis":"K5-2-u2-X14"}],"explanation":["부정하는 말이 없어요.","부정하는 말이 없어요.","전혀 + 부정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#5','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C19',1,'mc','auto','「내일」과 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X18']::text[],false,'{"seq":5,"concept":"K5-2-u2-C19","difficulty":1,"kind":"mc","stem":"「내일」과 어울리는 문장은 어느 것인가요?","options":[{"t":"내일 박물관에 갈 것이다.","correct":true},{"t":"내일 박물관에 갔다.","mis":"K5-2-u2-X18"},{"t":"내일 박물관에 갔었다.","mis":"K5-2-u2-X18"},{"t":"내일 박물관에 다녀왔다.","mis":"K5-2-u2-X18"}],"explanation":["지난 일이에요.","지난 일이에요.","앞으로의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#6','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C32',1,'mc','auto','반 친구들이 함께 보고 댓글로 의견을 나누며 글이 오래 기록으로 남는 매체는 어느 것인가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X28']::text[],false,'{"seq":6,"concept":"K5-2-u2-C32","difficulty":1,"kind":"mc","stem":"반 친구들이 함께 보고 댓글로 의견을 나누며 글이 오래 기록으로 남는 매체는 어느 것인가요?","options":[{"t":"학급 누리집","correct":true},{"t":"휴대 전화 메시지","mis":"K5-2-u2-X29"},{"t":"전자 우편","mis":"K5-2-u2-X29"},{"t":"손으로 쓴 쪽지","mis":"K5-2-u2-X28"}],"explanation":["한 사람과 빠르게예요.","공식적으로 보내요.","반 모두가 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#7','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C44',1,'mc','auto','이름 없는 계정이 집 주소를 물었을 때 알맞은 대답은 어느 것인가요?',ARRAY['K5-2-u2-X39']::text[],false,'{"seq":7,"concept":"K5-2-u2-C44","difficulty":1,"kind":"mc","stem":"이름 없는 계정이 집 주소를 물었을 때 알맞은 대답은 어느 것인가요?","options":[{"t":"「미안하지만 개인 정보는 보낼 수 없어.」","correct":true},{"t":"「응, 지금 알려 줄게.」","mis":"K5-2-u2-X39"},{"t":"「전화번호도 같이 줄까?」","mis":"K5-2-u2-X39"},{"t":"「사진도 보내 줄게.」","mis":"K5-2-u2-X39"}],"explanation":["알려 주면 안 돼요.","전화번호도 개인 정보예요.","정중하지만 분명히 거절해요."],"asset":{"type":"speech","turns":[{"who":"이름 없는 계정","text":"너 ○○초 다니지? 집 주소 좀 알려 줘."},{"who":"소희","text":"미안하지만 개인 정보는 온라인에서 보내지 않기로 했어."},{"who":"이름 없는 계정","text":"사진 한 장만 보내 주면 선물 줄게."},{"who":"소희","text":"부모님께 먼저 여쭤봐야 해. 더는 답하지 않을게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#8','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C41',1,'mc','auto','구체적인 칭찬 댓글은 어느 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":8,"concept":"K5-2-u2-C41","difficulty":1,"kind":"mc","stem":"구체적인 칭찬 댓글은 어느 것인가요?","options":[{"t":"「표로 정리해서 자란 과정을 한눈에 볼 수 있었어요.」","correct":true},{"t":"「좋아요」","mis":"K5-2-u2-X35"},{"t":"「굿」","mis":"K5-2-u2-X35"},{"t":"「틀린 글자가 있어요.」","mis":"K5-2-u2-X36"}],"explanation":["근거가 없어요.","근거가 없어요.","어디가 왜 좋은지 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#9','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C8',2,'mc','auto','「지호가 꽃을 드렸다.」에 더 있어야 뜻이 분명해지는 말은 무엇인가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X04','K5-2-u2-X06']::text[],false,'{"seq":9,"concept":"K5-2-u2-C8","difficulty":2,"kind":"mc","stem":"「지호가 꽃을 드렸다.」에 더 있어야 뜻이 분명해지는 말은 무엇인가요?","options":[{"t":"누구에게 드렸는지 (예: 할머니께)","correct":true},{"t":"무엇을 드렸는지 (예: 꽃을)","mis":"K5-2-u2-X07"},{"t":"누가 드렸는지 (예: 지호가)","mis":"K5-2-u2-X04"},{"t":"어찌했는지 (예: 드렸다)","mis":"K5-2-u2-X06"}],"explanation":["이미 있어요.","이미 있어요.","드리다는 누구에게가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#10','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C20',2,'mc','auto','「아버지가 신문을 읽는다.」를 높임 표현에 맞게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X19']::text[],false,'{"seq":10,"concept":"K5-2-u2-C20","difficulty":2,"kind":"mc","stem":"「아버지가 신문을 읽는다.」를 높임 표현에 맞게 고친 것은 어느 것인가요?","options":[{"t":"아버지께서 신문을 읽으신다.","correct":true},{"t":"아버지께서 신문을 읽는다.","mis":"K5-2-u2-X19"},{"t":"아버지가 신문을 읽는다고 하셨다.","mis":"K5-2-u2-X19"},{"t":"아버지께 신문을 읽는다.","mis":"K5-2-u2-X19"}],"explanation":["서술어도 높여요.","뜻이 바뀌었어요.","께서 + -시-예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
