INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#12','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C21',2,'mc','auto','「내 꿈은 커서 수의사가 되고 싶다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X20']::text[],false,'{"seq":12,"concept":"K5-2-u2-C21","difficulty":2,"kind":"mc","stem":"「내 꿈은 커서 수의사가 되고 싶다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"내 꿈은 커서 수의사가 되는 것이다.","correct":true},{"t":"내 꿈은 커서 수의사가 되고 싶었다.","mis":"K5-2-u2-X20"},{"t":"내 꿈은 커서 수의사가 될 것 같다.","mis":"K5-2-u2-X20"},{"t":"내 꿈은 커서 수의사다 싶다.","mis":"K5-2-u2-X20"}],"explanation":["끝맺음이 그대로예요.","짐작이에요.","꿈은 ~는 것이다예요."],"asset":{"type":"passage","lines":["서윤이는 장갑과 목도리를 끼고 나섰다.","우리 고양이는 목욕을 별로 좋아한다.","내 꿈은 커서 수의사가 되고 싶다."],"title":"「서윤이의 아침」 속 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#13','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C14',2,'mc','auto','「언니는 모자와 장갑을 쓰고 나갔다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X13','K5-2-u2-X12']::text[],false,'{"seq":13,"concept":"K5-2-u2-C14","difficulty":2,"kind":"mc","stem":"「언니는 모자와 장갑을 쓰고 나갔다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"언니는 모자를 쓰고 장갑을 끼고 나갔다.","correct":true},{"t":"언니는 모자와 장갑을 끼고 나갔다.","mis":"K5-2-u2-X13"},{"t":"언니는 모자와 장갑을 신고 나갔다.","mis":"K5-2-u2-X13"},{"t":"언니는 모자를 끼고 장갑을 쓰고 나갔다.","mis":"K5-2-u2-X12"}],"explanation":["모자는 끼지 않아요.","둘 다 어울리지 않아요.","각각 어울리는 서술어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#14','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C29',2,'mc','auto','반 친구들에게 체육 대회 응원 구호 의견을 모으려면 어떤 매체가 알맞은가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X02']::text[],false,'{"seq":14,"concept":"K5-2-u2-C29","difficulty":2,"kind":"mc","stem":"반 친구들에게 체육 대회 응원 구호 의견을 모으려면 어떤 매체가 알맞은가요?","options":[{"t":"학급 누리집","correct":true},{"t":"한 친구에게만 보내는 휴대 전화 메시지","mis":"K5-2-u2-X28"},{"t":"잡지사에 보내는 전자 우편","mis":"K5-2-u2-X28"},{"t":"아무 매체도 쓰지 않는다","mis":"K5-2-u2-X02"}],"explanation":["모두의 의견이 필요해요.","반 안의 일이에요.","함께 보고 댓글을 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#15','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C26',2,'mc','auto','경험 글의 「끝」에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":15,"concept":"K5-2-u2-C26","difficulty":2,"kind":"mc","stem":"경험 글의 「끝」에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"배우거나 느낀 점과 다짐","correct":true},{"t":"언제 어디서 누구와 갔는지","mis":"K5-2-u2-X25"},{"t":"일어난 일을 자세히","mis":"K5-2-u2-X25"},{"t":"글의 제목","mis":"K5-2-u2-X25"}],"explanation":["처음이에요.","가운데예요.","끝은 돌아보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#16','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C44',2,'mc','auto','소희의 대답이 알맞은 까닭은 무엇인가요?',ARRAY['K5-2-u2-X39']::text[],false,'{"seq":16,"concept":"K5-2-u2-C44","difficulty":2,"kind":"mc","stem":"소희의 대답이 알맞은 까닭은 무엇인가요?","options":[{"t":"정중하지만 분명하게 거절하고 개인 정보를 지켰기 때문에","correct":true},{"t":"모르는 사람과 친해지려고 했기 때문에","mis":"K5-2-u2-X39"},{"t":"선물을 받으려고 사진을 보냈기 때문에","mis":"K5-2-u2-X39"},{"t":"온라인을 아예 쓰지 않겠다고 했기 때문에","mis":"K5-2-u2-X39"}],"explanation":["거절했어요.","보내지 않았어요.","안전하게 거절했어요."],"asset":{"type":"speech","turns":[{"who":"이름 없는 계정","text":"너 ○○초 다니지? 집 주소 좀 알려 줘."},{"who":"소희","text":"미안하지만 개인 정보는 온라인에서 보내지 않기로 했어."},{"who":"이름 없는 계정","text":"사진 한 장만 보내 주면 선물 줄게."},{"who":"소희","text":"부모님께 먼저 여쭤봐야 해. 더는 답하지 않을게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#17','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C22',3,'mc','auto','「서윤이의 아침」 세 문장을 고친 까닭을 차례대로 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u2-X19','K5-2-u2-X01','K5-2-u2-X10']::text[],false,'{"seq":17,"concept":"K5-2-u2-C22","difficulty":3,"kind":"mc","stem":"「서윤이의 아침」 세 문장을 고친 까닭을 차례대로 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"목적어마다 서술어 · 「별로」와 부정하는 말 · 「꿈은」과 「~는 것이다」","correct":true},{"t":"높임 표현 · 시간 표현 · 높임 표현","mis":"K5-2-u2-X19"},{"t":"주어 빠짐 · 목적어 빠짐 · 서술어 빠짐","mis":"K5-2-u2-X01"},{"t":"맞춤법 · 띄어쓰기 · 문장 부호","mis":"K5-2-u2-X10"}],"explanation":["높임과 관계없어요.","빠진 말은 없어요.","호응을 맞췄어요."],"asset":{"type":"passage","lines":["서윤이는 장갑과 목도리를 끼고 나섰다.","우리 고양이는 목욕을 별로 좋아한다.","내 꿈은 커서 수의사가 되고 싶다."],"title":"「서윤이의 아침」 속 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#18','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C19',3,'mc','auto','「고구마 캔 날」에서 시간 표현이 어색한 문장은 어느 것인가요?',ARRAY['K5-2-u2-X18','K5-2-u2-X15','K5-2-u2-X19']::text[],false,'{"seq":18,"concept":"K5-2-u2-C19","difficulty":3,"kind":"mc","stem":"「고구마 캔 날」에서 시간 표현이 어색한 문장은 어느 것인가요?","options":[{"t":"다음 주에는 고구마로 간식을 만들었다.","correct":true},{"t":"지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","mis":"K5-2-u2-X18"},{"t":"고구마가 생각보다 커서 여간 놀랐다.","mis":"K5-2-u2-X15"},{"t":"선생님이 호미 쓰는 법을 알려 주었다.","mis":"K5-2-u2-X19"}],"explanation":["지난 일이라 알맞아요.","시간이 아니라 여간이 문제예요.","다음 주는 앞으로의 일이에요."],"asset":{"type":"passage","lines":["지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","선생님이 호미 쓰는 법을 알려 주었다.","나는 호미와 장갑을 끼고 흙을 팠다.","고구마가 생각보다 커서 여간 놀랐다.","다음 주에는 고구마로 간식을 만들었다."],"title":"경험을 쓴 글 「고구마 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#19','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C29',3,'mc','auto','「반 체험 학습 사진」을 나누는 상황과 매체가 알맞게 짝지어지지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X28']::text[],false,'{"seq":19,"concept":"K5-2-u2-C29","difficulty":3,"kind":"mc","stem":"「반 체험 학습 사진」을 나누는 상황과 매체가 알맞게 짝지어지지 않은 것은 어느 것인가요?","options":[{"t":"사진 공모전에 응모하기 — 휴대 전화 메시지","correct":true},{"t":"반 친구들과 함께 보며 댓글 달기 — 학급 누리집","mis":"K5-2-u2-X28"},{"t":"아파서 못 온 친구에게 바로 보여 주기 — 휴대 전화 메시지","mis":"K5-2-u2-X28"},{"t":"박물관에 사진을 써도 되는지 묻기 — 전자 우편","mis":"K5-2-u2-X28"}],"explanation":["알맞아요.","알맞아요.","응모는 전자 우편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#20','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C37',3,'mc','auto','도윤이의 글이 제안하는 글의 짜임을 잘 갖춘 까닭은 무엇인가요?',ARRAY['K5-2-u2-X32','K5-2-u2-X33','K5-2-u2-X34']::text[],false,'{"seq":20,"concept":"K5-2-u2-C37","difficulty":3,"kind":"mc","stem":"도윤이의 글이 제안하는 글의 짜임을 잘 갖춘 까닭은 무엇인가요?","options":[{"t":"문제 상황을 묻고 → 사진과 함께 제안하고 → 댓글로 의견을 남겨 달라고 안내해서","correct":true},{"t":"제목만 보고도 모든 내용을 다 알 수 있어서","mis":"K5-2-u2-X32"},{"t":"출처 없이 사진을 써서","mis":"K5-2-u2-X33"},{"t":"끝을 「끝.」으로 맺어서","mis":"K5-2-u2-X34"}],"explanation":["내용도 읽어야 해요.","출처는 밝혀요.","참여 안내가 있어요."],"asset":{"type":"passage","lines":["〔제목〕 복도 우산꽂이, 이렇게 정리하면 어떨까요?","비 오는 날마다 우산이 뒤섞여 내 우산을 찾느라 늦은 적이 있나요?","우산꽂이 옆에 모둠별 고리를 달고 우산에 이름표를 붙이면 좋겠습니다.","사진처럼 고리를 달면 우산이 바닥에 떨어지지 않습니다. 〔사진〕","어떻게 생각하는지 댓글로 의견을 남겨 주세요. — 최도윤"],"title":"학급 누리집에 올린 제안하는 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#21','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C40',3,'mc','auto','김○○의 댓글은 어디를 보고 칭찬한 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":21,"concept":"K5-2-u2-C40","difficulty":3,"kind":"mc","stem":"김○○의 댓글은 어디를 보고 칭찬한 것인가요?","options":[{"t":"문단 — 사진과 날짜 자료가 잘 어울린다","correct":true},{"t":"문장과 낱말 — 생생한 낱말","mis":"K5-2-u2-X35"},{"t":"맞춤법 — 틀린 곳이 없다","mis":"K5-2-u2-X36"},{"t":"글 전체 — 제목이 끌린다","mis":"K5-2-u2-X35"}],"explanation":["낱말이 아니에요.","오늘은 맞춤법을 보지 않아요.","자료를 칭찬했어요."],"asset":{"type":"speech","turns":[{"who":"김○○","text":"싹이 난 날을 사진과 날짜로 남겨서 자라는 모습이 한눈에 보여요!"},{"who":"오○○","text":"「잎이 기지개를 켰다」는 문장 덕분에 싹이 눈앞에 그려졌어요."},{"who":"이○○","text":"좋아요"},{"who":"박○○","text":"맞춤법 두 개 틀렸어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#22','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C24',3,'mc','auto','경험 글의 글감을 고른 친구들 가운데 가장 알맞게 고른 것은 어느 것인가요?',ARRAY['K5-2-u2-X23','K5-2-u2-X22']::text[],false,'{"seq":22,"concept":"K5-2-u2-C24","difficulty":3,"kind":"mc","stem":"경험 글의 글감을 고른 친구들 가운데 가장 알맞게 고른 것은 어느 것인가요?","options":[{"t":"「할머니와 처음 김치를 담근 날」 — 그때의 냄새와 매운 손끝이 생생해서","correct":true},{"t":"「방학 동안 한 일 전부」 — 많을수록 좋아서","mis":"K5-2-u2-X23"},{"t":"「친구가 해 준 여행 이야기」 — 재미있어서","mis":"K5-2-u2-X22"},{"t":"「매일 아침 먹은 반찬」 — 빠짐없이 적을 수 있어서","mis":"K5-2-u2-X23"}],"explanation":["너무 많아요.","내 경험이 아니에요.","느낌이 생생한 한 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#23','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C22',4,'essay','teacher','「고구마 캔 날」에서 어색한 문장 네 개를 찾아 고쳐 쓰고, 각각 어색한 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u2-C22","difficulty":4,"kind":"essay","stem":"「고구마 캔 날」에서 어색한 문장 네 개를 찾아 고쳐 쓰고, 각각 어색한 까닭을 쓰세요.","answer_guide":{"answer":"예: 「선생님께서 호미 쓰는 법을 알려 주셨다.」 — 높일 분이 주어라 서술어도 높인다. 「나는 호미를 들고 장갑을 끼고 흙을 팠다.」 — 호미는 「끼다」와 어울리지 않는다. 「고구마가 생각보다 커서 여간 놀라운 일이 아니었다.」 — 「여간」 뒤에는 부정하는 말이 온다. 「다음 주에는 고구마로 간식을 만들 것이다.」 — 앞으로의 일이다.","scoring_points":["네 문장을 찾았는가","알맞게 고쳐 썼는가","높임 · 목적어 · 여간 · 시간 등 까닭을 썼는가"]},"explanation":["어색한 곳을 찾아요.","고쳐 써요.","까닭을 밝혀요."],"asset":{"type":"passage","lines":["지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","선생님이 호미 쓰는 법을 알려 주었다.","나는 호미와 장갑을 끼고 흙을 팠다.","고구마가 생각보다 커서 여간 놀랐다.","다음 주에는 고구마로 간식을 만들었다."],"title":"경험을 쓴 글 「고구마 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#24','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C29',4,'essay','teacher','「우리 반 텃밭에서 딴 방울토마토 소식」을 학급 누리집과 휴대 전화 메시지 가운데 어디에 올릴지 정하고, 그 매체의 특성에 맞추어 실제로 쓸 글을 제목과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u2-C29","difficulty":4,"kind":"essay","stem":"「우리 반 텃밭에서 딴 방울토마토 소식」을 학급 누리집과 휴대 전화 메시지 가운데 어디에 올릴지 정하고, 그 매체의 특성에 맞추어 실제로 쓸 글을 제목과 함께 쓰세요.","answer_guide":{"answer":"예: 학급 누리집에 올리겠다. 반 친구들이 모두 보고 댓글로 의견을 남길 수 있기 때문이다. 제목 — 우리 반 방울토마토, 드디어 빨갛게 익었어요! 오늘 아침 텃밭에서 방울토마토를 한 바구니 땄습니다. 〔사진〕 함께 맛볼 방법이 있다면 댓글로 알려 주세요. — 텃밭 당번 김○○","scoring_points":["매체를 정하고 까닭을 썼는가","그 매체의 특성에 맞게 썼는가","제목을 붙였는가"]},"explanation":["매체를 골라요.","특성에 맞춰요.","제목을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_a#25','kor',5,2,'u2','','g5_2_kor_u2_review_a','unit_review','K5-2-u2-C3',4,'essay','teacher','이 단원에서 배운 「올바른 문장」과 「매체에 알맞은 글」이 왜 함께 필요한지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u2-C3","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「올바른 문장」과 「매체에 알맞은 글」이 왜 함께 필요한지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 학급 누리집에 「반드시 우산을 꽂아도 됩니다」라고 올리면 매체는 알맞게 골랐어도 친구들은 꼭 꽂으라는 것인지 헷갈린다. 반대로 문장이 바르더라도 반 친구 모두의 의견을 모을 일을 한 사람에게만 메시지로 보내면 뜻이 제대로 퍼지지 않는다. 그래서 올바른 문장과 알맞은 매체가 함께 있어야 생각이 정확히 전해진다.","scoring_points":["올바른 문장이 필요한 예를 들었는가","알맞은 매체가 필요한 예를 들었는가","둘이 함께 필요한 까닭을 정리했는가"]},"explanation":["문장 예를 들어요.","매체 예를 들어요.","함께 필요한 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#1','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C7',1,'mc','auto','「고양이가 생선을 먹는다.」에서 목적어는 어느 것인가요?',ARRAY['K5-2-u2-X07','K5-2-u2-X06','K5-2-u2-X08']::text[],false,'{"seq":1,"concept":"K5-2-u2-C7","difficulty":1,"kind":"mc","stem":"「고양이가 생선을 먹는다.」에서 목적어는 어느 것인가요?","options":[{"t":"생선을","correct":true},{"t":"고양이가","mis":"K5-2-u2-X07"},{"t":"먹는다","mis":"K5-2-u2-X06"},{"t":"목적어가 없다","mis":"K5-2-u2-X08"}],"explanation":["주어예요.","서술어예요.","무엇을 먹는지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#2','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C5',1,'mc','auto','서술어가 「어찌하다」에 해당하는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X05']::text[],false,'{"seq":2,"concept":"K5-2-u2-C5","difficulty":1,"kind":"mc","stem":"서술어가 「어찌하다」에 해당하는 문장은 어느 것인가요?","options":[{"t":"강아지가 뛴다.","correct":true},{"t":"강아지가 작다.","mis":"K5-2-u2-X05"},{"t":"강아지는 진돗개이다.","mis":"K5-2-u2-X05"},{"t":"강아지가 하얗다.","mis":"K5-2-u2-X05"}],"explanation":["어떠하다예요.","무엇이다예요.","움직임이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#3','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C13',1,'blank','auto','「만두를 (     ).」에 어울리는 서술어는 어느 것인가요?',ARRAY['K5-2-u2-X12']::text[],false,'{"seq":3,"concept":"K5-2-u2-C13","difficulty":1,"kind":"blank","stem":"「만두를 (     ).」에 어울리는 서술어는 어느 것인가요?","options":[{"t":"빚는다","correct":true},{"t":"담근다","mis":"K5-2-u2-X12"},{"t":"신는다","mis":"K5-2-u2-X12"},{"t":"쓴다","mis":"K5-2-u2-X12"}],"explanation":["김치예요.","양말이에요.","만두는 빚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#4','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C16',1,'mc','auto','「별로」와 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X15']::text[],false,'{"seq":4,"concept":"K5-2-u2-C16","difficulty":1,"kind":"mc","stem":"「별로」와 어울리는 문장은 어느 것인가요?","options":[{"t":"오늘은 별로 춥지 않다.","correct":true},{"t":"오늘은 별로 춥다.","mis":"K5-2-u2-X15"},{"t":"오늘은 별로 추울 것이다.","mis":"K5-2-u2-X15"},{"t":"오늘은 별로 추웠다.","mis":"K5-2-u2-X15"}],"explanation":["부정하는 말이 없어요.","부정하는 말이 없어요.","별로 + 부정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#5','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C19',1,'blank','auto','「지난주에 할머니 댁에 (     ).」에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X18']::text[],false,'{"seq":5,"concept":"K5-2-u2-C19","difficulty":1,"kind":"blank","stem":"「지난주에 할머니 댁에 (     ).」에 알맞은 말은 어느 것인가요?","options":[{"t":"다녀왔다","correct":true},{"t":"다녀올 것이다","mis":"K5-2-u2-X18"},{"t":"다녀오겠다","mis":"K5-2-u2-X18"},{"t":"다녀오자","mis":"K5-2-u2-X18"}],"explanation":["앞으로의 일이에요.","앞으로의 일이에요.","지난 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#6','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C31',1,'mc','auto','글쓰기 대회에 작품을 첨부해 보내기에 알맞은 매체는 어느 것인가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X28']::text[],false,'{"seq":6,"concept":"K5-2-u2-C31","difficulty":1,"kind":"mc","stem":"글쓰기 대회에 작품을 첨부해 보내기에 알맞은 매체는 어느 것인가요?","options":[{"t":"전자 우편","correct":true},{"t":"휴대 전화 그림말","mis":"K5-2-u2-X29"},{"t":"학급 누리집 댓글","mis":"K5-2-u2-X28"},{"t":"교실 칠판","mis":"K5-2-u2-X28"}],"explanation":["공식적이지 않아요.","대회 응모가 아니에요.","첨부해 공식적으로 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#7','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C44',1,'ox','auto','온라인에서 이름 · 학교 · 전화번호 · 집 주소는 공개하지 않는 것이 좋아요.',ARRAY['K5-2-u2-X39']::text[],false,'{"seq":7,"concept":"K5-2-u2-C44","difficulty":1,"kind":"ox","stem":"온라인에서 이름 · 학교 · 전화번호 · 집 주소는 공개하지 않는 것이 좋아요.","answer":"O","reason_options":[{"t":"개인 정보가 나쁘게 쓰일 수 있기 때문에","correct":true},{"t":"친한 척하는 사람에게는 알려 줘도 되기 때문에","mis":"K5-2-u2-X39"}],"mis":"K5-2-u2-X39","explanation":["개인 정보를 지켜요.","친한 척해도 조심해요.","공개하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#8','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C36',1,'ox','auto','글에 쓴 사진이 남이 찍은 것이면 출처를 밝혀야 해요.',ARRAY['K5-2-u2-X33']::text[],false,'{"seq":8,"concept":"K5-2-u2-C36","difficulty":1,"kind":"ox","stem":"글에 쓴 사진이 남이 찍은 것이면 출처를 밝혀야 해요.","answer":"O","reason_options":[{"t":"남의 자료를 쓸 때에는 허락받고 출처를 밝히는 것이 지킬 점이기 때문에","correct":true},{"t":"인터넷에 있는 사진은 모두 내 것이기 때문에","mis":"K5-2-u2-X33"}],"mis":"K5-2-u2-X33","explanation":["남의 자료예요.","출처를 밝혀요.","내 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#9','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C8',2,'mc','auto','「해가 떠오른다.」에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u2-X08','K5-2-u2-X09','K5-2-u2-X06']::text[],false,'{"seq":9,"concept":"K5-2-u2-C8","difficulty":2,"kind":"mc","stem":"「해가 떠오른다.」에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"「떠오르다」는 주어만 있어도 뜻이 온전하다","correct":true},{"t":"목적어가 없어서 틀린 문장이다","mis":"K5-2-u2-X08"},{"t":"어디에 해당하는 말이 꼭 있어야 한다","mis":"K5-2-u2-X09"},{"t":"서술어가 빠져 있다","mis":"K5-2-u2-X06"}],"explanation":["목적어가 필요 없어요.","없어도 돼요.","주어만으로 완전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#10','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C20',2,'blank','auto','「교장 선생님께서 운동장을 (     ).」에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X19']::text[],false,'{"seq":10,"concept":"K5-2-u2-C20","difficulty":2,"kind":"blank","stem":"「교장 선생님께서 운동장을 (     ).」에 알맞은 말은 어느 것인가요?","options":[{"t":"둘러보셨다","correct":true},{"t":"둘러봤다","mis":"K5-2-u2-X19"},{"t":"둘러보자","mis":"K5-2-u2-X19"},{"t":"둘러볼래","mis":"K5-2-u2-X19"}],"explanation":["높이지 않았어요.","함께 하자는 말이에요.","께서에 맞게 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#11','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C17',2,'mc','auto','「왜냐하면」과 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X16','K5-2-u2-X17']::text[],false,'{"seq":11,"concept":"K5-2-u2-C17","difficulty":2,"kind":"mc","stem":"「왜냐하면」과 어울리는 문장은 어느 것인가요?","options":[{"t":"왜냐하면 오늘이 내 생일이기 때문이다.","correct":true},{"t":"왜냐하면 오늘이 내 생일이다.","mis":"K5-2-u2-X16"},{"t":"왜냐하면 오늘이 내 생일일 것이다.","mis":"K5-2-u2-X17"},{"t":"왜냐하면 오늘이 내 생일이었다.","mis":"K5-2-u2-X16"}],"explanation":["끝맺음이 안 맞아요.","짐작이 아니에요.","~기 때문이다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#12','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C21',2,'ox','auto','「내 소원은 강아지를 키우는 것이다.」는 호응이 자연스러운 문장이에요.',ARRAY['K5-2-u2-X20']::text[],false,'{"seq":12,"concept":"K5-2-u2-C21","difficulty":2,"kind":"ox","stem":"「내 소원은 강아지를 키우는 것이다.」는 호응이 자연스러운 문장이에요.","answer":"O","reason_options":[{"t":"「소원은」과 「~는 것이다」가 어울리기 때문에","correct":true},{"t":"「소원은」 뒤에는 「~하고 싶다」가 와야 하기 때문에","mis":"K5-2-u2-X20"}],"mis":"K5-2-u2-X20","explanation":["주어와 서술어가 맞아요.","~는 것이다로 맺었어요.","자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#13','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C14',2,'ox','auto','「밥과 국을 먹었다.」처럼 두 목적어에 같은 서술어가 다 어울리면 하나로 묶어 써도 돼요.',ARRAY['K5-2-u2-X13']::text[],false,'{"seq":13,"concept":"K5-2-u2-C14","difficulty":2,"kind":"ox","stem":"「밥과 국을 먹었다.」처럼 두 목적어에 같은 서술어가 다 어울리면 하나로 묶어 써도 돼요.","answer":"O","reason_options":[{"t":"두 목적어 모두 「먹다」와 어울리기 때문에","correct":true},{"t":"목적어가 둘이면 언제나 서술어를 따로 써야 하기 때문에","mis":"K5-2-u2-X13"}],"mis":"K5-2-u2-X13","explanation":["둘 다 먹어요.","어울리면 묶어도 돼요.","어울리지 않을 때만 따로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#14','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C29',2,'mc','auto','어린이 신문사에 내가 쓴 기사를 보내려면 어떤 매체가 알맞은가요?',ARRAY['K5-2-u2-X28','K5-2-u2-X29']::text[],false,'{"seq":14,"concept":"K5-2-u2-C29","difficulty":2,"kind":"mc","stem":"어린이 신문사에 내가 쓴 기사를 보내려면 어떤 매체가 알맞은가요?","options":[{"t":"전자 우편","correct":true},{"t":"학급 누리집 댓글","mis":"K5-2-u2-X28"},{"t":"휴대 전화 그림말","mis":"K5-2-u2-X29"},{"t":"교실 게시판 쪽지","mis":"K5-2-u2-X28"}],"explanation":["반 안의 공간이에요.","공식적이지 않아요.","첨부해 공식적으로 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#15','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C26',2,'mc','auto','경험 글의 「가운데」에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":15,"concept":"K5-2-u2-C26","difficulty":2,"kind":"mc","stem":"경험 글의 「가운데」에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"일어난 일과 그때 든 생각 · 느낌","correct":true},{"t":"글을 쓴 날짜만","mis":"K5-2-u2-X25"},{"t":"다짐만","mis":"K5-2-u2-X25"},{"t":"글쓴이 소개만","mis":"K5-2-u2-X25"}],"explanation":["부족해요.","끝이에요.","처음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#16','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C44',2,'mc','auto','온라인 대화 예절을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u2-X31','K5-2-u2-X39']::text[],false,'{"seq":16,"concept":"K5-2-u2-C44","difficulty":2,"kind":"mc","stem":"온라인 대화 예절을 바르게 말한 것은 어느 것인가요?","options":[{"t":"온라인에서도 얼굴을 보고 말할 때처럼 예의를 지키고 개인 정보를 지킨다","correct":true},{"t":"얼굴이 안 보이니 아무 말이나 해도 된다","mis":"K5-2-u2-X31"},{"t":"온라인은 위험하니 절대 쓰면 안 된다","mis":"K5-2-u2-X39"},{"t":"친절한 사람에게는 집 주소를 알려 줘도 된다","mis":"K5-2-u2-X39"}],"explanation":["예의를 지켜요.","안전하게 쓰는 법을 익혀요.","개인 정보를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#17','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C22',3,'mc','auto','「서윤이는 장갑과 목도리를 끼고 나섰다.」를 고친 문장 가운데 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X21']::text[],false,'{"seq":17,"concept":"K5-2-u2-C22","difficulty":3,"kind":"mc","stem":"「서윤이는 장갑과 목도리를 끼고 나섰다.」를 고친 문장 가운데 알맞지 않은 것은 어느 것인가요?","options":[{"t":"서윤이는 장갑과 목도리를 두르고 나섰다.","correct":true},{"t":"서윤이는 장갑을 끼고 목도리를 두르고 나섰다.","mis":"K5-2-u2-X21"},{"t":"서윤이는 목도리를 두르고 장갑을 끼고 나섰다.","mis":"K5-2-u2-X21"},{"t":"서윤이는 장갑을 끼고 목도리도 두른 채 나섰다.","mis":"K5-2-u2-X21"}],"explanation":["알맞아요.","차례를 바꿔도 알맞아요.","장갑은 두르지 않아요."],"asset":{"type":"passage","lines":["서윤이는 장갑과 목도리를 끼고 나섰다.","우리 고양이는 목욕을 별로 좋아한다.","내 꿈은 커서 수의사가 되고 싶다."],"title":"「서윤이의 아침」 속 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#18','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C19',3,'mc','auto','「고구마 캔 날」의 마지막 문장을 바르게 고친 것은 어느 것인가요?',ARRAY['K5-2-u2-X18']::text[],false,'{"seq":18,"concept":"K5-2-u2-C19","difficulty":3,"kind":"mc","stem":"「고구마 캔 날」의 마지막 문장을 바르게 고친 것은 어느 것인가요?","options":[{"t":"다음 주에는 고구마로 간식을 만들 것이다.","correct":true},{"t":"다음 주에는 고구마로 간식을 만들었었다.","mis":"K5-2-u2-X18"},{"t":"지난주에는 고구마로 간식을 만들 것이다.","mis":"K5-2-u2-X18"},{"t":"다음 주에는 고구마로 간식을 만들어 버렸다.","mis":"K5-2-u2-X18"}],"explanation":["여전히 지난 일이에요.","이번엔 지난주와 어긋나요.","앞으로의 일로 맺었어요."],"asset":{"type":"passage","lines":["지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","선생님이 호미 쓰는 법을 알려 주었다.","나는 호미와 장갑을 끼고 흙을 팠다.","고구마가 생각보다 커서 여간 놀랐다.","다음 주에는 고구마로 간식을 만들었다."],"title":"경험을 쓴 글 「고구마 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#19','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C31',3,'mc','auto','전자 우편으로 기관에 무엇을 물을 때 메시지처럼 쓰면 안 되는 까닭은 무엇인가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X30','K5-2-u2-X28']::text[],false,'{"seq":19,"concept":"K5-2-u2-C31","difficulty":3,"kind":"mc","stem":"전자 우편으로 기관에 무엇을 물을 때 메시지처럼 쓰면 안 되는 까닭은 무엇인가요?","options":[{"t":"공식적인 글이라 제목 · 인사를 갖추고 예의 바른 말로 써야 하기 때문에","correct":true},{"t":"전자 우편은 그림말만 쓸 수 있기 때문에","mis":"K5-2-u2-X29"},{"t":"전자 우편은 아무도 읽지 않기 때문에","mis":"K5-2-u2-X30"},{"t":"전자 우편은 반 친구 모두가 보기 때문에","mis":"K5-2-u2-X28"}],"explanation":["그림말만 쓰지 않아요.","받는 사람이 읽어요.","그건 누리집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#20','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C35',3,'mc','auto','학급 누리집 글의 제목을 고르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X32']::text[],false,'{"seq":20,"concept":"K5-2-u2-C35","difficulty":3,"kind":"mc","stem":"학급 누리집 글의 제목을 고르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 싶어지면서 글의 핵심을 담고, 내용과 어긋나지 않는다","correct":true},{"t":"느낌표를 많이 달아 깜짝 놀라게 한다","mis":"K5-2-u2-X32"},{"t":"되도록 짧게 한 글자로 쓴다","mis":"K5-2-u2-X32"},{"t":"내용과 달라도 눈길만 끌면 된다","mis":"K5-2-u2-X32"}],"explanation":["자극적이기만 해요.","핵심이 없어요.","흥미와 핵심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#21','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C41',3,'mc','auto','다음 칭찬 댓글 가운데 가장 구체적인 것은 어느 것인가요?',ARRAY['K5-2-u2-X35']::text[],false,'{"seq":21,"concept":"K5-2-u2-C41","difficulty":3,"kind":"mc","stem":"다음 칭찬 댓글 가운데 가장 구체적인 것은 어느 것인가요?","options":[{"t":"「‘우산 이름표’ 제안 덕분에 내 우산을 쉽게 찾을 방법을 생각해 보았습니다.」","correct":true},{"t":"「이 글 좋아요.」","mis":"K5-2-u2-X35"},{"t":"「최고 최고!」","mis":"K5-2-u2-X35"},{"t":"「잘 썼다.」","mis":"K5-2-u2-X35"}],"explanation":["근거가 없어요.","근거가 없어요.","어디가 왜 좋은지 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#22','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C23',3,'mc','auto','반 친구들이 읽을 경험 글을 쓰기 전 세운 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X22']::text[],false,'{"seq":22,"concept":"K5-2-u2-C23","difficulty":3,"kind":"mc","stem":"반 친구들이 읽을 경험 글을 쓰기 전 세운 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"목적 — 경험과 느낀 점 나누기 / 읽을 사람 — 반 친구들 / 글감 — 느낌이 생생한 한 가지 일","correct":true},{"t":"목적 — 없음 / 읽을 사람 — 아무나 / 글감 — 일 열 가지","mis":"K5-2-u2-X22"},{"t":"목적 — 칭찬받기 / 읽을 사람 — 나 / 글감 — 남이 겪은 일","mis":"K5-2-u2-X22"},{"t":"목적 — 맞춤법 연습 / 읽을 사람 — 선생님만 / 글감 — 아무 일","mis":"K5-2-u2-X22"}],"explanation":["정하지 않았어요.","내 경험이 아니에요.","목적 · 독자 · 글감이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#23','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C16',4,'essay','teacher','「전혀 · 별로 · 도저히 · 여간」 가운데 두 낱말을 골라 호응이 알맞은 문장을 하나씩 쓰고, 이 낱말들과 어울리는 말의 공통점을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u2-C16","difficulty":4,"kind":"essay","stem":"「전혀 · 별로 · 도저히 · 여간」 가운데 두 낱말을 골라 호응이 알맞은 문장을 하나씩 쓰고, 이 낱말들과 어울리는 말의 공통점을 쓰세요.","answer_guide":{"answer":"예: 「나는 그 영화가 전혀 무섭지 않았다.」 「밤새 내린 눈 때문에 문을 도저히 열 수 없었다.」 이 낱말들은 모두 뒤에 「~지 않다 · ~지 못하다 · ~이 아니다 · ~할 수 없다」처럼 부정하는 말이 와야 어울린다.","scoring_points":["두 낱말로 문장을 썼는가","문장의 호응이 알맞은가","부정하는 말과 어울린다는 공통점을 썼는가"]},"explanation":["낱말을 골라요.","부정하는 말로 맺어요.","공통점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#24','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C31',4,'essay','teacher','할머니께 휴대 전화 메시지로 안부를 전할 때와 어린이 신문사에 전자 우편으로 기사를 보낼 때 글이 어떻게 달라지는지 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u2-C31","difficulty":4,"kind":"essay","stem":"할머니께 휴대 전화 메시지로 안부를 전할 때와 어린이 신문사에 전자 우편으로 기사를 보낼 때 글이 어떻게 달라지는지 두 가지 쓰세요.","answer_guide":{"answer":"예: 첫째, 메시지는 짧고 친근하게 「할머니, 잘 지내세요? 보고 싶어요 😊」처럼 쓰지만, 전자 우편은 제목 · 첫인사 · 끝인사를 갖추어 공식적으로 쓴다. 둘째, 메시지는 바로 주고받는 대화 같지만, 전자 우편은 받는 사람 주소를 정확히 쓰고 기사를 첨부 자료로 붙여 보낸다.","scoring_points":["두 가지 차이를 썼는가","메시지의 특성을 썼는가","전자 우편의 특성을 썼는가"]},"explanation":["차이를 찾아요.","메시지를 떠올려요.","전자 우편을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_b#25','kor',5,2,'u2','','g5_2_kor_u2_review_b','unit_review','K5-2-u2-C12',4,'essay','teacher','글을 쓴 뒤 문장의 호응을 스스로 확인할 물음 세 가지를 만들어 쓰고, 그 물음이 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u2-C12","difficulty":4,"kind":"essay","stem":"글을 쓴 뒤 문장의 호응을 스스로 확인할 물음 세 가지를 만들어 쓰고, 그 물음이 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 「주어와 서술어가 서로 어울리나?」 둘째, 「‘별로 · 전혀 · 반드시 · 왜냐하면’ 뒤에 짝이 되는 말이 왔나?」 셋째, 「때를 나타내는 말과 높일 분에 맞게 서술어를 썼나?」 쓰는 동안에는 뜻에만 집중해 호응이 어긋나기 쉬우므로, 다 쓴 뒤 물음으로 하나씩 짝을 맞춰 보아야 한다.","scoring_points":["물음 세 가지를 만들었는가","물음이 호응의 갈래와 이어지는가","필요한 까닭을 썼는가"]},"explanation":["물음을 만들어요.","호응과 이어요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#1','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C6',1,'mc','auto','「고양이가 생선을 먹는다.」에서 서술어는 어느 것인가요?',ARRAY['K5-2-u2-X06','K5-2-u2-X07']::text[],false,'{"seq":1,"concept":"K5-2-u2-C6","difficulty":1,"kind":"mc","stem":"「고양이가 생선을 먹는다.」에서 서술어는 어느 것인가요?","options":[{"t":"먹는다","correct":true},{"t":"고양이가","mis":"K5-2-u2-X06"},{"t":"생선을","mis":"K5-2-u2-X07"},{"t":"서술어가 없다","mis":"K5-2-u2-X06"}],"explanation":["주어예요.","목적어예요.","어찌하는지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#2','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C5',1,'blank','auto','「우리 아빠는 (     ).」에 「무엇이다」에 해당하는 서술어를 넣으면 어느 것인가요?',ARRAY['K5-2-u2-X05','K5-2-u2-X07']::text[],false,'{"seq":2,"concept":"K5-2-u2-C5","difficulty":1,"kind":"blank","stem":"「우리 아빠는 (     ).」에 「무엇이다」에 해당하는 서술어를 넣으면 어느 것인가요?","options":[{"t":"요리사이다","correct":true},{"t":"요리한다","mis":"K5-2-u2-X05"},{"t":"친절하다","mis":"K5-2-u2-X05"},{"t":"요리를","mis":"K5-2-u2-X07"}],"explanation":["어찌하다예요.","어떠하다예요.","아빠가 무엇인지 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#3','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C13',1,'mc','auto','목적어와 서술어가 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u2-X12']::text[],false,'{"seq":3,"concept":"K5-2-u2-C13","difficulty":1,"kind":"mc","stem":"목적어와 서술어가 어울리는 문장은 어느 것인가요?","options":[{"t":"목도리를 두른다.","correct":true},{"t":"목도리를 신는다.","mis":"K5-2-u2-X12"},{"t":"목도리를 쓴다.","mis":"K5-2-u2-X12"},{"t":"목도리를 빚는다.","mis":"K5-2-u2-X12"}],"explanation":["어울리지 않아요.","어울리지 않아요.","목도리는 둘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#4','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C16',1,'ox','auto','「도저히 참을 수 있었다.」는 호응이 자연스러운 문장이에요.',ARRAY['K5-2-u2-X15']::text[],false,'{"seq":4,"concept":"K5-2-u2-C16","difficulty":1,"kind":"ox","stem":"「도저히 참을 수 있었다.」는 호응이 자연스러운 문장이에요.","answer":"X","reason_options":[{"t":"「도저히」 뒤에는 「~할 수 없다」처럼 부정하는 말이 와야 하기 때문에","correct":true},{"t":"「도저히」는 아무 말과 함께 써도 되기 때문에","mis":"K5-2-u2-X15"}],"mis":"K5-2-u2-X15","explanation":["부정하는 말이 필요해요.","도저히 참을 수 없었다예요.","짝이 정해져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#5','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C19',1,'ox','auto','「어제 친구와 축구를 할 것이다.」는 시간 표현이 어울리는 문장이에요.',ARRAY['K5-2-u2-X18']::text[],false,'{"seq":5,"concept":"K5-2-u2-C19","difficulty":1,"kind":"ox","stem":"「어제 친구와 축구를 할 것이다.」는 시간 표현이 어울리는 문장이에요.","answer":"X","reason_options":[{"t":"「어제」는 지난 일이라 「~했다」와 어울리기 때문에","correct":true},{"t":"「어제」 뒤에는 앞으로의 일을 쓰기 때문에","mis":"K5-2-u2-X18"}],"mis":"K5-2-u2-X18","explanation":["어제는 지난 일이에요.","「했다」로 맺어요.","때와 서술어를 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#6','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C30',1,'match','auto','매체와 그 특성을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u2-C30","difficulty":1,"kind":"match","stem":"매체와 그 특성을 이으세요.","pairs":[{"l":"휴대 전화 메시지","r":"짧고 빠르게, 그림말로 기분 표현"},{"l":"전자 우편","r":"제목 · 인사 · 첨부 자료"},{"l":"학급 누리집","r":"반 모두가 보고 댓글로 의견"}],"mis":"K5-2-u2-X29","explanation":["빠르게예요.","갖춰서 보내요.","함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#7','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C44',1,'mc','auto','이상한 메시지를 받았을 때 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u2-X39']::text[],false,'{"seq":7,"concept":"K5-2-u2-C44","difficulty":1,"kind":"mc","stem":"이상한 메시지를 받았을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"부모님이나 선생님께 알린다","correct":true},{"t":"혼자 몰래 답장한다","mis":"K5-2-u2-X39"},{"t":"친구들에게 내 주소와 함께 퍼뜨린다","mis":"K5-2-u2-X39"},{"t":"선물을 준다고 하면 사진을 보낸다","mis":"K5-2-u2-X39"}],"explanation":["혼자 하지 않아요.","개인 정보를 지켜요.","어른께 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#8','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C41',1,'blank','auto','칭찬 댓글은 막연한 「좋아요」보다 글의 내용이나 표현을 (     )(으)로 들어 어떤 점이 왜 좋은지 써요.',ARRAY['K5-2-u2-X36','K5-2-u2-X35']::text[],false,'{"seq":8,"concept":"K5-2-u2-C41","difficulty":1,"kind":"blank","stem":"칭찬 댓글은 막연한 「좋아요」보다 글의 내용이나 표현을 (     )(으)로 들어 어떤 점이 왜 좋은지 써요.","options":[{"t":"근거","correct":true},{"t":"맞춤법","mis":"K5-2-u2-X36"},{"t":"그림말","mis":"K5-2-u2-X35"},{"t":"글자 수","mis":"K5-2-u2-X35"}],"explanation":["오늘은 지적하지 않아요.","그림말이 칭찬은 아니에요.","근거를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#9','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C8',2,'mc','auto','「누나가 책을 두었다.」에 한 말을 더해 뜻을 분명히 한 것은 어느 것인가요?',ARRAY['K5-2-u2-X09','K5-2-u2-X04']::text[],false,'{"seq":9,"concept":"K5-2-u2-C8","difficulty":2,"kind":"mc","stem":"「누나가 책을 두었다.」에 한 말을 더해 뜻을 분명히 한 것은 어느 것인가요?","options":[{"t":"누나가 책을 책상 위에 두었다.","correct":true},{"t":"누나가 책을 빨리 두었다.","mis":"K5-2-u2-X09"},{"t":"누나가 두었다.","mis":"K5-2-u2-X09"},{"t":"책을 책상 위에 두었다.","mis":"K5-2-u2-X04"}],"explanation":["어디에가 없어요.","더 빠졌어요.","두다는 어디에가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#10','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C20',2,'ox','auto','「선생님께서 칭찬을 해 줬다.」는 높임 표현이 알맞은 문장이에요.',ARRAY['K5-2-u2-X19']::text[],false,'{"seq":10,"concept":"K5-2-u2-C20","difficulty":2,"kind":"ox","stem":"「선생님께서 칭찬을 해 줬다.」는 높임 표현이 알맞은 문장이에요.","answer":"X","reason_options":[{"t":"「께서」에 어울리게 서술어도 「해 주셨다」로 높여야 하기 때문에","correct":true},{"t":"「께서」만 넣으면 높임 표현이 다 된 것이기 때문에","mis":"K5-2-u2-X19"}],"mis":"K5-2-u2-X19","explanation":["서술어가 그대로예요.","해 주셨다로 높여요.","둘 다 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#11','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C15',2,'mc','auto','「반드시」를 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K5-2-u2-X14']::text[],false,'{"seq":11,"concept":"K5-2-u2-C15","difficulty":2,"kind":"mc","stem":"「반드시」를 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"도서관 책은 반드시 제자리에 꽂아야 한다.","correct":true},{"t":"도서관 책은 반드시 제자리에 꽂아도 된다.","mis":"K5-2-u2-X14"},{"t":"도서관 책은 반드시 제자리에 꽂지 않아도 된다.","mis":"K5-2-u2-X14"},{"t":"도서관 책은 반드시 제자리에 꽂았을까?","mis":"K5-2-u2-X14"}],"explanation":["어울리지 않아요.","어울리지 않아요.","반드시 ~해야 한다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#12','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C21',2,'blank','auto','「내 목표는 이번 달에 책을 열 권 (     ).」에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X20','K5-2-u2-X18']::text[],false,'{"seq":12,"concept":"K5-2-u2-C21","difficulty":2,"kind":"blank","stem":"「내 목표는 이번 달에 책을 열 권 (     ).」에 알맞은 말은 어느 것인가요?","options":[{"t":"읽는 것이다","correct":true},{"t":"읽고 싶다","mis":"K5-2-u2-X20"},{"t":"읽었다","mis":"K5-2-u2-X18"},{"t":"읽어라","mis":"K5-2-u2-X20"}],"explanation":["목표는과 어울리지 않아요.","지난 일이에요.","목표는 ~는 것이다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#13','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C14',2,'mc','auto','목적어가 둘인데 서술어 하나로 묶어서 어색한 문장은 어느 것인가요?',ARRAY['K5-2-u2-X13']::text[],false,'{"seq":13,"concept":"K5-2-u2-C14","difficulty":2,"kind":"mc","stem":"목적어가 둘인데 서술어 하나로 묶어서 어색한 문장은 어느 것인가요?","options":[{"t":"동생은 바지와 운동화를 입었다.","correct":true},{"t":"동생은 바지와 셔츠를 입었다.","mis":"K5-2-u2-X13"},{"t":"동생은 우유와 주스를 마셨다.","mis":"K5-2-u2-X13"},{"t":"동생은 연필과 지우개를 샀다.","mis":"K5-2-u2-X13"}],"explanation":["둘 다 입어요.","둘 다 마셔요.","운동화는 신어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#14','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C29',2,'mc','auto','친구와 오늘 저녁 약속 장소를 급히 바꾸려면 어떤 매체가 알맞은가요?',ARRAY['K5-2-u2-X29','K5-2-u2-X28']::text[],false,'{"seq":14,"concept":"K5-2-u2-C29","difficulty":2,"kind":"mc","stem":"친구와 오늘 저녁 약속 장소를 급히 바꾸려면 어떤 매체가 알맞은가요?","options":[{"t":"휴대 전화 메시지","correct":true},{"t":"첨부 자료를 붙인 전자 우편","mis":"K5-2-u2-X29"},{"t":"학급 누리집 공지","mis":"K5-2-u2-X28"},{"t":"어린이 잡지 독자 마당","mis":"K5-2-u2-X28"}],"explanation":["급할 땐 느려요.","반 모두에게 알릴 일이 아니에요.","빠르게 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#15','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C26',2,'ox','auto','경험 글에서 가장 인상 깊은 장면은 처음 부분에 길게 써야 해요.',ARRAY['K5-2-u2-X25']::text[],false,'{"seq":15,"concept":"K5-2-u2-C26","difficulty":2,"kind":"ox","stem":"경험 글에서 가장 인상 깊은 장면은 처음 부분에 길게 써야 해요.","answer":"X","reason_options":[{"t":"가장 인상 깊은 장면은 가운데에 자세히 담기 때문에","correct":true},{"t":"처음이 가장 길어야 읽는 사람이 끝까지 읽기 때문에","mis":"K5-2-u2-X25"}],"mis":"K5-2-u2-X25","explanation":["처음은 소개예요.","가운데에 담아요.","처음이 길면 지루해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#16','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C44',2,'error','auto','모르는 계정의 메시지에 답한 말이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X39','K5-2-u2-X31']::text[],false,'{"seq":16,"concept":"K5-2-u2-C44","difficulty":2,"kind":"error","stem":"모르는 계정의 메시지에 답한 말이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「선물 준다면 내 사진 보내 줄게.」","correct":true,"mis_target":"K5-2-u2-X39"},{"t":"「부모님께 먼저 여쭤봐야 해.」","mis":"K5-2-u2-X31"},{"t":"「개인 정보는 보내지 않기로 했어.」","mis":"K5-2-u2-X31"}],"explanation":["알맞은 거절이에요.","알맞은 거절이에요.","사진을 보내면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#17','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C22',3,'ox','auto','호응이 어색한 문장을 고칠 때, 까닭이 맞으면 고친 문장은 여러 가지일 수 있어요.',ARRAY['K5-2-u2-X21']::text[],false,'{"seq":17,"concept":"K5-2-u2-C22","difficulty":3,"kind":"ox","stem":"호응이 어색한 문장을 고칠 때, 까닭이 맞으면 고친 문장은 여러 가지일 수 있어요.","answer":"O","reason_options":[{"t":"어울리는 말끼리 쓰기만 하면 표현은 여러 가지가 될 수 있기 때문에","correct":true},{"t":"어색한 문장마다 정답인 고친 문장이 하나씩 정해져 있기 때문에","mis":"K5-2-u2-X21"}],"mis":"K5-2-u2-X21","explanation":["여러 가지예요.","까닭이 맞으면 돼요.","하나로 정해져 있지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#18','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C14',3,'mc','auto','「나는 호미와 장갑을 끼고 흙을 팠다.」가 어색한 까닭과 고친 문장을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u2-X06','K5-2-u2-X18','K5-2-u2-X19']::text[],false,'{"seq":18,"concept":"K5-2-u2-C14","difficulty":3,"kind":"mc","stem":"「나는 호미와 장갑을 끼고 흙을 팠다.」가 어색한 까닭과 고친 문장을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"호미는 「끼다」와 어울리지 않아서 — 나는 호미를 들고 장갑을 끼고 흙을 팠다.","correct":true},{"t":"주어가 없어서 — 호미와 장갑을 끼고 흙을 팠다.","mis":"K5-2-u2-X06"},{"t":"시간 표현이 어색해서 — 나는 호미와 장갑을 끼고 흙을 팔 것이다.","mis":"K5-2-u2-X18"},{"t":"높임 표현이 빠져서 — 나는 호미와 장갑을 끼시고 흙을 팠다.","mis":"K5-2-u2-X19"}],"explanation":["「나는」이 있어요.","시간은 맞아요.","나를 높이지 않아요."],"asset":{"type":"passage","lines":["지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","선생님이 호미 쓰는 법을 알려 주었다.","나는 호미와 장갑을 끼고 흙을 팠다.","고구마가 생각보다 커서 여간 놀랐다.","다음 주에는 고구마로 간식을 만들었다."],"title":"경험을 쓴 글 「고구마 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#19','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C32',3,'ox','auto','학급 누리집은 오래 기록으로 남으니 올린 글이 나중에도 여러 사람에게 읽힐 수 있어요.',ARRAY['K5-2-u2-X31']::text[],false,'{"seq":19,"concept":"K5-2-u2-C32","difficulty":3,"kind":"ox","stem":"학급 누리집은 오래 기록으로 남으니 올린 글이 나중에도 여러 사람에게 읽힐 수 있어요.","answer":"O","reason_options":[{"t":"기록이 남아 시간이 지나도 다시 볼 수 있기 때문에","correct":true},{"t":"누리집 글은 하루가 지나면 저절로 사라지기 때문에","mis":"K5-2-u2-X31"}],"mis":"K5-2-u2-X31","explanation":["기록이 남아요.","그래서 신중히 써요.","사라지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#20','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C37',3,'error','auto','「책 바꿔 읽기 상자」 초안을 고치려는 계획이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X34','K5-2-u2-X40']::text[],false,'{"seq":20,"concept":"K5-2-u2-C37","difficulty":3,"kind":"error","stem":"「책 바꿔 읽기 상자」 초안을 고치려는 계획이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「‘끝.’으로 맺으면 깔끔하니 그대로 둘래.」","correct":true,"mis_target":"K5-2-u2-X34"},{"t":"「제목을 핵심이 드러나게 바꿀래.」","mis":"K5-2-u2-X40"},{"t":"「그림 출처를 밝힐래.」","mis":"K5-2-u2-X40"}],"explanation":["알맞아요.","알맞아요.","댓글 참여를 안내해요."],"asset":{"type":"passage","lines":["〔제목〕 충격!!! 우리 반 큰일 났다","요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미있다.","그래서 집에 있는 책을 바꿔 읽는 상자를 만들면 좋겠다.","인터넷에서 본 그림을 그대로 붙였다. 〔그림〕","끝."],"title":"학급 누리집에 올릴 글 초안 「책 바꿔 읽기 상자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#21','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C41',3,'ox','auto','「이 글 덕분에 ○○을/를 생각해 보았습니다.」 같은 틀 문장은 ○○에 친구 글 내용을 넣어 내 말로 채워 써야 해요.',ARRAY['K5-2-u2-X35']::text[],false,'{"seq":21,"concept":"K5-2-u2-C41","difficulty":3,"kind":"ox","stem":"「이 글 덕분에 ○○을/를 생각해 보았습니다.」 같은 틀 문장은 ○○에 친구 글 내용을 넣어 내 말로 채워 써야 해요.","answer":"O","reason_options":[{"t":"근거가 담겨야 구체적인 칭찬이 되기 때문에","correct":true},{"t":"틀 문장은 그대로 붙여 넣어야 예의 바르기 때문에","mis":"K5-2-u2-X35"}],"mis":"K5-2-u2-X35","explanation":["빈칸을 채워요.","내 말로 써요.","그래야 구체적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#22','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C25',3,'mc','auto','차례대로 정리한 메모 가운데 가장 잘된 것은 어느 것인가요?',ARRAY['K5-2-u2-X24']::text[],false,'{"seq":22,"concept":"K5-2-u2-C25","difficulty":3,"kind":"mc","stem":"차례대로 정리한 메모 가운데 가장 잘된 것은 어느 것인가요?","options":[{"t":"처음 — 연을 만들었다(설렘) → 그다음 — 줄이 끊어졌다(눈물이 핑) → 마지막 — 다시 띄웠다(뿌듯함)","correct":true},{"t":"연을 만들었다 → 줄이 끊어졌다 → 다시 띄웠다","mis":"K5-2-u2-X24"},{"t":"다시 띄웠다 → 연을 만들었다 → 줄이 끊어졌다","mis":"K5-2-u2-X24"},{"t":"뿌듯함 → 슬픔 → 설렘","mis":"K5-2-u2-X24"}],"explanation":["느낌이 빠졌어요.","차례가 섞였어요.","차례와 느낌이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#23','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C20',4,'essay','teacher','선생님이나 웃어른이 주어인 문장을 두 개 쓰고, 높임 표현을 어떻게 맞추었는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u2-C20","difficulty":4,"kind":"essay","stem":"선생님이나 웃어른이 주어인 문장을 두 개 쓰고, 높임 표현을 어떻게 맞추었는지 쓰세요.","answer_guide":{"answer":"예: 「할머니께서 마당에 꽃을 심으셨다.」 「담임 선생님께서 우리에게 이야기책을 읽어 주셨다.」 높일 분이 주어이므로 「이 · 가」 대신 「께서」를 쓰고, 서술어에도 「-시-」를 넣어 「심으셨다 · 주셨다」로 높였다.","scoring_points":["웃어른이 주어인 문장 두 개를 썼는가","「께서」를 썼는가","서술어에 「-시-」를 넣어 높였는가"]},"explanation":["웃어른을 주어로 해요.","께서를 써요.","서술어도 높여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#24','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C37',4,'essay','teacher','「책 바꿔 읽기 상자」 초안을 학급 누리집 글로 고쳐 쓰세요. 제목 · 처음 · 가운데 · 끝을 갖추고, 고친 까닭을 한 문장 덧붙이세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u2-C37","difficulty":4,"kind":"essay","stem":"「책 바꿔 읽기 상자」 초안을 학급 누리집 글로 고쳐 쓰세요. 제목 · 처음 · 가운데 · 끝을 갖추고, 고친 까닭을 한 문장 덧붙이세요.","answer_guide":{"answer":"예: 제목 — 우리 반 책 바꿔 읽기 상자, 함께 만들어 볼까요? 처음 — 요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미없지 않나요? 가운데 — 집에서 다 읽은 책을 한 권씩 가져와 상자에 넣고 바꿔 읽으면 좋겠습니다. 〔그림 — 출처: ○○ 누리집〕 끝 — 상자 이름이나 규칙을 댓글로 알려 주세요. 고친 까닭 — 제목과 호응을 바로잡고 출처와 참여 안내를 넣어 누리집에 알맞게 했다.","scoring_points":["제목 · 처음 · 가운데 · 끝을 갖추었는가","호응 · 출처 · 참여 안내를 바로잡았는가","고친 까닭을 썼는가"]},"explanation":["짜임을 갖춰요.","문제를 바로잡아요.","까닭을 덧붙여요."],"asset":{"type":"passage","lines":["〔제목〕 충격!!! 우리 반 큰일 났다","요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미있다.","그래서 집에 있는 책을 바꿔 읽는 상자를 만들면 좋겠다.","인터넷에서 본 그림을 그대로 붙였다. 〔그림〕","끝."],"title":"학급 누리집에 올릴 글 초안 「책 바꿔 읽기 상자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_c#25','kor',5,2,'u2','','g5_2_kor_u2_review_c','unit_review','K5-2-u2-C41',4,'essay','teacher','학급 누리집에서 친구 글에 칭찬 댓글을 쓸 때 지킬 점 세 가지를 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u2-C41","difficulty":4,"kind":"essay","stem":"학급 누리집에서 친구 글에 칭찬 댓글을 쓸 때 지킬 점 세 가지를 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 어디가 왜 좋은지 근거를 들어 구체적으로 쓴다. 둘째, 틀린 곳을 지적하지 않고 장점을 중심으로 쓴다. 셋째, 올리기 전에 한 번 더 읽고 이름을 밝힌다. 여러 사람이 함께 보는 공간이라 예절을 지켜야 하고, 구체적인 칭찬이어야 글쓴이가 잘된 점을 다음 글에서도 살릴 수 있기 때문이다.","scoring_points":["지킬 점 세 가지를 썼는가","근거 · 장점 · 확인 가운데 둘 이상을 담았는가","까닭을 썼는가"]},"explanation":["지킬 점을 써요.","배운 것을 담아요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#1','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C10',1,'ox','auto','「우리 반은 줄넘기를 한다.」에서 주어는 「우리 반은」이에요.',ARRAY['K5-2-u2-X04']::text[],false,'{"seq":1,"concept":"K5-2-u2-C10","difficulty":1,"kind":"ox","stem":"「우리 반은 줄넘기를 한다.」에서 주어는 「우리 반은」이에요.","answer":"O","reason_options":[{"t":"누가 줄넘기를 하는지 알려 주는 말이기 때문에","correct":true},{"t":"「이 · 가」가 붙지 않은 말은 주어가 될 수 없기 때문에","mis":"K5-2-u2-X04"}],"mis":"K5-2-u2-X04","explanation":["누가를 물어요.","「은」이 붙어도 주어예요.","「우리 반은」이 주어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#2','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C5',1,'ox','auto','「하늘이 파랗다.」의 「파랗다」도 서술어예요.',ARRAY['K5-2-u2-X05']::text[],false,'{"seq":2,"concept":"K5-2-u2-C5","difficulty":1,"kind":"ox","stem":"「하늘이 파랗다.」의 「파랗다」도 서술어예요.","answer":"O","reason_options":[{"t":"하늘이 어떠한지 알려 주는 말이기 때문에","correct":true},{"t":"움직임을 나타내는 말만 서술어이기 때문에","mis":"K5-2-u2-X05"}],"mis":"K5-2-u2-X05","explanation":["어떠하다도 서술어예요.","세 갈래가 있어요.","움직임만이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#3','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C13',1,'ox','auto','「양말을 쓴다.」는 목적어와 서술어가 잘 어울리는 문장이에요.',ARRAY['K5-2-u2-X12']::text[],false,'{"seq":3,"concept":"K5-2-u2-C13","difficulty":1,"kind":"ox","stem":"「양말을 쓴다.」는 목적어와 서술어가 잘 어울리는 문장이에요.","answer":"X","reason_options":[{"t":"양말은 「신다」와 어울리기 때문에","correct":true},{"t":"몸에 걸치는 것은 모두 「쓰다」를 쓰기 때문에","mis":"K5-2-u2-X12"}],"mis":"K5-2-u2-X12","explanation":["양말은 신어요.","목적어마다 달라요.","쓰다는 모자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#4','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C16',1,'mc','auto','「여간」을 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K5-2-u2-X15','K5-2-u2-X14']::text[],false,'{"seq":4,"concept":"K5-2-u2-C16","difficulty":1,"kind":"mc","stem":"「여간」을 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"운동장 청소는 여간 힘든 일이 아니었다.","correct":true},{"t":"운동장 청소는 여간 힘든 일이었다.","mis":"K5-2-u2-X15"},{"t":"운동장 청소는 여간 힘들 것이다.","mis":"K5-2-u2-X15"},{"t":"운동장 청소는 여간 힘들어야 한다.","mis":"K5-2-u2-X14"}],"explanation":["부정하는 말이 없어요.","부정하는 말이 없어요.","여간 + 아니다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#5','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C19',1,'mc','auto','시간 표현이 어색한 문장은 어느 것인가요?',ARRAY['K5-2-u2-X18']::text[],false,'{"seq":5,"concept":"K5-2-u2-C19","difficulty":1,"kind":"mc","stem":"시간 표현이 어색한 문장은 어느 것인가요?","options":[{"t":"다음 주에 소풍을 갔다.","correct":true},{"t":"다음 주에 소풍을 갈 것이다.","mis":"K5-2-u2-X18"},{"t":"지난주에 소풍을 갔다.","mis":"K5-2-u2-X18"},{"t":"지금 소풍을 가고 있다.","mis":"K5-2-u2-X18"}],"explanation":["어울려요.","어울려요.","다음 주는 앞으로의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#6','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C31',1,'ox','auto','전자 우편은 받는 사람 주소가 한 글자만 틀려도 제대로 보내지지 않을 수 있어요.',ARRAY['K5-2-u2-X30']::text[],false,'{"seq":6,"concept":"K5-2-u2-C31","difficulty":1,"kind":"ox","stem":"전자 우편은 받는 사람 주소가 한 글자만 틀려도 제대로 보내지지 않을 수 있어요.","answer":"O","reason_options":[{"t":"주소를 정확히 써야 전송되기 때문에","correct":true},{"t":"전자 우편은 주소가 틀려도 알아서 찾아가기 때문에","mis":"K5-2-u2-X30"}],"mis":"K5-2-u2-X30","explanation":["주소가 중요해요.","한 글자도 확인해요.","알아서 찾아가지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#7','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C44',1,'mc','auto','다음 가운데 온라인에서 이야기해도 괜찮은 것에 가장 가까운 것은 어느 것인가요?',ARRAY['K5-2-u2-X39']::text[],false,'{"seq":7,"concept":"K5-2-u2-C44","difficulty":1,"kind":"mc","stem":"다음 가운데 온라인에서 이야기해도 괜찮은 것에 가장 가까운 것은 어느 것인가요?","options":[{"t":"좋아하는 책 제목","correct":true},{"t":"우리 집 주소","mis":"K5-2-u2-X39"},{"t":"내 전화번호","mis":"K5-2-u2-X39"},{"t":"다니는 학교와 반","mis":"K5-2-u2-X39"}],"explanation":["개인 정보예요.","개인 정보예요.","개인 정보가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#8','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C36',1,'mc','auto','가져온 자료를 쓸 때 꼭 함께 적을 것은 어느 것인가요?',ARRAY['K5-2-u2-X39','K5-2-u2-X29','K5-2-u2-X32']::text[],false,'{"seq":8,"concept":"K5-2-u2-C36","difficulty":1,"kind":"mc","stem":"가져온 자료를 쓸 때 꼭 함께 적을 것은 어느 것인가요?","options":[{"t":"출처","correct":true},{"t":"내 전화번호","mis":"K5-2-u2-X39"},{"t":"그림말","mis":"K5-2-u2-X29"},{"t":"느낌표","mis":"K5-2-u2-X32"}],"explanation":["개인 정보예요.","관계없어요.","어디서 가져왔는지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#9','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C8',2,'ox','auto','「민준이가 보냈다.」는 서술어 「보내다」에 꼭 필요한 말이 다 있는 문장이에요.',ARRAY['K5-2-u2-X09']::text[],false,'{"seq":9,"concept":"K5-2-u2-C8","difficulty":2,"kind":"ox","stem":"「민준이가 보냈다.」는 서술어 「보내다」에 꼭 필요한 말이 다 있는 문장이에요.","answer":"X","reason_options":[{"t":"무엇을 누구에게 보냈는지가 있어야 뜻이 분명하기 때문에","correct":true},{"t":"주어와 서술어만 있으면 어떤 문장이든 완전하기 때문에","mis":"K5-2-u2-X09"}],"mis":"K5-2-u2-X09","explanation":["무엇을이 빠졌어요.","누구에게가 빠졌어요.","서술어가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#10','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C20',2,'error','auto','「고구마 캔 날」을 고치려는 말 가운데 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X19','K5-2-u2-X21']::text[],false,'{"seq":10,"concept":"K5-2-u2-C20","difficulty":2,"kind":"error","stem":"「고구마 캔 날」을 고치려는 말 가운데 알맞지 않은 것은 어느 것인가요?","options":[{"t":"둘째 문장은 고칠 곳이 없다","correct":true,"mis_target":"K5-2-u2-X19"},{"t":"둘째 문장은 「선생님께서 … 알려 주셨다」로 고친다","mis":"K5-2-u2-X21"},{"t":"넷째 문장은 「여간 놀라운 일이 아니었다」로 고친다","mis":"K5-2-u2-X21"}],"explanation":["높임을 맞췄어요.","부정하는 말을 넣었어요.","선생님이 주어이니 높여요."],"asset":{"type":"passage","lines":["지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","선생님이 호미 쓰는 법을 알려 주었다.","나는 호미와 장갑을 끼고 흙을 팠다.","고구마가 생각보다 커서 여간 놀랐다.","다음 주에는 고구마로 간식을 만들었다."],"title":"경험을 쓴 글 「고구마 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#11','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C18',2,'match','auto','앞말과 어울리는 끝말을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-2-u2-C18","difficulty":2,"kind":"match","stem":"앞말과 어울리는 끝말을 알맞게 이으세요.","pairs":[{"l":"아마","r":"~ㄹ 것이다"},{"l":"반드시","r":"~해야 한다"},{"l":"별로","r":"~지 않다"}],"mis":"K5-2-u2-X17","explanation":["짐작이에요.","꼭 해야 함이에요.","부정하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#12','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C21',2,'mc','auto','주어와 서술어의 호응이 자연스러운 문장은 어느 것인가요?',ARRAY['K5-2-u2-X20']::text[],false,'{"seq":12,"concept":"K5-2-u2-C21","difficulty":2,"kind":"mc","stem":"주어와 서술어의 호응이 자연스러운 문장은 어느 것인가요?","options":[{"t":"내가 바라는 것은 모두가 웃는 것이다.","correct":true},{"t":"내가 바라는 것은 모두가 웃었으면 좋겠다.","mis":"K5-2-u2-X20"},{"t":"내 꿈은 화가가 되고 싶다.","mis":"K5-2-u2-X20"},{"t":"내 다짐은 일찍 일어나고 싶다.","mis":"K5-2-u2-X20"}],"explanation":["어울리지 않아요.","어울리지 않아요.","바라는 것은 ~는 것이다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#13','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C14',2,'blank','auto','「할아버지는 안경을 (     ) 신문을 읽으셨다.」에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u2-X12']::text[],false,'{"seq":13,"concept":"K5-2-u2-C14","difficulty":2,"kind":"blank","stem":"「할아버지는 안경을 (     ) 신문을 읽으셨다.」에 알맞은 말은 어느 것인가요?","options":[{"t":"쓰시고","correct":true},{"t":"신으시고","mis":"K5-2-u2-X12"},{"t":"두르시고","mis":"K5-2-u2-X12"},{"t":"빚으시고","mis":"K5-2-u2-X12"}],"explanation":["어울리지 않아요.","어울리지 않아요.","안경은 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#14','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C29',2,'ox','auto','매체를 고를 때에는 읽을 사람과 상황을 생각해야 해요.',ARRAY['K5-2-u2-X28']::text[],false,'{"seq":14,"concept":"K5-2-u2-C29","difficulty":2,"kind":"ox","stem":"매체를 고를 때에는 읽을 사람과 상황을 생각해야 해요.","answer":"O","reason_options":[{"t":"같은 내용도 누구에게 어떤 상황에서 전하는지에 따라 알맞은 매체가 다르기 때문에","correct":true},{"t":"가장 새로운 매체가 언제나 가장 알맞기 때문에","mis":"K5-2-u2-X28"}],"mis":"K5-2-u2-X28","explanation":["읽을 사람을 봐요.","상황을 봐요.","늘 좋은 매체는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#15','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C26',2,'match','auto','경험 글의 짜임과 들어갈 내용을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K5-2-u2-C26","difficulty":2,"kind":"match","stem":"경험 글의 짜임과 들어갈 내용을 이으세요.","pairs":[{"l":"처음","r":"언제 · 어디서 · 누구와"},{"l":"가운데","r":"일어난 일과 생각 · 느낌"},{"l":"끝","r":"배운 점과 다짐"}],"mis":"K5-2-u2-X25","explanation":["소개해요.","자세히 써요.","돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#16','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C44',2,'ox','auto','모르는 사람이 계속 메시지를 보내면 어른께 알리지 말고 혼자 참아야 해요.',ARRAY['K5-2-u2-X39']::text[],false,'{"seq":16,"concept":"K5-2-u2-C44","difficulty":2,"kind":"ox","stem":"모르는 사람이 계속 메시지를 보내면 어른께 알리지 말고 혼자 참아야 해요.","answer":"X","reason_options":[{"t":"이상한 메시지는 부모님이나 선생님께 알려 도움을 받아야 하기 때문에","correct":true},{"t":"어른께 알리면 혼날 수 있기 때문에","mis":"K5-2-u2-X39"}],"mis":"K5-2-u2-X39","explanation":["혼자 참지 않아요.","어른께 알려요.","도움을 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#17','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C22',3,'error','auto','「우리 고양이는 목욕을 별로 좋아한다.」를 두고 나눈 말이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X15','K5-2-u2-X21']::text[],false,'{"seq":17,"concept":"K5-2-u2-C22","difficulty":3,"kind":"error","stem":"「우리 고양이는 목욕을 별로 좋아한다.」를 두고 나눈 말이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「‘좋아한다’를 ‘좋아했다’로 바꾸면 돼.」","correct":true,"mis_target":"K5-2-u2-X15"},{"t":"「‘좋아하지 않는다’로 고치면 ‘별로’와 어울려.」","mis":"K5-2-u2-X21"},{"t":"「어색한 까닭은 ‘별로’ 뒤에 부정하는 말이 없어서야.」","mis":"K5-2-u2-X21"}],"explanation":["알맞게 고쳤어요.","까닭을 말했어요.","때를 바꿔도 여전히 어색해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#18','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C27',3,'error','auto','「고구마 캔 날」을 고쳐 쓰려는 계획이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X26','K5-2-u2-X21']::text[],false,'{"seq":18,"concept":"K5-2-u2-C27","difficulty":3,"kind":"error","stem":"「고구마 캔 날」을 고쳐 쓰려는 계획이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「맞춤법이 다 맞으니 고칠 곳이 없어.」","correct":true,"mis_target":"K5-2-u2-X26"},{"t":"「선생님이 주어인 문장은 높임 표현으로 고칠래.」","mis":"K5-2-u2-X21"},{"t":"「‘여간’ 뒤에는 부정하는 말을 넣을래.」","mis":"K5-2-u2-X21"}],"explanation":["알맞은 계획이에요.","알맞은 계획이에요.","맞춤법만이 고쳐쓰기가 아니에요."],"asset":{"type":"passage","lines":["지난주 금요일, 우리 반은 학교 텃밭에서 고구마를 캤다.","선생님이 호미 쓰는 법을 알려 주었다.","나는 호미와 장갑을 끼고 흙을 팠다.","고구마가 생각보다 커서 여간 놀랐다.","다음 주에는 고구마로 간식을 만들었다."],"title":"경험을 쓴 글 「고구마 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#19','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C33',3,'mc','auto','학급 누리집에 글을 올릴 때 누가 썼는지 밝히는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u2-X31','K5-2-u2-X33']::text[],false,'{"seq":19,"concept":"K5-2-u2-C33","difficulty":3,"kind":"mc","stem":"학급 누리집에 글을 올릴 때 누가 썼는지 밝히는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누가 쓴 글인지 알아야 책임 있게 의견을 주고받을 수 있어서","correct":true},{"t":"이름을 쓰면 글이 길어 보여서","mis":"K5-2-u2-X31"},{"t":"익명이면 아무 말이나 해도 되니까","mis":"K5-2-u2-X31"},{"t":"이름이 있으면 출처를 안 밝혀도 돼서","mis":"K5-2-u2-X33"}],"explanation":["길이와 관계없어요.","익명이어도 예의를 지켜요.","출처는 따로 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#20','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C34',3,'mc','auto','초안을 학급 누리집 글답게 바꾸려면 무엇을 더해야 할까요?',ARRAY['K5-2-u2-X32','K5-2-u2-X33','K5-2-u2-X29']::text[],false,'{"seq":20,"concept":"K5-2-u2-C34","difficulty":3,"kind":"mc","stem":"초안을 학급 누리집 글답게 바꾸려면 무엇을 더해야 할까요?","options":[{"t":"반 친구들에게 의견을 묻고 댓글 참여를 안내하는 말","correct":true},{"t":"더 자극적인 제목","mis":"K5-2-u2-X32"},{"t":"출처를 지운 그림","mis":"K5-2-u2-X33"},{"t":"나만 아는 줄임말","mis":"K5-2-u2-X29"}],"explanation":["제목은 고쳐야 해요.","출처를 밝혀요.","함께 정하자는 글이에요."],"asset":{"type":"passage","lines":["〔제목〕 충격!!! 우리 반 큰일 났다","요즘 교실 책꽂이에 다 읽은 책만 꽂혀 있어 별로 재미있다.","그래서 집에 있는 책을 바꿔 읽는 상자를 만들면 좋겠다.","인터넷에서 본 그림을 그대로 붙였다. 〔그림〕","끝."],"title":"학급 누리집에 올릴 글 초안 「책 바꿔 읽기 상자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#21','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C41',3,'error','auto','칭찬 댓글을 쓰려는 친구들의 생각이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u2-X35','K5-2-u2-X36']::text[],false,'{"seq":21,"concept":"K5-2-u2-C41","difficulty":3,"kind":"error","stem":"칭찬 댓글을 쓰려는 친구들의 생각이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「칭찬할 곳을 못 찾겠으니 ‘좋아요’만 쓰고 끝낼래.」","correct":true,"mis_target":"K5-2-u2-X35"},{"t":"「제목이 궁금증을 불러일으켜서 좋았다고 쓸래.」","mis":"K5-2-u2-X36"},{"t":"「사진과 설명이 잘 어울린 점을 칭찬할래.」","mis":"K5-2-u2-X36"}],"explanation":["근거가 있어요.","근거가 있어요.","네 가지 눈으로 다시 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#22','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C27',3,'ox','auto','고쳐쓰기를 할 때에는 맞춤법만 바르게 고치면 돼요.',ARRAY['K5-2-u2-X26']::text[],false,'{"seq":22,"concept":"K5-2-u2-C27","difficulty":3,"kind":"ox","stem":"고쳐쓰기를 할 때에는 맞춤법만 바르게 고치면 돼요.","answer":"X","reason_options":[{"t":"빠진 말 · 겹친 말 · 어울리지 않는 말과 생생함까지 살펴야 하기 때문에","correct":true},{"t":"내용은 처음 쓴 그대로 두는 것이 좋기 때문에","mis":"K5-2-u2-X26"}],"mis":"K5-2-u2-X26","explanation":["맞춤법만이 아니에요.","내용도 살펴요.","세 가지 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#23','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C8',4,'essay','teacher','서술어 「넣다」나 「드리다」 가운데 하나를 골라 꼭 필요한 말을 모두 갖춘 문장을 쓰고, 그 말이 빠지면 무엇을 알 수 없는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u2-C8","difficulty":4,"kind":"essay","stem":"서술어 「넣다」나 「드리다」 가운데 하나를 골라 꼭 필요한 말을 모두 갖춘 문장을 쓰고, 그 말이 빠지면 무엇을 알 수 없는지 쓰세요.","answer_guide":{"answer":"예: 「나는 할아버지께 손수 만든 카드를 드렸다.」 「드리다」에는 누가 · 무엇을 · 누구에게가 꼭 있어야 한다. 「할아버지께」가 빠지면 카드를 누구에게 드렸는지 알 수 없고, 「카드를」이 빠지면 무엇을 드렸는지 알 수 없다.","scoring_points":["서술어를 골라 문장을 썼는가","꼭 필요한 말을 모두 갖추었는가","빠지면 알 수 없는 것을 썼는가"]},"explanation":["서술어를 골라요.","필요한 말을 갖춰요.","빠지면 어떤지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#24','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C44',4,'essay','teacher','모르는 계정이 사진이나 주소를 달라고 할 때 할 수 있는 말 두 가지를 쓰고, 그다음에 해야 할 행동을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u2-C44","difficulty":4,"kind":"essay","stem":"모르는 계정이 사진이나 주소를 달라고 할 때 할 수 있는 말 두 가지를 쓰고, 그다음에 해야 할 행동을 쓰세요.","answer_guide":{"answer":"예: 「미안하지만 개인 정보는 온라인에서 보내지 않아.」 「부모님께 먼저 여쭤봐야 해.」 그다음에는 더 답하지 않고, 메시지를 지우지 말고 부모님이나 선생님께 보여 드려 도움을 받는다.","scoring_points":["거절하는 말 두 가지를 썼는가","정중하지만 분명한 말인가","어른께 알리는 행동을 썼는가"]},"explanation":["거절하는 말을 써요.","분명히 말해요.","어른께 알려요."],"asset":{"type":"speech","turns":[{"who":"이름 없는 계정","text":"너 ○○초 다니지? 집 주소 좀 알려 줘."},{"who":"소희","text":"미안하지만 개인 정보는 온라인에서 보내지 않기로 했어."},{"who":"이름 없는 계정","text":"사진 한 장만 보내 주면 선물 줄게."},{"who":"소희","text":"부모님께 먼저 여쭤봐야 해. 더는 답하지 않을게."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u2_review_d#25','kor',5,2,'u2','','g5_2_kor_u2_review_d','unit_review','K5-2-u2-C28',4,'essay','teacher','이 단원에서 한 활동(문장 고치기 · 경험 글 · 매체 글 · 칭찬 댓글) 가운데 가장 기억에 남는 활동을 고르고, 배운 점과 앞으로 글을 쓸 때 해 볼 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u2-C28","difficulty":4,"kind":"essay","stem":"이 단원에서 한 활동(문장 고치기 · 경험 글 · 매체 글 · 칭찬 댓글) 가운데 가장 기억에 남는 활동을 고르고, 배운 점과 앞으로 글을 쓸 때 해 볼 일을 쓰세요.","answer_guide":{"answer":"예: 친구 경험 글을 읽고 공감한 부분을 말해 준 활동이 가장 기억에 남는다. 친구가 내 글의 연 장면에서 자기도 마음이 철렁했다고 말해 주어 내 글이 다른 사람에게 전해진다는 것을 느꼈다. 앞으로 글을 쓸 때에는 읽을 사람을 먼저 정하고, 다 쓴 뒤 호응이 맞는지 소리 내어 읽어 보겠다.","scoring_points":["활동을 하나 골랐는가","배운 점을 썼는가","앞으로 해 볼 일을 썼는가"]},"explanation":["활동을 떠올려요.","배운 점을 써요.","다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
